function venueCapitalWeightDefaults() {
  let parsed = {};
  try {
    const raw = String(process.env.NEXUS_VENUE_CAPITAL_WEIGHTS || '').trim();
    if (raw) {
      if (raw.startsWith('{')) parsed = JSON.parse(raw);
      else {
        for (const item of raw.split(',')) {
          const [venue, value] = item.split(':').map(x => String(x || '').trim());
          if (venue && Number.isFinite(Number(value))) parsed[venue.toLowerCase()] = Number(value);
        }
      }
    }
  } catch {}
  for (const venue of VENUES) {
    const envKey = `NEXUS_${venue.toUpperCase()}_CAPITAL_WEIGHT`;
    if (process.env[envKey] !== undefined && Number.isFinite(Number(process.env[envKey]))) parsed[venue] = Number(process.env[envKey]);
  }
  const total = VENUES.reduce((sum, venue) => sum + Math.max(0, Number(parsed[venue] || 0)), 0);
  if (!(total > 0)) return Object.fromEntries(VENUES.map(venue => [venue, Number((1 / VENUES.length).toFixed(6))]));
  return Object.fromEntries(VENUES.map(venue => [venue, Number((Math.max(0, Number(parsed[venue] || 0)) / total).toFixed(6))]));
}

