    tradeFlowProtection: LEARNING_GUARD_TRADE_FLOW_PROTECTION,
    activityMode: LEARNING_GUARD_TRADE_FLOW_PROTECTION ? 'aktivitás-tartó tanulás' : 'quality-filter',
    sizingPolicy: 'gyengébb setup = kisebb méret, nem automatikus trade-stop',
    adaptiveConfidenceLift: 0,
    calibrationLift: 0,
    targetGapLift: 0,
    lossStreakLift: 0,
    currentWinRate: null,
    sampleCount: 0,
    healthScore: 100,
    actionLabel: 'Tanulási guard még nem futott.',
    preferredSymbols: [],
    preferredSides: [],
    preferredStrategies: [],
