function integrityVersionNumber(value) {
  const m = String(value || '').match(/v199[_-](\d+)/i);
  return m ? Number(m[1]) : 0;
}

function booleanTrue(value) {
  if (value === true || value === 1) return true;
  return ['true', '1', 'yes', 'on', 'ok', 'verified', 'trusted'].includes(String(value ?? '').trim().toLowerCase());
}

function canonicalMarketVenue(value) {
  return normalizeVenue(value) || String(value || '').trim().toLowerCase();
}

function snapshotMatchesMarketBinding(snapshot = {}, venue = '', symbol = '') {
  if (!snapshot || typeof snapshot !== 'object') return false;
  const expectedSymbol = normalizeSymbol(symbol || snapshot.symbol || '');
  const actualSymbol = normalizeSymbol(snapshot.symbol || snapshot.rawSymbol || '');
  const expectedVenue = canonicalMarketVenue(venue || snapshot.venueKey || snapshot.venue);
  const actualVenue = canonicalMarketVenue(snapshot.venueKey || snapshot.venue);
  return !!expectedSymbol && expectedSymbol === actualSymbol && (!expectedVenue || !actualVenue || expectedVenue === actualVenue);
}

function tradeSymbolPriceIntegrity(trade = {}) {
  const statusText = [trade.status, trade.quarantineReason, trade.integrityStatus, trade.journalStatus]
    .map(value => String(value || '').toLowerCase()).join(' ');
  if (trade.quarantined === true || /quarantin|cross[_ -]?symbol|symbol[_ -]?price[_ -]?mismatch/.test(statusText)) {
    return { ok: false, reason: trade.quarantineReason || 'explicitly-quarantined', explicit: true, bindingVerified: false };
  }
  const symbol = normalizeSymbol(trade.symbol || trade.marketSymbol || '');
  const venue = canonicalMarketVenue(trade.venue || trade.marketVenue || '');
  const entrySymbols = uniqueNonEmpty([
    trade.entryMarketSymbol,
    trade.entrySnapshotSymbol,
    trade.entryMarketSnapshot?.symbol,
    trade.marketSnapshotAtEntry?.symbol,
    trade.marketSnapshot?.symbol,
    trade.signalMarketSymbol
  ]).map(normalizeSymbol);
  const exitSymbols = uniqueNonEmpty([
    trade.exitMarketSymbol,
    trade.exitSnapshotSymbol,
    trade.exitMarketSnapshot?.symbol,
    trade.marketSnapshotAtExit?.symbol,
    trade.reconcileMarketSnapshot?.symbol
  ]).map(normalizeSymbol);
  const entryVenues = uniqueNonEmpty([
    trade.entryMarketVenue,
    trade.entrySnapshotVenue,
    trade.entryMarketSnapshot?.venueKey,
    trade.entryMarketSnapshot?.venue,
    trade.marketSnapshotAtEntry?.venueKey,
    trade.marketSnapshotAtEntry?.venue,
    trade.marketSnapshot?.venueKey,
    trade.marketSnapshot?.venue
  ]).map(canonicalMarketVenue);
  const exitVenues = uniqueNonEmpty([
    trade.exitMarketVenue,
    trade.exitSnapshotVenue,
    trade.exitMarketSnapshot?.venueKey,
    trade.exitMarketSnapshot?.venue,
    trade.marketSnapshotAtExit?.venueKey,
    trade.marketSnapshotAtExit?.venue,
    trade.reconcileMarketSnapshot?.venueKey,
    trade.reconcileMarketSnapshot?.venue
  ]).map(canonicalMarketVenue);
  const symbolMismatch = !!symbol && [...entrySymbols, ...exitSymbols].some(item => item && item !== symbol);
  const venueMismatch = !!venue && [...entryVenues, ...exitVenues].some(item => item && item !== venue);
  const entrySourceVenue = canonicalMarketVenue(trade.entryMarketSourceVenue || trade.marketSnapshotAtEntry?.marketSourceVenue || trade.entryMarketSnapshot?.marketSourceVenue || '');
  const exitSourceVenue = canonicalMarketVenue(trade.exitMarketSourceVenue || trade.marketSnapshotAtExit?.marketSourceVenue || trade.exitMarketSnapshot?.marketSourceVenue || '');
  const sourceVenueMismatch = integrityVersionNumber(trade.journalIntegrityVersion || trade.marketIntegrityVersion || trade.epochVersion || trade.strategyVersion) >= 147
    && !!entrySourceVenue && !!exitSourceVenue && entrySourceVenue !== exitSourceVenue;
  if (symbolMismatch || venueMismatch || sourceVenueMismatch) {
    return {
      ok: false,
      reason: symbolMismatch ? 'market-snapshot-symbol-mismatch' : venueMismatch ? 'market-snapshot-venue-mismatch' : 'market-source-venue-mismatch',
      symbol,
      venue,
      entrySymbols,
      exitSymbols,
      entryVenues,
      exitVenues,
      entrySourceVenue,
      exitSourceVenue,
      bindingVerified: false
    };
  }

  const entry = finiteNumber(trade.entryPrice ?? trade.openPrice ?? trade.avgEntryPrice, 0);
  const exit = finiteNumber(trade.exitPrice ?? trade.closePrice ?? trade.avgExitPrice, 0);
  const version = Math.max(
    integrityVersionNumber(trade.journalIntegrityVersion || trade.marketIntegrityVersion || trade.epochVersion),
    integrityVersionNumber(trade.strategyVersion)
  );
  const openedMs = Date.parse(trade.openedAt || trade.entryTime || trade.time || '');
  const closedMs = Date.parse(trade.closedAt || trade.exitTime || trade.created_at || '');
  const derivedHoldingMs = Number.isFinite(openedMs) && Number.isFinite(closedMs) && closedMs >= openedMs ? closedMs - openedMs : 0;
  const holdingMs = Math.max(0, finiteNumber(trade.holdingMs, derivedHoldingMs));
  const absMovePct = entry > 0 && exit > 0 ? Math.abs(exit / entry - 1) * 100 : 0;
  let maxPlausibleMovePct = Infinity;
  if (version >= 141) {
    if (holdingMs <= 15 * 60 * 1000 || holdingMs === 0) maxPlausibleMovePct = 12;
    else if (holdingMs <= 60 * 60 * 1000) maxPlausibleMovePct = 20;
    else if (holdingMs <= 6 * 60 * 60 * 1000) maxPlausibleMovePct = 40;
    else if (holdingMs <= 24 * 60 * 60 * 1000) maxPlausibleMovePct = 70;
  }
  if (Number.isFinite(maxPlausibleMovePct) && absMovePct > maxPlausibleMovePct) {
    return {
      ok: false,
      reason: 'implausible-cross-symbol-price-move',
      symbol,
      venue,
      entry,
      exit,
      absMovePct: Number(absMovePct.toFixed(4)),
      maxPlausibleMovePct,
      holdingMs,
      version,
      bindingVerified: entrySymbols.length > 0 || exitSymbols.length > 0
    };
  }
  return {
    ok: true,
    reason: 'symbol-price-integrity-ok',
    symbol,
    venue,
    entry,
    exit,
    absMovePct: Number(absMovePct.toFixed(4)),
    holdingMs,
    version,
    bindingVerified: !!symbol && (entrySymbols.length > 0 || exitSymbols.length > 0) && !symbolMismatch && !venueMismatch
  };
}

function orderSymbolPriceIntegrity(order = {}, latest = null) {
  const symbol = normalizeSymbol(order.symbol || '');
  const venue = canonicalMarketVenue(order.venue || '');
  const snapshots = [order.marketSnapshot, order.entryMarketSnapshot, order.reconcileMarketSnapshot].filter(Boolean);
  for (const snapshot of snapshots) {
    if (!snapshotMatchesMarketBinding(snapshot, venue, symbol)) {
      return { ok: false, reason: 'order-market-snapshot-binding-mismatch', symbol, venue, snapshotSymbol: normalizeSymbol(snapshot.symbol || ''), snapshotVenue: canonicalMarketVenue(snapshot.venueKey || snapshot.venue) };
    }
  }
  if (latest && !snapshotMatchesMarketBinding(latest, venue, symbol)) {
    return { ok: false, reason: 'reconcile-market-snapshot-binding-mismatch', symbol, venue, snapshotSymbol: normalizeSymbol(latest.symbol || ''), snapshotVenue: canonicalMarketVenue(latest.venueKey || latest.venue) };
  }
  const entrySourceVenue = canonicalMarketVenue(order.marketSourceVenue || order.entryMarketSourceVenue || order.marketSnapshot?.marketSourceVenue || order.entryMarketSnapshot?.marketSourceVenue || '');
  const latestSourceVenue = latest ? canonicalMarketVenue(latest.marketSourceVenue || latest.venueKey || latest.venue || '') : '';
  if (latest && entrySourceVenue && latestSourceVenue && entrySourceVenue !== latestSourceVenue) {
    return { ok: false, reason: 'order-market-source-venue-mismatch', symbol, venue, entrySourceVenue, latestSourceVenue, bindingVerified: false };
  }
  const entry = finiteNumber(order.entryPrice, 0);
  const reference = finiteNumber(latest?.price ?? latest?.mid ?? latest?.bid ?? latest?.ask, 0);
  const holdingMs = Math.max(0, Date.now() - (Date.parse(order.submittedAt || order.time || '') || Date.now()));
  const absMovePct = entry > 0 && reference > 0 ? Math.abs(reference / entry - 1) * 100 : 0;
  const maxPlausibleMovePct = holdingMs <= 15 * 60 * 1000 ? 12 : holdingMs <= 60 * 60 * 1000 ? 20 : 40;
  if (entry > 0 && reference > 0 && absMovePct > maxPlausibleMovePct) {
    return { ok: false, reason: 'order-entry-price-incompatible-with-bound-symbol', symbol, venue, entry, reference, absMovePct: Number(absMovePct.toFixed(4)), maxPlausibleMovePct, holdingMs };
  }
  return { ok: true, reason: 'order-symbol-price-integrity-ok', symbol, venue, entry, reference, absMovePct: Number(absMovePct.toFixed(4)), holdingMs };
}

function quarantineTradeRecord(trade = {}, finding = {}, reason = 'symbol-price-integrity-repair') {
  trade.quarantined = true;
  trade.learningEligible = false;
  trade.verifiedEligible = false;
  trade.originalStatus = trade.originalStatus || trade.status || 'closed';
  trade.status = 'quarantined_symbol_price_mismatch';
  trade.integrityStatus = 'quarantined';
  trade.quarantinedAt = trade.quarantinedAt || now();
  trade.quarantineReason = finding.reason || reason;
  trade.integrityFinding = { ...finding, repairedAt: now(), repairReason: reason };
  return trade;
}

function quarantineOrderRecord(order = {}, finding = {}, reason = 'symbol-price-integrity-repair') {
  ensureOrderLifecycle(order, reason);
  order.originalStatus = order.originalStatus || order.status || '';
  order.status = 'quarantined_symbol_price_mismatch';
  order.quarantinedAt = order.quarantinedAt || now();
  order.quarantineReason = finding.reason || reason;
  order.integrityFinding = { ...finding, repairedAt: now(), repairReason: reason };
  addLifecycleStep(order, 'LEGACY_QUARANTINED', reason);
  order.currentStep = 'LEGACY_QUARANTINED';
  return order;
}


function integrityTradeKey(trade = {}) {
  const direct = String(trade.id || trade.orderId || trade.order_id || '').trim();
  if (direct) return direct;
  const fingerprint = [trade.venue, trade.symbol, trade.side, trade.entryPrice, trade.exitPrice, trade.openedAt || trade.entryTime, trade.closedAt || trade.exitTime || trade.time]
    .map(value => String(value ?? '')).join('|');
  return fingerprint ? crypto.createHash('sha1').update(fingerprint).digest('hex') : '';
}

function correctAggregateForIntegrityQuarantine(state = db, quarantinedRecords = [], reason = 'symbol-price-integrity-correction') {
  state.marketIntegrity = deepMerge(marketIntegrityDefaults(), state.marketIntegrity || {});
  const integrity = state.marketIntegrity.symbolPriceIntegrity || {};
  const correctedIds = new Set(asArray(integrity.correctedTradeIds).map(String));
  const newlyCorrected = [];
  for (const trade of asArray(quarantinedRecords)) {
    const key = integrityTradeKey(trade);
    if (!key || correctedIds.has(key)) continue;
    correctedIds.add(key);
    newlyCorrected.push(trade);
  }
  if (!newlyCorrected.length) return { corrected: 0, aggregate: state.aggregateStats, records: [] };

  const current = normalizeAggregateCandidate(state.aggregateStats, reason) || aggregateStatsDefaults();
  let closedTrades = Math.max(0, Number(current.closedTrades || 0));
  let wins = Math.max(0, Number(current.wins || 0));
  let losses = Math.max(0, Number(current.losses || Math.max(0, closedTrades - wins)));
  let netPnl = Number(current.netPnl || 0);
  let grossPnl = Number(current.grossPnl || 0);
  let fees = Number(current.fees || 0);
  let weeklyProfit = Number(current.weeklyProfit || 0);
  let correctedNetPnlUsd = 0;
  const week = currentWeekKey();
  const ids = new Set();

  for (const trade of newlyCorrected) {
    const key = integrityTradeKey(trade);
    if (key) ids.add(key);
    const pnl = finiteNumber(trade.netPnl, 0);
    const gross = finiteNumber(trade.grossPnl, 0);
    const cost = finiteNumber(trade.fee, 0) + finiteNumber(trade.slippage, 0);
    if (closedTrades > 0) closedTrades -= 1;
    if (pnl > 0 && wins > 0) wins -= 1;
    else if (pnl <= 0 && losses > 0) losses -= 1;
    netPnl -= pnl;
    grossPnl -= gross;
    fees -= cost;
    correctedNetPnlUsd -= pnl;
    if (currentWeekKey(new Date(trade.closedAt || trade.time || Date.now())) === week) weeklyProfit -= pnl;
  }
  losses = Math.max(0, Math.min(closedTrades, losses));
  wins = Math.max(0, Math.min(closedTrades, wins));
  if (wins + losses !== closedTrades) losses = Math.max(0, closedTrades - wins);
  const startingEquity = Number(state.paperAccount?.startingEquity || state.capital?.initialCapital || process.env.NEXUS_INITIAL_CAPITAL || 10000);
  const curve = asArray(current.equityCurve).filter(point => !ids.has(String(point.orderId || point.tradeId || point.id || '')));
  const corrected = {
    ...current,
    status: 'ready',
    source: `${current.source || 'aggregate'}+symbol-price-integrity-corrected`,
    complete: current.complete !== false,
    closedTrades,
    wins,
    losses,
    winRate: closedTrades ? Number((wins / closedTrades * 100).toFixed(1)) : null,
    netPnl: Number(netPnl.toFixed(4)),
    grossPnl: Number(grossPnl.toFixed(4)),
    fees: Number(Math.max(0, fees).toFixed(4)),
    weeklyProfit: Number(weeklyProfit.toFixed(4)),
    equity: Number((startingEquity + netPnl).toFixed(4)),
    equityCurve: curve.slice(-140),
    lastUpdatedAt: now(),
    monotonicProtection: {
      active: false,
      integrityCorrection: true,
      reason,
      previousClosedTrades: Number(current.closedTrades || 0),
      correctedClosedTrades: closedTrades,
      quarantinedTrades: newlyCorrected.length,
      correctedTradeIds: [...ids]
    },
    note: `${newlyCorrected.length} bizonyított cross-symbol/ár-integritási rekord egyszeri korrekcióval kivonva a teljes számlálóból, winrate-ből, PnL-ből és heti profitból.`
  };
  state.aggregateStats = corrected;
  state.marketIntegrity.symbolPriceIntegrity = {
    ...integrity,
    correctedTradeIds: [...correctedIds].slice(-1000),
    correctedAggregateAt: now(),
    correctedNetPnlUsd: Number((Number(integrity.correctedNetPnlUsd || 0) + correctedNetPnlUsd).toFixed(4))
  };
  return { corrected: newlyCorrected.length, aggregate: corrected, records: newlyCorrected, correctedNetPnlUsd: Number(correctedNetPnlUsd.toFixed(4)) };
}


function repairClosedPaperPositions(state = db, reason = 'closed-paper-position-repair') {
  const positions = state.positions && typeof state.positions === 'object' ? state.positions : {};
  const activeKeys = new Set(asArray(state.orders)
    .filter(isActiveOrder)
    .map(order => `${canonicalMarketVenue(order.venue)}:${normalizeSymbol(order.symbol)}`));
  let repaired = 0;
  for (const [key, position] of Object.entries(positions)) {
    if (!position || typeof position !== 'object') continue;
    const bindingKey = `${canonicalMarketVenue(position.venue || String(key).split(':')[0])}:${normalizeSymbol(position.symbol || String(key).split(':').slice(1).join(':'))}`;
    if (activeKeys.has(bindingKey)) continue;
    if (Math.abs(finiteNumber(position.qty, 0)) <= 0 && String(position.status || '').toLowerCase() === 'flat') continue;
    position.lastRepairedQty = finiteNumber(position.qty, 0);
    position.qty = 0;
    position.avgPrice = 0;
    position.status = 'flat';
    position.repairedAt = now();
    position.repairReason = reason;
    repaired += 1;
  }
  return { repaired, activePositions: activeKeys.size };
}

function repairSymbolPriceIntegrityState(state = db, reason = 'runtime-integrity-repair') {
  state.marketIntegrity = deepMerge(marketIntegrityDefaults(), state.marketIntegrity || {});
  const findings = [];
  let checkedTrades = 0;
  let checkedOrders = 0;
  let quarantinedTrades = 0;
  let quarantinedOrders = 0;
  const quarantinedTradeRecords = [];
  for (const trade of asArray(state.tradeJournal)) {
    checkedTrades += 1;
    const finding = tradeSymbolPriceIntegrity(trade);
    if (finding.ok || finding.explicit) continue;
    quarantineTradeRecord(trade, finding, reason);
    quarantinedTrades += 1;
    quarantinedTradeRecords.push(trade);
    findings.push({ type: 'trade', id: trade.id || trade.orderId || '', symbol: trade.symbol || '', reason: finding.reason, absMovePct: finding.absMovePct ?? null, netPnl: finiteNumber(trade.netPnl, 0) });
  }
  for (const order of asArray(state.orders)) {
    checkedOrders += 1;
    if (!isActiveOrder(order)) continue;
    const finding = orderSymbolPriceIntegrity(order, null);
    if (finding.ok) continue;
    quarantineOrderRecord(order, finding, reason);
    quarantinedOrders += 1;
    findings.push({ type: 'order', id: order.id || '', symbol: order.symbol || '', reason: finding.reason, absMovePct: finding.absMovePct ?? null });
  }
  const previous = state.marketIntegrity.symbolPriceIntegrity || {};
  state.marketIntegrity.symbolPriceIntegrity = {
    ...previous,
    status: quarantinedTrades || quarantinedOrders || asArray(previous.correctedTradeIds).length || Number(previous.quarantinedTrades || 0) > 0
      ? 'repaired-quarantine-active'
      : 'ok',
    checkedTrades,
    checkedOrders,
    quarantinedTrades: Math.max(Number(previous.quarantinedTrades || 0), Number(state.marketIntegrity.quarantinedTrades || 0), quarantinedTrades),
    quarantinedOrders: Math.max(Number(previous.quarantinedOrders || 0), Number(state.marketIntegrity.quarantinedOrders || 0), quarantinedOrders),
    lastRunAt: now(),
    lastReason: reason,
    recentFindings: [...findings, ...asArray(previous.recentFindings)].slice(0, 30),
    policy: 'symbol-venue-snapshot-bound-entry-exit-and-cross-symbol-price-anomaly-quarantine'
  };
  state.marketIntegrity.quarantinedTrades = Math.max(Number(state.marketIntegrity.quarantinedTrades || 0), quarantinedTrades);
  state.marketIntegrity.quarantinedOrders = Math.max(Number(state.marketIntegrity.quarantinedOrders || 0), quarantinedOrders);
  if (quarantinedTrades || quarantinedOrders) state.marketIntegrity.lastQuarantineAt = now();
  return { checkedTrades, checkedOrders, quarantinedTrades, quarantinedOrders, findings, quarantinedTradeRecords };
}

function verifiedMarketTradeEvidence(trade = {}) {
  const version = integrityVersionNumber(trade.journalIntegrityVersion || trade.marketIntegrityVersion || trade.epochVersion);
  const versionOk = version >= 131;
  const trusted = [
    trade.marketDataTrusted,
    trade.entryMarketDataTrusted,
    trade.marketSnapshot?.marketDataTrusted,
    trade.marketDataQuality?.learningTrusted,
    trade.marketSnapshot?.marketDataQuality?.learningTrusted
  ].some(booleanTrue);
  const sourceCandidates = [
    trade.priceSource,
    trade.marketSource,
    trade.entryPriceSource,
    trade.exitPriceSource,
    trade.marketSnapshot?.source,
    trade.marketSnapshot?.priceSource,
    trade.entryMarketSnapshot?.source,
    trade.exitMarketSnapshot?.source
  ].map(value => String(value || '').trim().toLowerCase()).filter(Boolean);
  const transportCandidates = [
    trade.marketTransport,
    trade.entryMarketTransport,
    trade.exitMarketTransport,
    trade.marketSnapshot?.marketTransport,
    trade.marketSnapshot?.transport,
    trade.entryMarketSnapshot?.marketTransport,
    trade.exitMarketSnapshot?.marketTransport
  ].map(value => String(value || '').trim().toLowerCase()).filter(Boolean);
  const sourceOk = sourceCandidates.some(source => ['live_public', 'live-public', 'public_live', 'public-live'].includes(source));
  const transportOk = transportCandidates.some(transport => ['websocket', 'ws', 'rest', 'rest-cross-venue', 'worker-rest-ipv4'].includes(transport));
  const entryPrice = finiteNumber(trade.entryPrice ?? trade.openPrice ?? trade.avgEntryPrice, 0);
  const exitPrice = finiteNumber(trade.exitPrice ?? trade.closePrice ?? trade.avgExitPrice, 0);
  const pricesOk = entryPrice > 0 && exitPrice > 0;
  const symbolPriceIntegrity = tradeSymbolPriceIntegrity(trade);
  const provenance = [
    trade.source,
    trade.proofSource,
    trade.fillState,
    trade.status,
    trade.journalStatus,
    ...asArray(trade.lifecycle)
  ].map(value => String(value || '')).join(' ').toLowerCase();
  // v199_137/v199_138 kompatibilitás: néhány Supabase journal sorban a
  // priceSource mező elveszett, miközben a trusted flag, a REST/WS transport,
  // az érvényes árak és a PAPER + PROOF provenance megmaradt. Ezeket szigorú
  // bizonyítéklánccal visszaállítjuk, de régi pre-epoch rekordot nem emelünk át.
  const recoveryProof = version >= 137 && (
    /paper\s*\+\s*proof|verified[ _-]?market|fresh[ _-]?market|journal[ _-]?saved/.test(provenance)
    || booleanTrue(trade.verifiedMarketEpoch)
    || booleanTrue(trade.marketProofVerified)
    || booleanTrue(trade.publicMarketProof)
  );
  const strict = versionOk && trusted && sourceOk && transportOk && pricesOk && symbolPriceIntegrity.ok;
  const recovered = !strict && versionOk && trusted && transportOk && pricesOk && recoveryProof && symbolPriceIntegrity.ok;
  return {
    verified: strict || recovered,
    strict,
    recovered,
    version,
    trusted,
    sourceOk,
    transportOk,
    pricesOk,
    symbolPriceIntegrity,
    sourceCandidates,
    transportCandidates,
    reason: strict ? 'strict-live-public-proof' : (recovered ? 'recovered-v199_137-plus-proof-provenance' : (!symbolPriceIntegrity.ok ? symbolPriceIntegrity.reason : 'verification-evidence-incomplete'))
  };
}

function isVerifiedMarketTrade(trade = {}) {
  if (!tradeClosed(trade)) return false;
  return verifiedMarketTradeEvidence(trade).verified;
}

function isTerminalOrderStatus(status = '') {
  const value = String(status || '').toLowerCase();
  return ['filled', 'rejected', 'cancelled', 'quarantined', 'legacy_closed'].some(x => value.includes(x));
}

function isActiveOrder(order = {}) {
  if (!order || typeof order !== 'object') return false;
  const value = String(order.status || '').toLowerCase();
  if (isTerminalOrderStatus(value)) return false;
  // Live dry-run / proof rekordok bizonyítékok, nem nyitott paper pozíciók.
  // Korábban ezek aktív ordernek számítottak, ezért a createOrder örökre
  // existing_order_waiting állapotban maradt és nem született lezárt trade.
  if (/live_submit_blocked|submit_blocked_dry_run|dry[_ -]?run.*blocked|proof.*saved|execution_proof|not-submitted/.test(value)) return false;
  if (String(order.fillState || '').toLowerCase() === 'not-submitted' && /live|proof|dry/.test(value + ' ' + String(order.source || ''))) return false;
  return true;
}

function orderHasVerifiedMarketEntry(order = {}) {
  const versionOk = integrityVersionNumber(order.marketIntegrityVersion) >= 131;
  const quality = order.marketDataQuality || order.marketSnapshot?.marketDataQuality || {};
  const source = String(order.priceSource || order.marketSnapshot?.source || '').toLowerCase();
  const transport = String(order.entryMarketTransport || order.marketSnapshot?.marketTransport || '').toLowerCase();
  return versionOk && order.entryMarketDataTrusted === true && quality.learningTrusted === true && source === 'live_public' && ['websocket', 'rest', 'rest-cross-venue', 'worker-rest-ipv4'].includes(transport);
}

function expireOrphanedPaperPositions(state = db, reason = 'paper-position-orphan-timeout') {
  if (!state || !['paper', 'staging'].includes(String(state.mode || '').toLowerCase())) return { expired: 0, ids: [] };
  const expired = [];
  for (const order of asArray(state.orders)) {
    if (!isActiveOrder(order)) continue;
    // v199_186: do not require perfect lifecycle metadata here. Rehydrated/legacy PAPER/STAGING
    // records can be visibly active and consume a slot even when submittedAt or POSITION_OPENED
    // was lost during persistence. Any active trading record that survives beyond hard-hold + grace
    // is safe to release because this watchdog never fabricates PnL or a learning label.
    const openedMs = Date.parse(order.submittedAt || order.openedAt || order.time || order.createdAt || '');
    if (!Number.isFinite(openedMs)) continue;
    const minHoldMs = Math.max(15000, Number(order.minHoldMs || PAPER_POSITION_MIN_HOLD_MS));
    const softHoldMs = Math.max(minHoldMs, Number(order.softHoldMs || PAPER_POSITION_SOFT_HOLD_MS));
    // v199_185_2: honor the latest effective hard-hold value first. A probe may
    // temporarily extend hardHoldMs beyond baseHardHoldMs during its bounded loss grace.
    const hardHoldMs = Math.max(softHoldMs + 30000, Number(order.hardHoldMs || order.baseHardHoldMs || PAPER_POSITION_MAX_HOLD_MS));
    const holdingMs = Math.max(0, Date.now() - openedMs);
    if (holdingMs < hardHoldMs + PAPER_POSITION_ORPHAN_RELEASE_GRACE_MS) continue;

    const venue = normalizeVenue(order.requestedVenue || order.entryMarketVenue || order.venue) || 'binance';
    const symbol = normalizeSymbol(order.symbol || '');
    const sourceVenue = normalizeVenue(order.marketSourceVenue || order.entryMarketSourceVenue || order.marketSnapshot?.marketSourceVenue || order.entryMarketVenue || venue) || venue;
    const cached = symbol ? latestFreshLivePublicSnapshotFromSource(venue, symbol, sourceVenue, MARKET_SOURCE_CACHE_MAX_AGE_MS) : null;
    const freshSameSourceCache = !!(cached?.snap && marketSnapshotIsFreshTrusted(cached.snap));

    // Never let a PAPER/STAGING slot live forever. If reconcile did not finish within
    // hard hold + grace, release the position without manufacturing a late PnL/training
    // record. Even a fresh cache no longer suppresses this watchdog: repeated reconcile
    // timeouts were able to strand positions for hours while the UI claimed a 90s max.
    order.status = 'cancelled_stale_position_watchdog';
    order.cancelledAt = now();
    order.closeReason = freshSameSourceCache
      ? 'reconcile_missed_hard_hold_with_fresh_cache'
      : 'market_source_unavailable_after_hard_hold';
    order.journalExcluded = true;
    order.learningExcluded = true;
    order.pnlExcluded = true;
    order.orphanRelease = {
      at: order.cancelledAt,
      holdingMs,
      hardHoldMs,
      graceMs: PAPER_POSITION_ORPHAN_RELEASE_GRACE_MS,
      requiredSourceVenue: sourceVenue,
      reason,
      freshSameSourceCache
    };
    addLifecycleStep(order, 'ORDER_CANCELLED_MARKET_TIMEOUT', reason);
    expired.push(order.id || `${venue}:${symbol}`);
    pushEvent('execution', `Beragadt PAPER/STAGING pozíció felszabadítva tanulási/PnL elszámolás nélkül: ${venue.toUpperCase()} ${symbol}.`, {
      orderId: order.id,
      venue,
      symbol,
      holdingMs,
      hardHoldMs,
      graceMs: PAPER_POSITION_ORPHAN_RELEASE_GRACE_MS,
      requiredSourceVenue: sourceVenue,
      freshSameSourceCache,
      source: 'v199_186-shadow-lab-watchdog',
      severity: 'warn'
    });
  }
  if (expired.length) persistSoon('paper-position-orphan-release');
  return { expired: expired.length, ids: expired };
}

function normalizeShadowStrategyLab(state = db) {
  if (!state.shadowStrategyLab || typeof state.shadowStrategyLab !== 'object' || Array.isArray(state.shadowStrategyLab)) {
    state.shadowStrategyLab = shadowStrategyLabDefaults();
  }
  const lab = state.shadowStrategyLab;
  lab.pending = asArray(lab.pending).slice(0, SHADOW_STRATEGY_PENDING_LIMIT);
  lab.results = asArray(lab.results).slice(0, SHADOW_STRATEGY_RESULTS_LIMIT);
  lab.lastSampleByMarket = asObject(lab.lastSampleByMarket, {});
  lab.championSummary = asObject(lab.championSummary, {});
  lab.enabled = SHADOW_STRATEGY_LAB_ENABLED;
  lab.policy = deepMerge(shadowStrategyLabDefaults().policy, asObject(lab.policy, {}));
  return lab;
}

function shadowStrategyLabSummary(state = db) {
  const lab = normalizeShadowStrategyLab(state);
  const byVenue = {};
  for (const venue of VENUES) {
    const venueRows = lab.results.filter(row => normalizeVenue(row.venue) === venue);
    const byRegime = {};
    for (const regime of ['trend-up','trend-down','volatile','ranging','transition','quiet']) {
      const regimeRows = venueRows.filter(row => String(row.regime || 'unknown') === regime);
      if (!regimeRows.length) continue;
      const strategies = {};
      for (const strategy of ['trend','momentum','breakout','mean-reversion','scalp']) {
        const rows = regimeRows.filter(row => String(row.strategy || '') === strategy);
        if (!rows.length) continue;
        const wins = rows.filter(row => Number(row.netPct || 0) > 0).length;
        const grossWin = rows.reduce((sum,row) => sum + Math.max(0, Number(row.netPct || 0)), 0);
        const grossLoss = Math.abs(rows.reduce((sum,row) => sum + Math.min(0, Number(row.netPct || 0)), 0));
        const net = rows.reduce((sum,row) => sum + Number(row.netPct || 0), 0);
        strategies[strategy] = {
          samples: rows.length,
          winRate: Number((wins / rows.length * 100).toFixed(1)),
          expectancyPct: Number((net / rows.length).toFixed(5)),
          profitFactor: Number((grossLoss > 0 ? grossWin / grossLoss : grossWin > 0 ? 3 : 1).toFixed(3))
        };
      }
      const ranking = Object.entries(strategies)
        .map(([strategy, perf]) => ({
          strategy,
          score: Number((50 + (perf.winRate - 50) * 0.35 + (perf.profitFactor - 1) * 12 + clamp(perf.expectancyPct * 100, -15, 15)).toFixed(1)),
          ...perf
        }))
        .sort((a,b) => b.score - a.score);
      byRegime[regime] = {
        samples: regimeRows.length,
        champion: ranking[0] || null,
        challenger: ranking[1] || null,
        ranking
      };
    }
    byVenue[venue] = {
      samples: venueRows.length,
      byRegime
    };
  }
  return {
    enabled: lab.enabled,
    status: lab.enabled ? (lab.totalSettled > 0 ? 'learning-active' : 'warming-up') : 'disabled',
    pending: lab.pending.length,
    results: lab.results.length,
    totalRecorded: Number(lab.totalRecorded || 0),
    totalSettled: Number(lab.totalSettled || 0),
    totalInvalidated: Number(lab.totalInvalidated || 0),
    lastRecordedAt: lab.lastRecordedAt || null,
    lastSettledAt: lab.lastSettledAt || null,
    byVenue,
    policy: lab.policy
  };
}

function maybeRecordShadowStrategyOpportunity(preview = null, reason = 'signal-opportunity') {
  const lab = normalizeShadowStrategyLab(db);
  if (!lab.enabled || !preview || preview.freshTrusted !== true || preview.technical?.ready !== true) return { recorded: 0, reason: 'not-eligible' };
  const venue = normalizeVenue(preview.venue || preview.snapshot?.venueKey || preview.snapshot?.venue || '');
  const symbol = normalizeSymbol(preview.symbol || preview.snapshot?.symbol || '');
  if (!venue || !symbol || !snapshotMatchesMarketBinding(preview.snapshot, venue, symbol) || !marketSnapshotIsFreshTrusted(preview.snapshot)) return { recorded: 0, reason: 'market-not-trusted' };
  const nowMs = Date.now();
  const marketKeyValue = `${venue}:${symbol}`;
  const lastMs = Date.parse(lab.lastSampleByMarket[marketKeyValue] || '');
  if (Number.isFinite(lastMs) && nowMs - lastMs < SHADOW_STRATEGY_SAMPLE_INTERVAL_MS) return { recorded: 0, reason: 'sample-throttle' };
  const fallbackSide = ['BUY','SELL'].includes(String(preview.preValidationCandidateSide || preview.candidateSide || '').toUpperCase())
    ? String(preview.preValidationCandidateSide || preview.candidateSide).toUpperCase()
    : (Number(preview.technical?.momentumScore || 0) >= 0 ? 'BUY' : 'SELL');
  const regime = inferMarketRegime(preview.technical || {}, { volatility: preview.snapshot?.volatility || preview.technical?.volatility, costCoverageRatio: preview.costCoverageRatio });
  const candidates = strategyCandidates(preview.technical || {}, {
    side: fallbackSide,
    costCoverageRatio: preview.costCoverageRatio,
    volatility: preview.snapshot?.volatility || preview.technical?.volatility
  });
  const bid = Number(preview.snapshot?.bid || preview.snapshot?.price || preview.snapshot?.mid || 0);
  const ask = Number(preview.snapshot?.ask || preview.snapshot?.price || preview.snapshot?.mid || 0);
  if (!(bid > 0 && ask > 0)) return { recorded: 0, reason: 'price-missing' };
  const openedAt = now();
  const settleAfterAt = new Date(nowMs + SHADOW_STRATEGY_HORIZON_MS).toISOString();
  const rows = [];
  for (const candidate of candidates) {
    const side = String(candidate.suggestedSide || fallbackSide).toUpperCase();
    const entryPrice = side === 'BUY' ? ask : bid;
    rows.push({
      id: uid(),
      shadow: true,
      trainingOnly: true,
      verifiedTrade: false,
      pnlAccounting: false,
      venue,
      requestedVenue: venue,
      symbol,
      strategy: candidate.key,
      agentStrategy: candidate.key,
      side,
      regime,
      candidateScore: Number(candidate.score || 0),
      regimeBias: Number(candidate.regimeBias || 0),
      entryPrice: Number(entryPrice.toFixed(8)),
      estimatedRoundTripCostPct: Number(preview.estimatedRoundTripCostPct || 0),
      costCoverageRatio: Number(preview.costCoverageRatio || 0),
      marketSnapshotId: preview.snapshot?.id || null,
      marketSourceVenue: normalizeVenue(preview.snapshot?.marketSourceVenue || preview.snapshot?.venueKey || preview.snapshot?.venue || venue) || venue,
      marketTransport: preview.snapshot?.marketTransport || 'unknown',
      openedAt,
      settleAfterAt,
      maxSettleAt: new Date(nowMs + SHADOW_STRATEGY_MAX_SETTLE_DELAY_MS).toISOString(),
      reason,
      learningWeight: 1
    });
  }
  lab.pending.unshift(...rows);
  lab.pending = lab.pending.slice(0, SHADOW_STRATEGY_PENDING_LIMIT);
  lab.totalRecorded = Number(lab.totalRecorded || 0) + rows.length;
  lab.lastRecordedAt = openedAt;
  lab.lastSampleByMarket[marketKeyValue] = openedAt;
  lab.lastUpdatedAt = openedAt;
  return { recorded: rows.length, venue, symbol, regime };
}


function adaptiveExitAIState(state = db) {
  state.adaptiveExitAI = deepMerge(adaptiveExitAIDefaults(), asObject(state.adaptiveExitAI, {}));
  state.adaptiveExitAI.profiles = asObject(state.adaptiveExitAI.profiles, {});
  state.adaptiveExitAI.exitReasons = asObject(state.adaptiveExitAI.exitReasons, {});
  return state.adaptiveExitAI;
}

function adaptiveExitProfileKey(order = {}, regime = 'unknown') {
  return [
    normalizeVenue(order.requestedVenue || order.venue || order.entryMarketVenue || '') || 'unknown',
    String(order.agentStrategy || order.strategy || 'adaptive').toLowerCase(),
    String(regime || 'unknown').toLowerCase(),
    String(order.side || 'NA').toUpperCase()
  ].join('|');
}

function adaptiveExitProfileForOrder(order = {}, technical = {}, latest = {}) {
  const state = adaptiveExitAIState(db);
  if (!ADAPTIVE_EXIT_AI_ENABLED) return null;
  const decision = (db.aiDecisions || []).find(d => d.id === order.decisionId) || {};
  const regime = String(order.marketRegime || order.venueAgentRegime || decision.venueAgentAI?.regime || decision.features?.regime || inferMarketRegime(technical, latest) || 'unknown').toLowerCase();
  const key = adaptiveExitProfileKey(order, regime);
  const cached = asObject(state.profiles[key], {});
  const cachedAt = Date.parse(cached.computedAt || '') || 0;
  if (cachedAt && Date.now() - cachedAt < ADAPTIVE_EXIT_PROFILE_CACHE_MS) return cached;
  const rows = verifiedLearningTrades(db).slice(0, ADAPTIVE_EXIT_EVIDENCE_LIMIT);
  const profile = buildAdaptiveExitProfile({
    verifiedTrades: rows,
    currentVersion: CURRENT_STRATEGY_VERSION,
    venue: normalizeVenue(order.requestedVenue || order.venue || order.entryMarketVenue || ''),
    strategy: order.agentStrategy || order.strategy || decision.venueAgentAI?.selectedStrategy || 'adaptive',
    regime,
    side: order.side,
    baseTakeProfitPct: Number(order.baseTakeProfitPct || order.takeProfitPct || 0.35),
    baseStopLossPct: Number(order.baseStopLossPct || order.stopLossPct || 0.25),
    baseMinHoldMs: Number(order.baseMinHoldMs || order.minHoldMs || PAPER_POSITION_MIN_HOLD_MS),
    baseSoftHoldMs: Number(order.baseSoftHoldMs || order.softHoldMs || PAPER_POSITION_SOFT_HOLD_MS),
    baseHardHoldMs: Number(order.baseHardHoldMs || order.hardHoldMs || PAPER_POSITION_MAX_HOLD_MS),
    estimatedCostPct: Number(order.estimatedRoundTripCostPct || 0.15)
  });
  profile.computedAt = now();
  profile.key = key;
  state.profiles[key] = profile;
  const keys = Object.keys(state.profiles);
  if (keys.length > 80) {
    keys.sort((a,b) => (Date.parse(state.profiles[b]?.computedAt || '') || 0) - (Date.parse(state.profiles[a]?.computedAt || '') || 0));
    const keep = new Set(keys.slice(0,80));
    for (const k of keys) if (!keep.has(k)) delete state.profiles[k];
  }
  state.lastProfileAt = profile.computedAt;
  state.lastProfileKey = key;
  state.status = profile.status === 'evidence-backed' ? 'learning-active' : 'warming-up';
  return profile;
}

function recordAdaptiveExitDecision(result = {}, profile = null) {
  const state = adaptiveExitAIState(db);
  state.totalDecisions = Number(state.totalDecisions || 0) + 1;
  state.lastDecisionAt = now();
  if (result.action === 'exit') {
    state.adaptiveExits = Number(state.adaptiveExits || 0) + 1;
    const reason = String(result.reason || 'adaptive_exit');
    state.exitReasons[reason] = Number(state.exitReasons[reason] || 0) + 1;
  } else {
    state.holdDecisions = Number(state.holdDecisions || 0) + 1;
  }
  if (profile?.status === 'evidence-backed') state.status = 'learning-active';
  return state;
}

function adaptiveExitAISummary(state = db) {
  const ai = adaptiveExitAIState(state);
  return summarizeAdaptiveExit(verifiedLearningTrades(state).slice(0, ADAPTIVE_EXIT_EVIDENCE_LIMIT), ai.profiles, ai);
}

function settleShadowStrategyLab(reason = 'runtime-cycle') {
  const lab = normalizeShadowStrategyLab(db);
  if (!lab.enabled || !lab.pending.length) return { settled: 0, invalidated: 0, pending: lab.pending.length };
  const nowMs = Date.now();
  const keep = [];
  let settled = 0;
  let invalidated = 0;
  for (const row of lab.pending) {
    const settleMs = Date.parse(row.settleAfterAt || '');
    const maxMs = Date.parse(row.maxSettleAt || '');
    if (!Number.isFinite(settleMs) || nowMs < settleMs) { keep.push(row); continue; }
    const venue = normalizeVenue(row.venue);
    const symbol = normalizeSymbol(row.symbol);
    const latest = venue && symbol ? marketDataService.latest(venue, symbol) : null;
    if (!latest || !snapshotMatchesMarketBinding(latest, venue, symbol) || !marketSnapshotIsFreshTrusted(latest)) {
      if (Number.isFinite(maxMs) && nowMs >= maxMs) invalidated += 1;
      else keep.push(row);
      continue;
    }
    const side = String(row.side || 'BUY').toUpperCase();
    const exitPrice = Number(side === 'BUY' ? (latest.bid || latest.price || latest.mid) : (latest.ask || latest.price || latest.mid));
    const entryPrice = Number(row.entryPrice || 0);
    if (!(entryPrice > 0 && exitPrice > 0)) {
      if (Number.isFinite(maxMs) && nowMs >= maxMs) invalidated += 1;
      else keep.push(row);
      continue;
    }
    const direction = side === 'SELL' ? -1 : 1;
    const grossPct = ((exitPrice - entryPrice) / entryPrice) * 100 * direction;
    const costPct = Math.max(0, Number(row.estimatedRoundTripCostPct || 0));
    const netPct = grossPct - costPct;
    lab.results.unshift({
      ...row,
      status: 'settled',
      exitPrice: Number(exitPrice.toFixed(8)),
      grossPct: Number(grossPct.toFixed(5)),
      costPct: Number(costPct.toFixed(5)),
      netPct: Number(netPct.toFixed(5)),
      won: netPct > 0,
      settledAt: now(),
      settleSnapshotId: latest.id || null,
      settleReason: reason
    });
    settled += 1;
  }
  lab.pending = keep.slice(0, SHADOW_STRATEGY_PENDING_LIMIT);
  lab.results = lab.results.slice(0, SHADOW_STRATEGY_RESULTS_LIMIT);
  lab.totalSettled = Number(lab.totalSettled || 0) + settled;
  lab.totalInvalidated = Number(lab.totalInvalidated || 0) + invalidated;
  if (settled) lab.lastSettledAt = now();
  lab.lastUpdatedAt = now();
  lab.status = lab.totalSettled > 0 ? 'learning-active' : 'warming-up';
  if (settled || invalidated) {
    lab.championSummary = shadowStrategyLabSummary(db).byVenue;
    persistSoon('shadow-strategy-lab-settle');
  }
  return { settled, invalidated, pending: lab.pending.length };
}

function computeVerifiedStatsFromTrades(trades = []) {
  const sorted = asArray(trades).filter(isVerifiedMarketTrade).sort((a, b) => String(a.closedAt || a.time || '').localeCompare(String(b.closedAt || b.time || '')));
  const out = marketIntegrityStatsDefaults();
  let equity = VERIFIED_PAPER_INITIAL_CAPITAL;
  let peak = equity;
  for (const trade of sorted) {
    const pnl = Number(trade.netPnl || 0);
    const gross = Number(trade.grossPnl || 0);
    const fees = Number(trade.fee || 0) + Number(trade.slippage || 0);
    out.closedTrades += 1;
    out.wins += pnl > 0 ? 1 : 0;
    out.losses += pnl > 0 ? 0 : 1;
    out.netPnl += pnl;
    out.grossPnl += gross;
    out.fees += fees;
    equity = VERIFIED_PAPER_INITIAL_CAPITAL + out.netPnl;
    peak = Math.max(peak, equity);
    out.maxDrawdownUsd = Math.max(out.maxDrawdownUsd, peak - equity);
    out.firstTradeAt = out.firstTradeAt || trade.closedAt || trade.time || null;
    out.lastTradeAt = trade.closedAt || trade.time || out.lastTradeAt;
    out.equityCurve.push({ n: out.closedTrades, equity: Number(equity.toFixed(4)), time: out.lastTradeAt, netPnl: Number(pnl.toFixed(4)), orderId: trade.orderId || '' });
  }
  out.winRate = out.closedTrades ? Number((out.wins / out.closedTrades * 100).toFixed(1)) : null;
  out.grossPnl = Number(out.grossPnl.toFixed(2));
  out.netPnl = Number(out.netPnl.toFixed(2));
  out.fees = Number(out.fees.toFixed(2));
  out.equity = Number(equity.toFixed(2));
  out.maxDrawdownUsd = Number(out.maxDrawdownUsd.toFixed(2));
  out.maxDrawdownPct = Number((out.maxDrawdownUsd / Math.max(1, peak) * 100).toFixed(2));
  out.equityCurve = out.equityCurve.slice(-140);
  out.status = out.closedTrades >= VERIFIED_MARKET_MIN_SAMPLES_FOR_BOOSTS ? 'verified' : (out.closedTrades > 0 ? 'warming-up' : 'waiting-for-verified-trades');
  out.lastUpdatedAt = now();
  return out;
}

function createVerifiedStatsAccumulator(source = 'supabase-verified-history-rehydrate') {
  const out = marketIntegrityStatsDefaults();
  out.source = source;
  out.status = 'waiting-for-verified-trades';
  out.strictVerifiedTrades = 0;
  out.recoveredVerifiedTrades = 0;
  out.scannedRows = 0;
  out._equity = VERIFIED_PAPER_INITIAL_CAPITAL;
  out._peak = VERIFIED_PAPER_INITIAL_CAPITAL;
  return out;
}

function accumulateVerifiedStats(acc, trade = {}) {
  const evidence = verifiedMarketTradeEvidence(trade);
  if (!tradeClosed(trade) || !evidence.verified) return acc;
  const pnl = finiteNumber(trade.netPnl ?? trade.pnl, 0);
  const gross = finiteNumber(trade.grossPnl, pnl);
  const fees = finiteNumber(trade.fee, 0) + finiteNumber(trade.slippage, 0);
  const closedAt = trade.closedAt || trade.time || trade.created_at || now();
  acc.scannedRows += 1;
  acc.closedTrades += 1;
  acc.wins += pnl > 0 ? 1 : 0;
  acc.losses += pnl > 0 ? 0 : 1;
  acc.netPnl += pnl;
  acc.grossPnl += gross;
  acc.fees += fees;
  acc.strictVerifiedTrades += evidence.strict ? 1 : 0;
  acc.recoveredVerifiedTrades += evidence.recovered ? 1 : 0;
  acc._equity = VERIFIED_PAPER_INITIAL_CAPITAL + acc.netPnl;
  acc._peak = Math.max(acc._peak, acc._equity);
  acc.maxDrawdownUsd = Math.max(acc.maxDrawdownUsd, acc._peak - acc._equity);
  const currentFirst = Date.parse(acc.firstTradeAt || '') || Infinity;
  const currentLast = Date.parse(acc.lastTradeAt || '') || 0;
  const candidateTime = Date.parse(closedAt) || 0;
  if (!acc.firstTradeAt || candidateTime < currentFirst) acc.firstTradeAt = closedAt;
  if (!acc.lastTradeAt || candidateTime >= currentLast) acc.lastTradeAt = closedAt;
  const step = { n: acc.closedTrades, equity: fixedNumber(acc._equity, 4), time: closedAt, netPnl: fixedNumber(pnl, 4), orderId: trade.orderId || trade.order_id || '' };
  if (acc.equityCurve.length < 400 || acc.closedTrades % 10 === 0) acc.equityCurve.push(step);
  if (acc.equityCurve.length > 650) acc.equityCurve.splice(0, acc.equityCurve.length - 650);
  return acc;
}

function finalizeVerifiedStatsAccumulator(acc = createVerifiedStatsAccumulator()) {
  const closedTrades = finiteNumber(acc.closedTrades, 0);
  const equity = VERIFIED_PAPER_INITIAL_CAPITAL + finiteNumber(acc.netPnl, 0);
  return {
    ...marketIntegrityStatsDefaults(),
    source: acc.source || 'supabase-verified-history-rehydrate',
    status: closedTrades >= VERIFIED_MARKET_MIN_SAMPLES_FOR_BOOSTS ? 'verified' : (closedTrades > 0 ? 'warming-up' : 'waiting-for-verified-trades'),
    closedTrades,
    wins: finiteNumber(acc.wins, 0),
    losses: finiteNumber(acc.losses, 0),
    winRate: closedTrades ? fixedNumber(finiteNumber(acc.wins, 0) / closedTrades * 100, 1) : null,
    grossPnl: fixedNumber(acc.grossPnl, 2),
    netPnl: fixedNumber(acc.netPnl, 2),
    fees: fixedNumber(acc.fees, 2),
    maxDrawdownUsd: fixedNumber(acc.maxDrawdownUsd, 2),
    maxDrawdownPct: fixedNumber(finiteNumber(acc.maxDrawdownUsd, 0) / Math.max(1, finiteNumber(acc._peak, VERIFIED_PAPER_INITIAL_CAPITAL)) * 100, 2),
    equity: fixedNumber(equity, 2),
    equityCurve: asArray(acc.equityCurve).slice(-140),
    firstTradeAt: acc.firstTradeAt || null,
    lastTradeAt: acc.lastTradeAt || null,
    lastUpdatedAt: now(),
    strictVerifiedTrades: finiteNumber(acc.strictVerifiedTrades, 0),
    recoveredVerifiedTrades: finiteNumber(acc.recoveredVerifiedTrades, 0),
    rehydratedFromFullHistory: true,
    note: `Teljes Supabase historyból visszaépített verified statisztika: ${finiteNumber(acc.strictVerifiedTrades, 0)} szigorú + ${finiteNumber(acc.recoveredVerifiedTrades, 0)} kompatibilitással helyreállított rekord.`
  };
}

function markVerifiedStatsIntegrityCorrected(stats = {}, state = db, source = 'symbol-price-integrity-correction', options = {}) {
  const integrity = deepMerge(marketIntegrityDefaults().symbolPriceIntegrity, state?.marketIntegrity?.symbolPriceIntegrity || {});
  const correctedTradeIds = [...new Set([
    ...asArray(stats.correctedTradeIds).map(String),
    ...asArray(options.correctedTradeIds).map(String),
    ...asArray(integrity.correctedTradeIds).map(String)
  ].filter(Boolean))].slice(-1000);
  const excluded = Math.max(
    finiteNumber(stats.quarantinedTradesExcluded, 0),
    finiteNumber(options.quarantinedTradesExcluded, 0),
    correctedTradeIds.length,
    finiteNumber(integrity.quarantinedTrades, 0)
  );
  return {
    ...deepMerge(marketIntegrityStatsDefaults(), stats || {}),
    integrityCorrected: true,
    integrityCorrectionSource: source,
    integrityCorrectionAppliedAt: options.integrityCorrectionAppliedAt || stats.integrityCorrectionAppliedAt || integrity.correctedAggregateAt || now(),
    quarantinedTradesExcluded: excluded,
    correctedTradeIds,
    correctedNetPnlUsd: Number(Math.max(
      finiteNumber(stats.correctedNetPnlUsd, 0),
      finiteNumber(options.correctedNetPnlUsd, 0),
      finiteNumber(integrity.correctedNetPnlUsd, 0)
    ).toFixed(4)),
    source: String(stats.source || 'verified-public-market-journal').includes('integrity-corrected')
      ? stats.source
      : `${stats.source || 'verified-public-market-journal'}+integrity-corrected`
  };
}

function chooseVerifiedStatsTruth(...candidates) {
  const valid = candidates.filter(value => value && typeof value === 'object').map(value => deepMerge(marketIntegrityStatsDefaults(), value));
  if (!valid.length) return marketIntegrityStatsDefaults();
  // A teljes history/journal alapján integritás-javított statisztika autoritatív.
  // Egy régebbi, nagyobb checkpoint nem hozhatja vissza a már karanténba tett rekordot.
  const corrected = valid.filter(value => value.integrityCorrected === true);
  const pool = corrected.length ? corrected : valid;
  pool.sort((a, b) => {
    const countDelta = finiteNumber(b.closedTrades, 0) - finiteNumber(a.closedTrades, 0);
    if (countDelta) return countDelta;
    const authorityDelta = Number(!!b.rehydratedFromFullHistory) - Number(!!a.rehydratedFromFullHistory);
    if (authorityDelta) return authorityDelta;
    const timeDelta = (Date.parse(b.lastTradeAt || b.lastUpdatedAt || b.integrityCorrectionAppliedAt || '') || 0) - (Date.parse(a.lastTradeAt || a.lastUpdatedAt || a.integrityCorrectionAppliedAt || '') || 0);
    if (timeDelta) return timeDelta;
    return (Date.parse(b.integrityCorrectionAppliedAt || '') || 0) - (Date.parse(a.integrityCorrectionAppliedAt || '') || 0);
  });
  return deepMerge(marketIntegrityStatsDefaults(), pool[0]);
}

function verifiedLearningTrades(state = db) {
  return asArray(state?.tradeJournal).filter(isVerifiedMarketTrade).sort((a, b) => String(b.closedAt || b.time || '').localeCompare(String(a.closedAt || a.time || '')));
}

function currentStrategyVerifiedTrades(state = db) {
  return verifiedLearningTrades(state).filter(trade => String(trade?.strategyVersion || trade?.executionEpoch || '') === CURRENT_STRATEGY_VERSION);
}

function currentStrategyRouteSampleCount(venue = 'binance', symbol = 'BTC/USDT', side = 'BUY', state = db) {
  const wantedVenue = normalizeVenue(venue) || 'binance';
  const wantedSymbol = normalizeSymbol(symbol);
  const wantedSide = String(side || '').toUpperCase();
  if (!['BUY', 'SELL'].includes(wantedSide)) return 0;
  return currentStrategyVerifiedTrades(state).filter(trade => {
    const tradeVenue = normalizeVenue(trade?.requestedVenue || trade?.entryMarketVenue || trade?.venue || trade?.marketVenue || '') || 'binance';
    return tradeVenue === wantedVenue
      && normalizeSymbol(trade?.symbol || '') === wantedSymbol
      && String(trade?.side || '').toUpperCase() === wantedSide;
  }).length;
}

function currentStrategyRouteRegimeEvidence(venue = 'binance', symbol = 'BTC/USDT', side = 'BUY', regime = 'RANGE', state = db) {
  const wantedVenue = normalizeVenue(venue) || 'binance';
  const wantedSymbol = normalizeSymbol(symbol);
  const wantedSide = String(side || '').toUpperCase();
  const wantedRegime = String(regime || 'RANGE').toUpperCase();
  if (!['BUY', 'SELL'].includes(wantedSide)) return { samples: 0, lastTradeAt: null, ageMs: Infinity };
  const rows = currentStrategyVerifiedTrades(state).filter(trade => {
    const tradeVenue = normalizeVenue(trade?.requestedVenue || trade?.entryMarketVenue || trade?.venue || trade?.marketVenue || '') || 'binance';
    return tradeVenue === wantedVenue
      && normalizeSymbol(trade?.symbol || '') === wantedSymbol
      && String(trade?.side || '').toUpperCase() === wantedSide
      && onlineLearningRegime(trade) === wantedRegime;
  });
  const lastTradeAt = rows[0]?.closedAt || rows[0]?.time || null;
  const lastMs = Date.parse(lastTradeAt || '');
  return {
    samples: rows.length,
    lastTradeAt,
    ageMs: Number.isFinite(lastMs) ? Math.max(0, Date.now() - lastMs) : Infinity
  };
}

function currentStrategyLastTradeStatus(state = db, venue = '') {
  const wantedVenue = venue ? (normalizeVenue(venue) || '') : '';
  const row = currentStrategyVerifiedTrades(state).find(trade => !wantedVenue || (normalizeVenue(trade?.requestedVenue || trade?.entryMarketVenue || trade?.venue || trade?.marketVenue || '') || 'binance') === wantedVenue) || null;
  const lastTradeAt = row?.closedAt || row?.time || null;
  const lastMs = Date.parse(lastTradeAt || '');
  return {
    lastTradeAt,
    idleMs: Number.isFinite(lastMs) ? Math.max(0, Date.now() - lastMs) : Infinity,
    tradeId: row?.id || row?.orderId || null
  };
}

function activeLearningOpenProbeCount(state = db) {
  return asArray(state?.orders).filter(order => isActiveOrder(order) && order?.activeLearningProbe === true).length;
}

function activeLearningOpenProbeCountForVenue(venue = 'binance', state = db) {
  const wanted = normalizeVenue(venue) || 'binance';
  return asArray(state?.orders).filter(order => {
    if (!isActiveOrder(order) || order?.activeLearningProbe !== true) return false;
    const orderVenue = normalizeVenue(order.requestedVenue || order.entryMarketVenue || order.venue || order.exchange || '') || 'binance';
    return orderVenue === wanted;
  }).length;
}

function currentStrategyPerformance(state = db, limit = 40) {
  const rows = currentStrategyVerifiedTrades(state).slice(0, Math.max(1, limit));
  const wins = rows.filter(row => Number(row.netPnl || 0) > 0).length;
  const netPnl = rows.reduce((sum, row) => sum + Number(row.netPnl || 0), 0);
  return {
    strategyVersion: CURRENT_STRATEGY_VERSION,
    trades: rows.length,
    wins,
    losses: Math.max(0, rows.length - wins),
    winRate: rows.length ? Number((wins / rows.length * 100).toFixed(1)) : null,
    netPnl: Number(netPnl.toFixed(4)),
    source: 'current-strategy-verified-only'
  };
}

function currentEngineBootstrapStatus(state = db, venue = '') {
  const wantedVenue = venue ? (normalizeVenue(venue) || '') : '';
  const trades = currentStrategyVerifiedTrades(state).filter(trade => !wantedVenue || (normalizeVenue(trade?.requestedVenue || trade?.entryMarketVenue || trade?.venue || trade?.marketVenue || '') || 'binance') === wantedVenue);
  const lastTradeStatus = currentStrategyLastTradeStatus(state, wantedVenue);
  const heartbeat = asObject(state?.marketLearningHeartbeat, {});
  const trustedObservations = Number(heartbeat.trustedObservations || 0);
  const technicalReadyObservations = Number(heartbeat.technicalReadyObservations || 0);
  const firstTrustedMs = Date.parse(heartbeat.firstTrustedObservationAt || heartbeat.firstObservationAt || PROCESS_STARTED_AT || '');
  const observationAgeMs = Number.isFinite(firstTrustedMs) ? Math.max(0, Date.now() - firstTrustedMs) : 0;
  const warmup = trades.length < CURRENT_ENGINE_BOOTSTRAP_TRADES;
  const bootstrapEligible = warmup
    && ['paper', 'staging'].includes(String(state?.mode || '').toLowerCase())
    && trustedObservations >= CURRENT_ENGINE_BOOTSTRAP_OBSERVATIONS;
  const starvationRecovery = bootstrapEligible
    && trades.length < 3
    && trustedObservations >= CURRENT_ENGINE_STARVATION_OBSERVATIONS
    && technicalReadyObservations >= Math.floor(CURRENT_ENGINE_STARVATION_OBSERVATIONS * 0.65)
    && observationAgeMs >= CURRENT_ENGINE_STARVATION_MIN_MS;
  return {
    strategyVersion: CURRENT_STRATEGY_VERSION,
    scopeVenue: wantedVenue || null,
    trades: trades.length,
    warmup,
    bootstrapEligible,
    starvationRecovery,
    trustedObservations,
    technicalReadyObservations,
    lastTradeAt: lastTradeStatus.lastTradeAt,
    idleMs: lastTradeStatus.idleMs,
    firstTrustedObservationAt: heartbeat.firstTrustedObservationAt || heartbeat.firstObservationAt || null,
    observationAgeMs,
    controlMinTrades: CURRENT_ENGINE_CONTROL_MIN_TRADES,
    bootstrapTradeTarget: CURRENT_ENGINE_BOOTSTRAP_TRADES,
    policy: 'new-engine-epoch-warmup-old-results-soft-prior-only-controlled-non-random-entry'
  };
}

function verifiedTradeMetrics(state = db) {
  const stats = deepMerge(marketIntegrityStatsDefaults(), state?.marketIntegrity?.verifiedStats || {});
  return {
    closedTrades: Number(stats.closedTrades || 0),
    wins: Number(stats.wins || 0),
    losses: Number(stats.losses || 0),
    winRate: stats.winRate == null ? null : Number(stats.winRate),
    grossPnl: Number(stats.grossPnl || 0),
    netPnl: Number(stats.netPnl || 0),
    fees: Number(stats.fees || 0),
    maxDrawdownUsd: Number(stats.maxDrawdownUsd || 0),
    maxDrawdownPct: Number(stats.maxDrawdownPct || 0),
    equity: Number(stats.equity || VERIFIED_PAPER_INITIAL_CAPITAL),
    equityCurve: asArray(stats.equityCurve).slice(-100),
    weeklyProfit: 0,
    aggregateSource: 'verified-public-market-journal',
    aggregateComplete: true,
    displayCacheTrades: verifiedLearningTrades(state).length,
    statsScope: 'verified_public_market_epoch',
    integrityVerified: true
  };
}

function historicalProofLikeTrade(trade = {}) {
  const text = [trade.id, trade.orderId, trade.status, trade.source, trade.mode, trade.exitReason, trade.fillState, trade.note, trade.type]
    .map(x => String(x || '').toLowerCase()).join(' ');
  return /live[_ -]?submit[_ -]?blocked|dry[_ -]?run|execution[_ -]?proof|readonly[_ -]?proof|preflight|test[_ -]?proof|not-submitted|quarantin|maintenance[_ -]?proof/.test(text);
}

function qualifyHistoricalTrade(trade = {}) {
  if (!HISTORICAL_LEARNING_ENABLED) return { accepted: false, reason: 'disabled', weight: 0, tier: 'excluded' };
  const symbolPriceIntegrity = tradeSymbolPriceIntegrity(trade);
  if (!symbolPriceIntegrity.ok) return { accepted: false, reason: symbolPriceIntegrity.reason || 'symbol-price-integrity-failed', weight: 0, tier: 'excluded' };
  if (!tradeClosed(trade)) return { accepted: false, reason: 'not-closed', weight: 0, tier: 'excluded' };
  if (isVerifiedMarketTrade(trade)) return { accepted: false, reason: 'verified-separate', weight: 0, tier: 'verified' };
  if (historicalProofLikeTrade(trade)) return { accepted: false, reason: 'proof-or-quarantine', weight: 0, tier: 'excluded' };
  const entry = Number(trade.entryPrice || trade.openPrice || trade.avgEntryPrice || 0);
  const exit = Number(trade.exitPrice || trade.closePrice || trade.avgExitPrice || 0);
  const pnl = Number(trade.netPnl);
  const rawSymbol = String(trade.symbol || '').trim();
  const symbol = rawSymbol ? normalizeSymbol(rawSymbol) : '';
  const side = String(trade.side || trade.direction || '').toUpperCase();
  if (!Number.isFinite(pnl)) return { accepted: false, reason: 'invalid-pnl', weight: 0, tier: 'excluded' };
  if (!(entry > 0) || !(exit > 0)) return { accepted: false, reason: 'missing-prices', weight: 0, tier: 'excluded' };
  if (!symbol || symbol === 'UNKNOWN') return { accepted: false, reason: 'missing-symbol', weight: 0, tier: 'excluded' };
  if (!['BUY', 'SELL', 'LONG', 'SHORT'].includes(side)) return { accepted: false, reason: 'missing-side', weight: 0, tier: 'excluded' };
  const hasTime = tradeTimeValue(trade) > 0;
  const hasContext = !!(trade.strategy || trade.strategyKey || trade.regime || trade.marketRegime || Number(trade.confidence || 0) > 0 || trade.volatility);
  const tier = hasTime && hasContext ? 'strong' : 'standard';
  return {
    accepted: true,
    reason: 'qualified',
    tier,
    weight: tier === 'strong' ? HISTORICAL_LEARNING_STRONG_WEIGHT : HISTORICAL_LEARNING_STANDARD_WEIGHT,
    normalized: { ...trade, entryPrice: entry, exitPrice: exit, netPnl: pnl, symbol, side: side === 'LONG' ? 'BUY' : side === 'SHORT' ? 'SELL' : side }
  };
}

function createHistoricalLearningAccumulator(source = 'local-history') {
  return {
    source,
    scanned: 0,
    verifiedSkipped: 0,
    accepted: 0,
    rejected: 0,
    acceptedStrong: 0,
    acceptedStandard: 0,
    rejectionReasons: {},
    weightedSamples: 0,
    weightedWins: 0,
    weightedLosses: 0,
    weightedNetPnl: 0,
    weightedGrossPnl: 0,
    weightedFees: 0,
    weightedQuality: 0,
    strategy: new Map(), symbol: new Map(), regime: new Map(), side: new Map(),
    calibrationRows: [],
    recentAcceptedQuality: [],
    verifiedSkippedWins: 0,
    verifiedSkippedNetPnl: 0
  };
}

function accumulateHistoricalLearningTrade(acc, trade = {}) {
  acc.scanned += 1;
  const qf = qualifyHistoricalTrade(trade);
  if (qf.reason === 'verified-separate') {
    acc.verifiedSkipped += 1;
    const verifiedPnl = Number(trade.netPnl ?? trade.pnl ?? 0);
    if (verifiedPnl > 0) acc.verifiedSkippedWins += 1;
    acc.verifiedSkippedNetPnl += Number.isFinite(verifiedPnl) ? verifiedPnl : 0;
    return acc;
  }
  if (!qf.accepted) {
    acc.rejected += 1;
    acc.rejectionReasons[qf.reason] = Number(acc.rejectionReasons[qf.reason] || 0) + 1;
    return acc;
  }
  const row = buildSignalQualityRow(qf.normalized, null, {
    skipDecisionLookup: true,
    source: 'qualified-historical-trade',
    learningWeight: qf.weight,
    historical: true,
    qualityTier: qf.tier,
    preserveTime: true
  });
  const w = Number(row.learningWeight || qf.weight || 0);
  acc.accepted += 1;
  if (qf.tier === 'strong') acc.acceptedStrong += 1; else acc.acceptedStandard += 1;
  acc.weightedSamples += w;
  acc.weightedWins += row.win ? w : 0;
  acc.weightedLosses += row.win ? 0 : w;
  acc.weightedNetPnl += Number(row.netPnl || 0) * w;
  acc.weightedGrossPnl += Number(row.grossPnl || 0) * w;
  acc.weightedFees += (Number(row.fee || 0) + Number(row.slippage || 0)) * w;
  acc.weightedQuality += Number(row.qualityScore || 0) * w;
  addToGroup(acc.strategy, row.strategyKey, row);
  addToGroup(acc.symbol, row.symbol, row);
  addToGroup(acc.regime, row.regime || 'UNKNOWN', row);
  addToGroup(acc.side, row.side || 'NA', row);
  acc.calibrationRows.push(row);
  acc.recentAcceptedQuality.push(row);
  if (acc.recentAcceptedQuality.length > HISTORICAL_LEARNING_RECENT_QUALITY_CAP) acc.recentAcceptedQuality.shift();
  if (acc.calibrationRows.length > 5000) acc.calibrationRows.shift();
  return acc;
}

function scaleGroupAccumulator(g = {}, factor = 1) {
  const out = { ...g };
  for (const key of ['trades','wins','losses','netPnl','grossPnl','fees','winPnl','lossPnl','confidenceSum','confidenceSamples','qualitySum']) out[key] = Number(out[key] || 0) * factor;
  return out;
}

function finalizeHistoricalLearningAccumulator(acc, options = {}) {
  const cap = HISTORICAL_LEARNING_EFFECTIVE_SAMPLE_CAP;
  const rawWeighted = Number(acc.weightedSamples || 0);
  const detailedScale = rawWeighted > cap ? cap / rawWeighted : 1;
  let effective = rawWeighted * detailedScale;
  let weightedWins = Number(acc.weightedWins || 0) * detailedScale;
  let weightedLosses = Number(acc.weightedLosses || 0) * detailedScale;
  let weightedNetPnl = Number(acc.weightedNetPnl || 0) * detailedScale;
  let weightedGrossPnl = Number(acc.weightedGrossPnl || 0) * detailedScale;
  let weightedFees = Number(acc.weightedFees || 0) * detailedScale;
  let weightedQuality = Number(acc.weightedQuality || 0) * detailedScale;
  const knownLegacy = Math.max(0, Number(options.totalLegacyClosed || 0));
  const unseenLegacy = Math.max(0, knownLegacy - Number(acc.accepted || 0) - Number(acc.rejected || 0));
  const remainingCap = Math.max(0, cap - effective);
  const fallbackEffective = Math.min(remainingCap, unseenLegacy * HISTORICAL_LEARNING_AGGREGATE_WEIGHT);
  const fallbackWinRate = Number.isFinite(Number(options.legacyWinRate)) ? clamp(Number(options.legacyWinRate), 0, 100) : null;
  if (fallbackEffective > 0 && fallbackWinRate !== null) {
    const legacyPerTradePnl = knownLegacy > 0 ? Number(options.legacyNetPnl || 0) / knownLegacy : 0;
    weightedWins += fallbackEffective * fallbackWinRate / 100;
    weightedLosses += fallbackEffective * (1 - fallbackWinRate / 100);
    weightedNetPnl += fallbackEffective * legacyPerTradePnl;
    weightedGrossPnl += fallbackEffective * legacyPerTradePnl;
    weightedQuality += fallbackEffective * clamp(35 + fallbackWinRate * 0.55, 30, 85);
    effective += fallbackEffective;
  }
  const finalizeMap = map => [...map.entries()]
    .map(([key, g]) => finalizeGroup(key, scaleGroupAccumulator(g, detailedScale)))
    .sort((a, b) => Number(b.trades || 0) - Number(a.trades || 0) || Number(b.score || 0) - Number(a.score || 0))
    .slice(0, 120);
  const recent = asArray(acc.recentAcceptedQuality).map(row => ({ ...row, learningWeight: Number((Number(row.learningWeight || 0) * detailedScale).toFixed(6)) })).slice(-HISTORICAL_LEARNING_RECENT_QUALITY_CAP).reverse();
  const calibration = confidenceCalibrationRows(asArray(acc.calibrationRows).map(row => ({ ...row, learningWeight: Number((Number(row.learningWeight || 0) * detailedScale).toFixed(6)) })));
  const result = deepMerge(historicalLearningDefaults(), {
    enabled: HISTORICAL_LEARNING_ENABLED,
    status: effective > 0 ? 'active' : (acc.scanned > 0 ? 'no-qualified-history' : 'empty'),
    source: options.source || acc.source,
    complete: options.complete === true,
    detailedScanned: Number(acc.scanned || 0),
    verifiedSkipped: Number(acc.verifiedSkipped || 0),
    acceptedDetailedTrades: Number(acc.accepted || 0),
    rejectedDetailedTrades: Number(acc.rejected || 0),
    acceptedStrong: Number(acc.acceptedStrong || 0),
    acceptedStandard: Number(acc.acceptedStandard || 0),
    aggregateFallbackTrades: unseenLegacy,
    detailedEffectiveSamples: Number((rawWeighted * detailedScale).toFixed(2)),
    aggregateFallbackEffectiveSamples: Number(fallbackEffective.toFixed(2)),
    rawWeightedSamples: Number(rawWeighted.toFixed(3)),
    scaleFactor: Number(detailedScale.toFixed(6)),
    effectiveSampleCap: cap,
    effectiveHistoricalSamples: Number(effective.toFixed(2)),
    weightedWins: Number(weightedWins.toFixed(3)),
    weightedLosses: Number(weightedLosses.toFixed(3)),
    weightedWinRate: effective > 0 ? Number((weightedWins / Math.max(0.0001, effective) * 100).toFixed(1)) : null,
    weightedNetPnl: Number(weightedNetPnl.toFixed(4)),
    weightedGrossPnl: Number(weightedGrossPnl.toFixed(4)),
    weightedFees: Number(weightedFees.toFixed(4)),
    avgQuality: effective > 0 ? Number((weightedQuality / Math.max(0.0001, effective)).toFixed(1)) : 0,
    rejectionReasons: acc.rejectionReasons,
    groups: { strategy: finalizeMap(acc.strategy), symbol: finalizeMap(acc.symbol), regime: finalizeMap(acc.regime), side: finalizeMap(acc.side) },
    confidenceCalibration: calibration,
    recentAcceptedQuality: recent,
    lastRebuildAt: now()
  });
  return updateCombinedLearningSummary(result, options.state || db);
}

function rebuildHistoricalLearningFromLocalState(state = db, reason = 'local-history-rebuild') {
  const acc = createHistoricalLearningAccumulator(reason);
  for (const trade of asArray(state?.tradeJournal)) accumulateHistoricalLearningTrade(acc, trade);
  const verified = verifiedTradeMetrics(state);
  const legacy = state?.marketIntegrity?.legacySnapshot || {};
  const aggregateClosed = Number(state?.aggregateStats?.closedTrades || 0);
  // Az aggregált számláló a verified epochot is tartalmazza; a történeti rész mindig a különbség.
  // Csak aggregált számláló hiányában támaszkodunk a korábban mentett snapshotra.
  const totalLegacyClosed = aggregateClosed > 0
    ? Math.max(0, aggregateClosed - Number(verified.closedTrades || 0))
    : Math.max(0, Number(legacy.closedTrades || 0));
  const result = finalizeHistoricalLearningAccumulator(acc, {
    state,
    source: reason,
    complete: false,
    totalLegacyClosed,
    legacyWinRate: legacy.winRate ?? state?.aggregateStats?.winRate,
    legacyNetPnl: legacy.netPnl ?? (Number(state?.aggregateStats?.netPnl || 0) - Number(verified.netPnl || 0))
  });
  state.marketIntegrity = deepMerge(marketIntegrityDefaults(), state.marketIntegrity || {});
  state.marketIntegrity.historicalLearning = result;
  return result;
}

function updateCombinedLearningSummary(history = null, state = db) {
  const h = deepMerge(historicalLearningDefaults(), history || state?.marketIntegrity?.historicalLearning || {});
  const verified = verifiedTradeMetrics(state);
  const verifiedSamples = Number(verified.closedTrades || 0);
  const historicalSamples = Number(h.effectiveHistoricalSamples || 0);
  const combinedSamples = verifiedSamples + historicalSamples;
  const combinedWins = Number(verified.wins || 0) + Number(h.weightedWins || 0);
  h.verifiedSamples = verifiedSamples;
  h.combinedEffectiveSamples = Number(combinedSamples.toFixed(2));
  h.combinedWinRate = combinedSamples > 0 ? Number((combinedWins / combinedSamples * 100).toFixed(1)) : null;
  h.combinedLearningNetPnl = Number((Number(verified.netPnl || 0) + Number(h.weightedNetPnl || 0)).toFixed(4));
  return h;
}

function historicalLearningStatus(state = db) {
  const current = deepMerge(historicalLearningDefaults(), state?.marketIntegrity?.historicalLearning || {});
  return updateCombinedLearningSummary(current, state);
}

function combinedLearningMetrics(state = db) {
  const verified = verifiedTradeMetrics(state);
  const history = historicalLearningStatus(state);
  const samples = Number(verified.closedTrades || 0) + Number(history.effectiveHistoricalSamples || 0);
  const wins = Number(verified.wins || 0) + Number(history.weightedWins || 0);
  const losses = Number(verified.losses || 0) + Number(history.weightedLosses || 0);
  return {
    closedTrades: Number(samples.toFixed(2)),
    effectiveSamples: Number(samples.toFixed(2)),
    rawVerifiedTrades: Number(verified.closedTrades || 0),
    rawHistoricalAcceptedTrades: Number(history.acceptedDetailedTrades || 0),
    rawHistoricalRejectedTrades: Number(history.rejectedDetailedTrades || 0),
    historicalEffectiveSamples: Number(history.effectiveHistoricalSamples || 0),
    wins: Number(wins.toFixed(3)),
    losses: Number(losses.toFixed(3)),
    winRate: samples > 0 ? Number((wins / samples * 100).toFixed(1)) : null,
    netPnl: Number((Number(verified.netPnl || 0) + Number(history.weightedNetPnl || 0)).toFixed(4)),
    grossPnl: Number((Number(verified.grossPnl || 0) + Number(history.weightedGrossPnl || 0)).toFixed(4)),
    fees: Number((Number(verified.fees || 0) + Number(history.weightedFees || 0)).toFixed(4)),
    maxDrawdownUsd: Number(verified.maxDrawdownUsd || 0),
    maxDrawdownPct: Number(verified.maxDrawdownPct || 0),
    equity: Number(verified.equity || VERIFIED_PAPER_INITIAL_CAPITAL),
    aggregateSource: 'verified-plus-qualified-history-weighted',
    statsScope: 'learning-only-combined-history',
    history,
    verified
  };
}

function updateVerifiedMarketStats(trade = {}) {
  if (!isVerifiedMarketTrade(trade)) return db.marketIntegrity?.verifiedStats || marketIntegrityStatsDefaults();
  db.marketIntegrity = deepMerge(marketIntegrityDefaults(), db.marketIntegrity || {});
  const current = deepMerge(marketIntegrityStatsDefaults(), db.marketIntegrity.verifiedStats || {});
  const alreadyCounted = asArray(current.recentTradeIds).includes(trade.id);
  if (alreadyCounted) return current;
  const pnl = Number(trade.netPnl || 0);
  const gross = Number(trade.grossPnl || 0);
  const fees = Number(trade.fee || 0) + Number(trade.slippage || 0);
  const closedTrades = Number(current.closedTrades || 0) + 1;
  const wins = Number(current.wins || 0) + (pnl > 0 ? 1 : 0);
  const losses = Number(current.losses || 0) + (pnl > 0 ? 0 : 1);
  const netPnl = Number((Number(current.netPnl || 0) + pnl).toFixed(4));
  const equity = Number((VERIFIED_PAPER_INITIAL_CAPITAL + netPnl).toFixed(4));
  const priorPeak = Math.max(VERIFIED_PAPER_INITIAL_CAPITAL, ...asArray(current.equityCurve).map(x => Number(x.equity || 0)));
  const peak = Math.max(priorPeak, equity);
  const drawdownUsd = Math.max(Number(current.maxDrawdownUsd || 0), peak - equity);
  const next = {
    ...current,
    status: closedTrades >= VERIFIED_MARKET_MIN_SAMPLES_FOR_BOOSTS ? 'verified' : 'warming-up',
    closedTrades,
    wins,
    losses,
    winRate: Number((wins / closedTrades * 100).toFixed(1)),
    grossPnl: Number((Number(current.grossPnl || 0) + gross).toFixed(2)),
    netPnl: Number(netPnl.toFixed(2)),
    fees: Number((Number(current.fees || 0) + fees).toFixed(2)),
    maxDrawdownUsd: Number(drawdownUsd.toFixed(2)),
    maxDrawdownPct: Number((drawdownUsd / Math.max(1, peak) * 100).toFixed(2)),
    equity: Number(equity.toFixed(2)),
    equityCurve: [...asArray(current.equityCurve), { n: closedTrades, equity, time: trade.closedAt || now(), netPnl: Number(pnl.toFixed(4)), orderId: trade.orderId || '' }].slice(-140),
    firstTradeAt: current.firstTradeAt || trade.closedAt || now(),
    lastTradeAt: trade.closedAt || now(),
    lastUpdatedAt: now(),
    recentTradeIds: [...asArray(current.recentTradeIds), trade.id].slice(-200)
  };
  db.marketIntegrity.verifiedStats = next;
  db.marketIntegrity.historicalLearning = updateCombinedLearningSummary(db.marketIntegrity.historicalLearning, db);
  syncVerifiedCapitalState(db, 'verified-trade-update');
  db.marketIntegrity.lastReconcileAt = now();
  return next;
}

function normalizeMarketIntegrityState(state, reason = 'normalize') {
  state.marketIntegrity = deepMerge(marketIntegrityDefaults(), state.marketIntegrity || {});
  const legacyCandidateClosed = Math.max(
    Number(state.aggregateStats?.closedTrades || 0),
    Number(state.capital?.lifetimeClosedTrades || 0),
    Number(state.marketIntegrity?.legacySnapshot?.closedTrades || 0)
  );
  const legacySnapshotMissing = !state.marketIntegrity.legacySnapshot || !state.marketIntegrity.legacySnapshot.capturedAt;
  if (legacySnapshotMissing) {
    state.marketIntegrity.legacySnapshot = {
      capturedAt: now(),
      version: state.version || VERSION,
      closedTrades: legacyCandidateClosed,
      winRate: state.aggregateStats?.winRate == null ? null : Number(state.aggregateStats.winRate),
      netPnl: Number(state.aggregateStats?.netPnl || state.capital?.lifetimeNetPnl || 0),
      activeTradingCapital: Number(state.capital?.activeTradingCapital || state.paperAccount?.available || 0),
      weeklyProfit: Number(state.aggregateStats?.weeklyProfit || state.capital?.weeklyProfit || 0),
      note: 'Korábbi paper/szimulációs történet megőrizve; a minősített rész v199_138-tól csökkentett súllyal segíti a tanulást, de nem vezérli a profit vaultot vagy verified tőkét.'
    };
    state.marketIntegrity.migrationAt = now();
  }
  const symbolPriceRepair = repairSymbolPriceIntegrityState(state, reason + '-symbol-price-integrity');
  const positionRepair = repairClosedPaperPositions(state, reason + '-closed-position-repair');
  if (positionRepair.repaired > 0) {
    state.marketIntegrity.symbolPriceIntegrity.repairedStalePositions = Number(state.marketIntegrity.symbolPriceIntegrity.repairedStalePositions || 0) + positionRepair.repaired;
    state.marketIntegrity.symbolPriceIntegrity.lastPositionRepairAt = now();
  }
  const aggregateIntegrityCorrection = correctAggregateForIntegrityQuarantine(state, symbolPriceRepair.quarantinedTradeRecords, reason + '-aggregate-integrity-correction');
  if (aggregateIntegrityCorrection.corrected > 0) applyAggregateToAccount(state.aggregateStats, state);
  let cached = computeVerifiedStatsFromTrades(state.tradeJournal);
  let existing = deepMerge(marketIntegrityStatsDefaults(), state.marketIntegrity.verifiedStats || {});
  const correctedIds = asArray(state.marketIntegrity?.symbolPriceIntegrity?.correctedTradeIds).map(String).filter(Boolean);
  const staleDifference = Number(existing.closedTrades || 0) - Number(cached.closedTrades || 0);
  const cacheCanExplainCorrection = correctedIds.length > 0 && staleDifference > 0 && staleDifference <= correctedIds.length;
  if (Number(symbolPriceRepair.quarantinedTrades || 0) > 0 || cacheCanExplainCorrection) {
    cached = markVerifiedStatsIntegrityCorrected(cached, state, reason + '-local-journal-integrity-authority', {
      quarantinedTradesExcluded: Math.max(Number(symbolPriceRepair.quarantinedTrades || 0), correctedIds.length),
      correctedTradeIds: correctedIds
    });
    cached.note = `Verified statisztika újraépítve a tiszta helyi journalból; ${Math.max(Number(symbolPriceRepair.quarantinedTrades || 0), correctedIds.length)} cross-symbol/ár-integritási rekord kizárva.`;
    state.marketIntegrity.verifiedStats = cached;
  } else if (existing.integrityCorrected === true) {
    state.marketIntegrity.verifiedStats = chooseVerifiedStatsTruth(existing, Number(cached.closedTrades || 0) > Number(existing.closedTrades || 0)
      ? markVerifiedStatsIntegrityCorrected(cached, state, reason + '-new-trades-after-integrity-correction', { correctedTradeIds: correctedIds })
      : cached);
  } else if (Number(cached.closedTrades || 0) > Number(existing.closedTrades || 0)) state.marketIntegrity.verifiedStats = cached;
  else state.marketIntegrity.verifiedStats = existing;
  const verified = state.marketIntegrity.verifiedStats;
  if (verified?.integrityCorrected === true && asArray(verified.correctedTradeIds).length) {
    const selectedCorrectedIds = asArray(verified.correctedTradeIds).map(String).filter(Boolean);
    state.marketIntegrity.symbolPriceIntegrity.correctedTradeIds = [...new Set([
      ...asArray(state.marketIntegrity.symbolPriceIntegrity?.correctedTradeIds).map(String),
      ...selectedCorrectedIds
    ])].slice(-1000);
    state.marketIntegrity.symbolPriceIntegrity.quarantinedTrades = Math.max(
      Number(state.marketIntegrity.symbolPriceIntegrity?.quarantinedTrades || 0),
      Number(verified.quarantinedTradesExcluded || 0),
      selectedCorrectedIds.length
    );
    state.marketIntegrity.symbolPriceIntegrity.correctedAggregateAt = state.marketIntegrity.symbolPriceIntegrity.correctedAggregateAt
      || verified.integrityCorrectionAppliedAt
      || now();
    state.marketIntegrity.symbolPriceIntegrity.correctedNetPnlUsd = Number(Math.max(
      finiteNumber(state.marketIntegrity.symbolPriceIntegrity.correctedNetPnlUsd, 0),
      finiteNumber(verified.correctedNetPnlUsd, 0)
    ).toFixed(4));
  }
  const aggregateClosed = Number(state.aggregateStats?.closedTrades || 0);
  const aggregateNetPnl = Number(state.aggregateStats?.netPnl || 0);
  const derivedLegacyClosed = Math.max(0, aggregateClosed - Number(verified.closedTrades || 0));
  const aggregateWins = Number(state.aggregateStats?.wins || 0);
  const derivedLegacyWins = Math.max(0, aggregateWins - Number(verified.wins || 0));
  const derivedLegacyWinRate = derivedLegacyClosed > 0
    ? Number((derivedLegacyWins / derivedLegacyClosed * 100).toFixed(1))
    : null;
  // A snapshot soha ne tartalmazza még egyszer a verified epochot. Ez megakadályozza,
  // hogy a régi aggregált számláló fallbackje duplán kerüljön a tanulási mintába.
  if (aggregateClosed > 0 || legacySnapshotMissing) {
    state.marketIntegrity.legacySnapshot = {
      ...(state.marketIntegrity.legacySnapshot || {}),
      capturedAt: state.marketIntegrity.legacySnapshot?.capturedAt || now(),
      version: state.marketIntegrity.legacySnapshot?.version || state.version || VERSION,
      closedTrades: derivedLegacyClosed,
      winRate: derivedLegacyWinRate ?? state.marketIntegrity.legacySnapshot?.winRate ?? null,
      netPnl: Number((aggregateNetPnl - Number(verified.netPnl || 0)).toFixed(4)),
      activeTradingCapital: Number(state.marketIntegrity.legacySnapshot?.activeTradingCapital || state.capital?.activeTradingCapital || 0),
      weeklyProfit: Number(state.marketIntegrity.legacySnapshot?.weeklyProfit || state.aggregateStats?.weeklyProfit || 0),
      recoveredFromAggregate: true,
      note: 'Legacy referencia az aggregált számláló és a verified epoch pontos különbsége; a részletesen minősíthető rekordok súlyozott tanulási priorrá válnak, a profit vault és verified tőke változatlanul elkülönül.'
    };
  }
  state.marketIntegrity.verifiedCapital = buildVerifiedCapitalVault(verifiedTradeMetrics(state), state);
  const historicalMissing = !state.marketIntegrity.historicalLearning?.lastRebuildAt || state.marketIntegrity.historicalLearning?.status === 'not-built';
  if (historicalMissing) rebuildHistoricalLearningFromLocalState(state, reason + '-historical-learning-bootstrap');
  else state.marketIntegrity.historicalLearning = updateCombinedLearningSummary(state.marketIntegrity.historicalLearning, state);
  let quarantined = 0;
  for (const order of asArray(state.orders)) {
    if (!isActiveOrder(order) || orderHasVerifiedMarketEntry(order)) continue;
    const lifecycle = asArray(order.lifecycle).map(x => String(x).toUpperCase());
    const hadExposure = lifecycle.some(x => ['ORDER_SUBMITTED', 'TESTNET_ORDER_SUBMITTED', 'EXCHANGE_ACCEPTED', 'POSITION_OPENED', 'POSITION_MARKED'].includes(x)) || /open|submitted|accepted|waiting/i.test(String(order.status || ''));
    if (!hadExposure) continue;
    order.status = 'legacy_quarantined_untrusted_market';
    order.quarantinedAt = order.quarantinedAt || now();
    order.quarantineReason = 'v199_132: v199_131 előtti vagy nem bizonyított friss-market belépés; nem zárható le és nem írható verified journalba.';
    order.marketIntegrityVersion = order.marketIntegrityVersion || 'legacy-pre-v199_131';
    if (!lifecycle.includes('LEGACY_QUARANTINED')) order.lifecycle = [...asArray(order.lifecycle), 'LEGACY_QUARANTINED'];
    order.currentStep = 'LEGACY_QUARANTINED';
    quarantined += 1;
  }
  state.marketIntegrity.quarantinedOrders = Math.max(Number(state.marketIntegrity.quarantinedOrders || 0), quarantined);
  if (quarantined) state.marketIntegrity.lastQuarantineAt = now();
  state.marketIntegrity.lastReconcileAt = now();
  state.marketIntegrity.lastReason = reason;
  syncVerifiedCapitalState(state, reason);
  syncVerifiedLearningTruth(state, reason);
  return state.marketIntegrity;
}

function marketIntegrityStatus(state = db) {
  const integrity = deepMerge(marketIntegrityDefaults(), state?.marketIntegrity || {});
  const verified = deepMerge(marketIntegrityStatsDefaults(), integrity.verifiedStats || {});
  const aggregateClosed = Number(state?.aggregateStats?.closedTrades || 0);
  const aggregateNetPnl = Number(state?.aggregateStats?.netPnl || 0);
  const derivedLegacyClosed = Math.max(0, aggregateClosed - Number(verified.closedTrades || 0));
  const derivedLegacyNetPnl = Number((aggregateNetPnl - Number(verified.netPnl || 0)).toFixed(4));
  const hasAggregateSplit = aggregateClosed > 0;
  const aggregateWins = Number(state?.aggregateStats?.wins || 0);
  const derivedLegacyWins = Math.max(0, aggregateWins - Number(verified.wins || 0));
  const legacy = {
    ...(integrity.legacySnapshot || {}),
    closedTrades: hasAggregateSplit ? derivedLegacyClosed : Number(integrity.legacySnapshot?.closedTrades || 0),
    winRate: hasAggregateSplit && derivedLegacyClosed > 0
      ? Number((derivedLegacyWins / derivedLegacyClosed * 100).toFixed(1))
      : (integrity.legacySnapshot?.winRate ?? null),
    netPnl: hasAggregateSplit ? derivedLegacyNetPnl : Number(integrity.legacySnapshot?.netPnl || 0),
    derivedFallback: hasAggregateSplit
  };
  return {
    ...integrity,
    verifiedStats: verified,
    verifiedCapital: buildVerifiedCapitalVault(verifiedTradeMetrics(state), state),
    legacySnapshot: legacy,
    historicalLearning: historicalLearningStatus(state),
    verifiedWarmup: Number(verified.closedTrades || 0) < VERIFIED_MARKET_MIN_SAMPLES_FOR_BOOSTS,
    boostsAllowed: Number(verified.closedTrades || 0) >= VERIFIED_MARKET_MIN_SAMPLES_FOR_BOOSTS,
    weightedLearningReady: Number(historicalLearningStatus(state).combinedEffectiveSamples || 0) >= LEARNING_GUARD_MIN_TRADES,
    verifiedMinSamplesForBoosts: VERIFIED_MARKET_MIN_SAMPLES_FOR_BOOSTS,
    activeVerifiedOrders: asArray(state?.orders).filter(o => isActiveOrder(o) && orderHasVerifiedMarketEntry(o)).length,
    activeLegacyOrders: asArray(state?.orders).filter(o => isActiveOrder(o) && !orderHasVerifiedMarketEntry(o)).length,
    policyLabel: 'Minősített régi trade-ek csökkentett súllyal segítik a tanulást; tőke, PnL és kivétel továbbra is csak verified journalból.'
  };
}


