    lastLiveAt: aggregateFresh ? latestTime : (previous.lastLiveAt || null),
    lastFallbackAt: fallback ? (snapshot.time || now()) : (previous.lastFallbackAt || null),
    fallbackStreak: fallback ? Number(previous.fallbackStreak || 0) + 1 : 0,
    simulatedFallbackStreak: simulated ? Number(previous.simulatedFallbackStreak || 0) + 1 : 0,
    degraded: !aggregateFresh && !!q.degradedMarketData,
    partialCoverage,
    freshMarketCount: coverage.freshCount,
    expectedMarketCount: coverage.expectedCount,
    freshMarkets: coverage.freshKeys,
    staleOrMissingMarkets: coverage.missingKeys,
    freshVenues: coverage.freshVenues,
    learningTrusted: aggregateFresh ? true : !!q.learningTrusted,
    orderSizeFactor: aggregateFresh ? 1 : (Number.isFinite(Number(q.orderSizeFactor)) ? Number(q.orderSizeFactor) : 1),
    confidenceLiftPct: aggregateFresh ? 0 : Number(q.confidenceLiftPct || 0),
    lastError: aggregateFresh ? null : (snapshot.error || snapshot.fallbackReason || previous.lastError || null),
    partialLastError: aggregateFresh && snapshotQuality.marketFallback ? (snapshot.error || snapshot.fallbackReason || null) : null,
    lastVenue: effectiveSnapshot?.venue || effectiveSnapshot?.venueKey || snapshot.venue || previous.lastVenue || null,
    lastSymbol: effectiveSnapshot?.symbol || snapshot.symbol || previous.lastSymbol || null,
    lastSnapshotId: effectiveSnapshot?.id || snapshot.id || previous.lastSnapshotId || null,
    lastEndpoint: effectiveSnapshot?.marketEndpoint || snapshot.marketEndpoint || previous.lastEndpoint || null,
    requestTimeoutMs: MARKET_DATA_REQUEST_TIMEOUT_MS,
    simulatedTradingAllowed: MARKET_DATA_ALLOW_SIMULATED_TRADING,
    recoveryActive: !aggregateFresh && fallback,
    recoveredAt: aggregateFresh && previous.degraded ? latestTime : (previous.recoveredAt || null),
    updatedAt: latestTime,
