function selfHealingRuntimeStatus(reason = 'status', allowAction = false) {
  db.selfHealingStatus = deepMerge({ version:'self-healing-runtime-1.0', state:'warmup', heartbeatAt:null, recoveryActions:[], executionAuthority:'single-replica-local', lastRecoveryAttemptAt:null }, db.selfHealingStatus || {});
  const nowMs = Date.now();
  const runtimeMs = Date.parse(db.lastRuntimeAt || '');
  const runtimeAgeMs = Number.isFinite(runtimeMs) ? Math.max(0, nowMs-runtimeMs) : null;
  const activeOrders = asArray(db.orders).filter(isActiveOrder);
  const uncertainOrders = activeOrders.filter(o => /uncertain|submit|reconcile|waiting_fresh|pending/i.test(String(o.status || o.currentStep || '')));
  const marketFresh = Number(db.marketDataHealth?.freshMarketCount ?? db.marketDataHealth?.fresh ?? 0);
  const marketExpected = Number(db.marketDataHealth?.expectedMarketCount ?? db.marketDataHealth?.expected ?? 0);
  const dbHealthy = db.supabaseHealth?.ok === true || /ok|healthy|connected/i.test(String(db.supabaseHealth?.status || ''));
  const blockers=[];
  if (db.autopilot && runtimeAgeMs !== null && runtimeAgeMs > 120000) blockers.push('trading-cycle-stale');
  if (marketExpected > 0 && marketFresh <= 0) blockers.push('market-data-unavailable');
  if (!dbHealthy && db.supabaseHealth?.lastCheckedAt) blockers.push('supabase-degraded');
  if (db.renderRecovery?.recoveryLock && !recoveryIsStartReady()) blockers.push('recovery-lock-active');
  const recoveryActions=[];
  const lastAttemptMs=Date.parse(db.selfHealingStatus.lastRecoveryAttemptAt || '');
  const cooldownOk=!Number.isFinite(lastAttemptMs) || nowMs-lastAttemptMs>120000;
  if (allowAction && blockers.includes('trading-cycle-stale') && db.autopilot && cooldownOk && !db.emergency && !(db.killSwitch === true || db.killSwitch?.active === true)) {
    db.selfHealingStatus.lastRecoveryAttemptAt=now();
    recoveryActions.push({ at:now(), action:'runtime-cycle-kick', reason:'stale-heartbeat', bounded:true });
    setTimeout(()=>runtimeCycle().catch(error=>pushIncident('warn','Self-healing runtime cycle hiba: '+(error.message||String(error)),{source:'self-healing-runtime'})),250);
  }
  if (uncertainOrders.length) recoveryActions.push({ at:now(), action:'reconciliation-required', count:uncertainOrders.length, automaticResubmit:false });
  db.selfHealingStatus = {
    ...db.selfHealingStatus,
    state:blockers.length?(recoveryActions.some(x=>x.action==='runtime-cycle-kick')?'recovering':'degraded'):'healthy',
    reason,
    heartbeatAt:db.lastRuntimeAt || null,
    runtimeAgeMs,
    market:{ fresh:marketFresh, expected:marketExpected },
    database:{ healthy:dbHealthy, status:db.supabaseHealth?.status || null },
    uncertainOrders:uncertainOrders.length,
    blockers,
    recoveryActions:[...recoveryActions,...asArray(db.selfHealingStatus.recoveryActions)].slice(0,30),
    executionAuthority:'single-railway-replica-required',
    failover:{ distributedLease:false, fencing:false, standbyActivated:false, status:'not-enabled-single-replica-safe-baseline' },
    policy:'bounded-retry-backoff-no-restart-loop-reconcile-before-resubmit'
  };
  return db.selfHealingStatus;
}

function updateRegimeTransitionForMarket(venue = 'binance', symbol = 'BTC/USDT', technical = {}, snapshotId = '') {
  db.regimeTransitions = asObject(db.regimeTransitions, {});
  const key = marketKey(venue, symbol).toLowerCase();
  const previous = asObject(db.regimeTransitions[key], {});
  if (snapshotId && previous.lastSnapshotId === snapshotId) return previous;
  const next = inferRegimeTransition(technical, previous, { volatility:technical?.volatility });
  const row = { ...next, venue:normalizeVenue(venue)||'binance', symbol:normalizeSymbol(symbol), lastSnapshotId:snapshotId || null, updatedAt:now() };
  db.regimeTransitions[key] = row;
  return row;
}

function refreshExchangeCapabilityTruth(reason = 'runtime') {
  db.exchangeCapabilityRegistry = buildExchangeCapabilityRegistry({
    exchanges: db.exchanges || {}, venueStatus: db.venueStatus || {}, testnetProofs: db.testnetProofs || [],
    learningVenues: learningMarketVenues(), liveAllowed: envFlag('NEXUS_ALLOW_LIVE', 'ALLOW_LIVE_TRADING') && envFlag('NEXUS_LIVE_REAL_SUBMIT', 'ALLOW_LIVE_ORDER_SUBMIT')
  });
  db.exchangeCapabilityRegistry.reason = reason;
  db.exchangeOnboarding = buildMultiExchangeOnboarding(db.exchangeCapabilityRegistry);
  db.exchangeOnboarding.reason = reason;
  return { registry:db.exchangeCapabilityRegistry, onboarding:db.exchangeOnboarding };
}

function normalizeTickerSnapshot({ venue, symbol, bid, ask, price, volume24h, source, rawSymbol, latencyMs, error, staleFromSnapshotId, staleAgeMs, fallbackReason, marketEndpoint, marketAttemptCount, marketTransport, marketEventTime, requestedVenue, marketSourceVenue, marketSourceSymbol, marketRoute, marketReferenceConfidence }) {
  const normalizedSymbol = normalizeSymbol(symbol);
  const numericBid = Number(bid || price || 0);
  const numericAsk = Number(ask || price || 0);
  const mid = Number(price || ((numericBid + numericAsk) / 2) || 0);
  const safeBid = numericBid > 0 ? numericBid : Number((mid * 0.9999).toFixed(8));
  const safeAsk = numericAsk > 0 ? numericAsk : Number((mid * 1.0001).toFixed(8));
  const spread = Math.max(0, safeAsk - safeBid);
  const spreadPct = mid > 0 ? Number((spread / mid * 100).toFixed(5)) : 0;
  const snapshot = {
    id: uid(),
    time: now(),
    timestamp: now(),
    venue: (normalizeVenue(venue) || venue || 'binance').toUpperCase(),
    venueKey: normalizeVenue(venue) || 'binance',
    symbol: normalizedSymbol,
    symbolCompact: compactSymbol(normalizedSymbol),
    rawSymbol: rawSymbol || symbolForVenue(normalizedSymbol, normalizeVenue(venue) || 'binance'),
    price: Number(mid.toFixed(8)),
    mid: Number(mid.toFixed(8)),
    quoteObserved: Number.isFinite(Number(bid)) && Number(bid)>0 && Number.isFinite(Number(ask)) && Number(ask)>=Number(bid),
    bid: Number(safeBid.toFixed(8)),
    ask: Number(safeAsk.toFixed(8)),
    spread: Number(spread.toFixed(8)),
    spreadPct,
    volume24h: Number(volume24h || 0),
    trend: 'range',
    volatility: volatilityClass(spreadPct, venue, normalizedSymbol),
    source: source || 'simulated_fallback',
    latencyMs: Number(latencyMs || 0),
    error: error || '',
    staleFromSnapshotId: staleFromSnapshotId || '',
    staleAgeMs: Number(staleAgeMs || 0),
    fallbackReason: fallbackReason || '',
    marketEndpoint: marketEndpoint || '',
    marketAttemptCount: Number(marketAttemptCount || 0),
    marketTransport: marketTransport || (String(source || '').includes('live_public') ? 'rest' : 'fallback'),
    marketEventTime: Number(marketEventTime || 0),
    requestedVenue: normalizeVenue(requestedVenue || venue) || normalizeVenue(venue) || 'binance',
    marketSourceVenue: normalizeVenue(marketSourceVenue || venue) || normalizeVenue(venue) || 'binance',
    marketSourceSymbol: marketSourceSymbol || rawSymbol || symbolForVenue(normalizedSymbol, normalizeVenue(marketSourceVenue || venue) || 'binance'),
    marketRoute: marketRoute || 'primary-venue',
    marketReferenceConfidence: Number.isFinite(Number(marketReferenceConfidence)) ? Number(marketReferenceConfidence) : 1
  };
  Object.assign(snapshot, marketDataQualityForSnapshot(snapshot));
  if (String(snapshot.source || '').toLowerCase() === 'live_public') {
    const technical = technicalMarketFeatures(snapshot.venueKey, normalizedSymbol, snapshot);
    snapshot.technical = technical;
    snapshot.trend = technical.trend;
    snapshot.volatility = technical.volatility;
  } else {
    snapshot.technical = {
      ready: false,
      sampleCount: 0,
      momentumSide: 'HOLD',
      momentumScore: 0,
      trend: 'range',
      volatility: snapshot.volatility,
      source: 'non-live-market-not-used-for-signal',
      policy: 'fallback-data-display-only'
    };
  }
  const historyRecord = recordMarketSeriesHistory(snapshot);
  if (snapshot.technical && typeof snapshot.technical === 'object') {
    snapshot.technical.historySeriesPoints = Number(historyRecord.perKeyCount || 0);
    snapshot.technical.liveHistorySeriesPoints = Number(historyRecord.livePerKeyCount || 0);
    snapshot.technical.historicalSeedPoints = Number(historyRecord.historicalPerKeyCount || 0);
    snapshot.technical.historyTargetPoints = WALK_FORWARD_LOOKBACK_POINTS;
  }
  updateMarketDataHealth(snapshot);
  db.marketState[marketKey(snapshot.venueKey, normalizedSymbol)] = snapshot;
  db.marketSnapshots.unshift(snapshot);
  db.marketSnapshots = db.marketSnapshots.slice(0, 400);
  supabaseInsert('market_snapshots', { id: snapshot.id, venue: snapshot.venue, symbol: snapshot.symbol, source: snapshot.source, price: snapshot.price, bid: snapshot.bid, ask: snapshot.ask, spread_pct: snapshot.spreadPct, payload: snapshot, created_at: snapshot.time });
  return snapshot;
}

function simulatedMarketSnapshot(venue = 'binance', symbol = 'BTC/USDT', reason = 'fallback') {
  const normalized = normalizeSymbol(symbol);
  const compact = compactSymbol(normalized);
  const baseMap = { BTCUSDT: 65000, ETHUSDT: 3200, SOLUSDT: 145 };
  const base = baseMap[compact] || 100;
  const seed = [...`${normalized}:${venue}:${db.cycle}:${Date.now().toString().slice(-4)}`].reduce((a, c) => a + c.charCodeAt(0), 0);
  const wave = Math.sin((Date.now() / 60000) + seed) * base * 0.0018;
  const drift = ((seed % 220) - 110) / 10000 * base;
  const mid = Math.max(0.0001, base + wave + drift);
  const spreadPct = 0.018 + ((seed % 8) / 1000);
  const spread = mid * spreadPct / 100;
  return normalizeTickerSnapshot({
    venue, symbol: normalized,
    bid: mid - spread / 2,
    ask: mid + spread / 2,
    price: mid,
    volume24h: 1000 + (seed % 9000),
    source: 'simulated_fallback',
    rawSymbol: symbolForVenue(normalized, normalizeVenue(venue) || 'binance'),
    latencyMs: 0,
    fallbackReason: String(reason || 'fallback').slice(0, 1200)
  });
}


const binancePublicStream = {
  socket: null,
  status: 'idle',
  endpoint: '',
  endpointIndex: 0,
  connectedAt: null,
  lastMessageAt: null,
  lastError: null,
  reconnectAttempts: 0,
  reconnectTimer: null,
  cache: {}
};

// v199_167: independent own-venue public WebSocket caches for Bybit, OKX and Kraken.
// These feeds are market data only and never count as private API authentication.
const venuePublicStreams = Object.fromEntries(['bybit', 'okx', 'kraken'].map(venue => [venue, {
  venue, socket: null, status: 'idle', endpoint: '', endpointIndex: 0, connectedAt: null,
  lastMessageAt: null, lastError: null, reconnectAttempts: 0, reconnectTimer: null, cache: {}
}]));
const VENUE_PUBLIC_STREAM_MAX_AGE_MS = Math.max(3000, Number(process.env.NEXUS_VENUE_WS_MAX_AGE_MS || MARKET_DATA_WS_MAX_AGE_MS));

function venuePublicStreamEndpoints(venue) {
  const v = normalizeVenue(venue);
  if (v === 'bybit') return [
    'wss://stream.bybit.eu/v5/public/spot',
    'wss://stream.bybit.com/v5/public/spot'
  ];
  if (v === 'okx') return [
    'wss://wseea.okx.com:8443/ws/v5/public',
    'wss://ws.okx.com:8443/ws/v5/public',
    'wss://wsaws.okx.com:8443/ws/v5/public'
  ];
  if (v === 'kraken') return ['wss://ws.kraken.com'];
  return [];
}

function publicStreamSubscriptionPayload(venue, onlySymbols = null) {
  const symbols = asArray(onlySymbols).length ? asArray(onlySymbols).map(normalizeSymbol).filter(Boolean) : normalizedSymbolWhitelist();
  if (venue === 'bybit') return { op: 'subscribe', args: symbols.map(symbol => `tickers.${compactSymbol(symbol)}`) };
  if (venue === 'okx') return { op: 'subscribe', args: symbols.map(symbol => ({ channel: 'tickers', instId: symbolForVenue(symbol, 'okx') })) };
  if (venue === 'kraken') return { event: 'subscribe', pair: symbols.map(symbol => symbol === 'BTC/USDT' ? 'XBT/USDT' : symbol), subscription: { name: 'ticker' } };
  return null;
}

function parseVenuePublicStreamMessage(venue, raw) {
  let text = raw;
  if (Buffer.isBuffer(text)) text = text.toString('utf8');
  if (typeof text === 'string' && ['pong', 'ping'].includes(text.trim().toLowerCase())) return null;
  const payload = typeof text === 'string' ? JSON.parse(text) : text;
  if (!payload) return null;

  if (venue === 'bybit') {
    if (payload.op === 'pong' || payload.op === 'subscribe') return null;
    const topic = String(payload.topic || '');
    const data = payload.data || {};
    // v199_179: lightweight official ticker topic is preferred; keep orderbook.1 parsing as backward-compatible fallback.
    if (topic.startsWith('tickers.')) {
      const symbol = normalizeSymbol(data.symbol || topic.split('.').pop() || '');
      const previous = venuePublicStreams.bybit?.cache?.[symbol] || {};
      const bid = Number(data.bid1Price || previous.bid || 0);
      const ask = Number(data.ask1Price || previous.ask || 0);
      const price = Number(data.lastPrice || 0) || ((bid + ask) / 2);
      if (!symbol || !(bid > 0) || !(ask > 0) || !(price > 0)) return null;
      return { symbol, rawSymbol: compactSymbol(symbol), bid, ask, price, volume24h: Number(data.turnover24h || data.volume24h || previous.volume24h || 0), eventTime: Number(payload.ts || Date.now()) };
    }
    if (!topic.startsWith('orderbook.1.')) return null;
    const symbol = normalizeSymbol(data.s || topic.split('.').pop() || '');
    const previous = venuePublicStreams.bybit?.cache?.[symbol] || {};
    const bid = Number(data.b?.[0]?.[0] || previous.bid || 0);
    const ask = Number(data.a?.[0]?.[0] || previous.ask || 0);
    if (!symbol || !(bid > 0) || !(ask > 0)) return null;
    return { symbol, rawSymbol: compactSymbol(symbol), bid, ask, price: (bid + ask) / 2, volume24h: Number(previous.volume24h || 0), eventTime: Number(payload.ts || Date.now()) };
  }

  if (venue === 'okx') {
    if (payload.event || String(payload.arg?.channel || '') !== 'tickers') return null;
    const row = payload.data?.[0] || {};
    const symbol = normalizeSymbol(row.instId || payload.arg?.instId || '');
    const bid = Number(row.bidPx || 0);
    const ask = Number(row.askPx || 0);
    const price = Number(row.last || 0) || ((bid + ask) / 2);
    if (!symbol || !(bid > 0) || !(ask > 0) || !(price > 0)) return null;
    return { symbol, rawSymbol: row.instId || symbolForVenue(symbol, 'okx'), bid, ask, price, volume24h: Number(row.volCcy24h || row.vol24h || 0), eventTime: Number(row.ts || Date.now()) };
  }

  if (venue === 'kraken') {
    if (!Array.isArray(payload) || payload.length < 4 || payload[2] !== 'ticker') return null;
    const row = payload[1] || {};
    const rawPair = String(payload[3] || '');
    const symbol = normalizeSymbol(rawPair.replace(/^XBT\//i, 'BTC/'));
    const bid = Number(row.b?.[0] || 0);
    const ask = Number(row.a?.[0] || 0);
    const price = Number(row.c?.[0] || 0) || ((bid + ask) / 2);
    if (!symbol || !(bid > 0) || !(ask > 0) || !(price > 0)) return null;
    return { symbol, rawSymbol: rawPair, bid, ask, price, volume24h: Number(row.v?.[1] || row.v?.[0] || 0), eventTime: Date.now() };
  }
  return null;
}

function clearVenuePublicReconnectTimer(venue) {
  const state = venuePublicStreams[venue];
  if (!state) return;
  if (state.reconnectTimer) clearTimeout(state.reconnectTimer);
  state.reconnectTimer = null;
}

function scheduleVenuePublicReconnect(venue, reason = 'closed') {
  const state = venuePublicStreams[venue];
  if (!state || !MARKET_DATA_WS_ENABLED || !WebSocketClient) return;
  clearVenuePublicReconnectTimer(venue);
  const waitMs = Math.min(30000, 1500 * (2 ** Math.min(Number(state.reconnectAttempts || 0), 4)));
  state.status = 'reconnecting';
  state.reconnectTimer = setTimeout(() => connectVenuePublicMarketStream(venue, reason), waitMs);
  state.reconnectTimer.unref?.();
}

function connectVenuePublicMarketStream(venue, reason = 'boot') {
  const v = normalizeVenue(venue);
  const state = venuePublicStreams[v];
  if (!state || !MARKET_DATA_WS_ENABLED || !WebSocketClient) return false;
  const current = state.socket;
  if (current && (current.readyState === WebSocketClient.OPEN || current.readyState === WebSocketClient.CONNECTING)) return true;
  clearVenuePublicReconnectTimer(v);
  const endpoints = venuePublicStreamEndpoints(v);
  if (!endpoints.length) return false;
  const endpoint = endpoints[state.endpointIndex % endpoints.length];
  state.endpoint = endpoint;
  state.status = 'connecting';
  let socket;
  try {
    socket = new WebSocketClient(endpoint, { handshakeTimeout: 10000, perMessageDeflate: false, headers: { 'User-Agent': 'NEXUS-public-market/199.169' } });
  } catch (error) {
    state.lastError = error?.message || String(error);
    state.reconnectAttempts += 1; state.endpointIndex = (state.endpointIndex + 1) % endpoints.length;
    scheduleVenuePublicReconnect(v, 'constructor-error'); return false;
  }
  state.socket = socket;
  socket.on('open', () => {
    state.status = 'connected'; state.connectedAt = now(); state.lastError = null; state.reconnectAttempts = 0;
    const sub = publicStreamSubscriptionPayload(v);
    if (sub) { try { socket.send(JSON.stringify(sub)); } catch (error) { state.lastError = 'subscribe: ' + (error?.message || String(error)); } }
  });
  socket.on('message', raw => {
    try {
      let control = null;
      try { const txt = Buffer.isBuffer(raw) ? raw.toString('utf8') : raw; control = typeof txt === 'string' ? JSON.parse(txt) : txt; } catch {}
      if ((control?.success === false) || control?.event === 'error') state.lastError = String(control?.ret_msg || control?.msg || control?.message || control?.code || 'subscription-error').slice(0, 500);
      const ticker = parseVenuePublicStreamMessage(v, raw);
      if (!ticker) return;
      state.cache[ticker.symbol] = { ...ticker, receivedAt: Date.now(), endpoint: state.endpoint };
      state.lastMessageAt = now(); state.status = 'connected'; state.lastError = null;
    } catch (error) { state.lastError = 'stream-parse: ' + (error?.message || String(error)); }
  });
  socket.on('error', error => { state.lastError = error?.message || String(error); });
  socket.on('close', (code, reasonBuffer) => {
    if (state.socket === socket) state.socket = null;
    const reasonText = Buffer.isBuffer(reasonBuffer) ? reasonBuffer.toString('utf8') : String(reasonBuffer || '');
    state.status = 'closed'; state.lastError = `close_${code}${reasonText ? ': ' + reasonText : ''}`;
    state.reconnectAttempts += 1; state.endpointIndex = (state.endpointIndex + 1) % endpoints.length;
    scheduleVenuePublicReconnect(v, 'close');
  });
  if (v === 'bybit') {
    const ping = setInterval(() => { if (socket.readyState === WebSocketClient.OPEN) { try { socket.send(JSON.stringify({ op: 'ping' })); } catch {} } }, 20000);
    ping.unref?.(); socket.once('close', () => clearInterval(ping));
  } else if (v === 'okx') {
    const ping = setInterval(() => { if (socket.readyState === WebSocketClient.OPEN) { try { socket.send('ping'); } catch {} } }, 20000);
    ping.unref?.(); socket.once('close', () => clearInterval(ping));
  }
  return true;
}

function ensureVenuePublicMarketStreams(reason = 'snapshot') {
  if (!MARKET_DATA_WS_ENABLED || !WebSocketClient) return false;
  const expectedSymbols = normalizedSymbolWhitelist();
  for (const venue of Object.keys(venuePublicStreams)) {
    const state = venuePublicStreams[venue];
    const lastMs = Date.parse(state.lastMessageAt || '');
    const connectedMs = Date.parse(state.connectedAt || '');
    const noDataTooLong = state.status === 'connected' && !Number.isFinite(lastMs) && Number.isFinite(connectedMs) && Date.now() - connectedMs > 30000;
    const staleSymbols = expectedSymbols.filter(symbol => {
      const ticker = state.cache?.[normalizeSymbol(symbol)];
      return !ticker || Date.now() - Number(ticker.receivedAt || 0) > Math.max(30000, VENUE_PUBLIC_STREAM_MAX_AGE_MS * 2);
    });
    const staleVenue = noDataTooLong || (Number.isFinite(lastMs) && Date.now() - lastMs > Math.max(30000, VENUE_PUBLIC_STREAM_MAX_AGE_MS * 2));
    const sessionExpired = Number.isFinite(connectedMs) && Date.now() - connectedMs >= MARKET_WS_SESSION_ROTATE_MS;
    const partialStale = state.status === 'connected' && staleSymbols.length > 0 && Number.isFinite(connectedMs) && Date.now() - connectedMs > 30000;
    if (partialStale && state.socket?.readyState === WebSocketClient.OPEN) {
      const lastResub = Date.parse(state.lastResubscribeAt || '');
      if (!Number.isFinite(lastResub) || Date.now() - lastResub > 15000) {
        try {
          const sub = publicStreamSubscriptionPayload(venue, staleSymbols);
          if (sub) state.socket.send(JSON.stringify(sub));
          state.lastResubscribeAt = now();
          state.lastResubscribeSymbols = staleSymbols;
        } catch (error) { state.lastError = 'resubscribe: ' + (error?.message || String(error)); }
      }
    }
    const forceRotate = sessionExpired || staleVenue || (partialStale && staleSymbols.length >= expectedSymbols.length);
    if (forceRotate && state.socket) { try { state.socket.terminate(); } catch {} state.socket = null; }
    if (!state.socket || ['idle', 'closed'].includes(state.status) || forceRotate) connectVenuePublicMarketStream(venue, reason);
  }
  return true;
}

function freshVenuePublicStreamTicker(venue, symbol) {
  const v = normalizeVenue(venue);
  if (v === 'binance') return freshBinancePublicStreamTicker(symbol);
  const state = venuePublicStreams[v];
  const ticker = state?.cache?.[normalizeSymbol(symbol)];
  if (!ticker) return null;
  const ageMs = Math.max(0, Date.now() - Number(ticker.receivedAt || 0));
  if (ageMs > VENUE_PUBLIC_STREAM_MAX_AGE_MS) return null;
  return { ...ticker, ageMs };
}

function venuePublicStreamsStatus() {
  const result = { binance: publicMarketStreamStatus() };
  for (const [venue, state] of Object.entries(venuePublicStreams)) {
    const lastMs = Date.parse(state.lastMessageAt || '');
    const expectedSymbols = normalizedSymbolWhitelist();
    const freshSymbols = expectedSymbols.filter(symbol => {
      const ticker = state.cache?.[normalizeSymbol(symbol)];
      return ticker && Date.now() - Number(ticker.receivedAt || 0) <= VENUE_PUBLIC_STREAM_MAX_AGE_MS;
    });
    result[venue] = { enabled: MARKET_DATA_WS_ENABLED, clientAvailable: !!WebSocketClient, status: state.status, endpoint: state.endpoint, connectedAt: state.connectedAt, lastMessageAt: state.lastMessageAt, lastMessageAgeMs: Number.isFinite(lastMs) ? Math.max(0, Date.now() - lastMs) : null, reconnectAttempts: Number(state.reconnectAttempts || 0), lastError: state.lastError || null, cachedSymbols: Object.keys(state.cache || {}), freshSymbols, staleSymbols: expectedSymbols.filter(symbol => !freshSymbols.includes(symbol)), lastResubscribeAt: state.lastResubscribeAt || null };
  }
  return result;
}


function marketGuardianRuntimeStatus() {
  const heartbeatMs = Date.parse(marketGuardianStatus.lastHeartbeatAt || '');
  const tickerMs = Date.parse(marketGuardianStatus.lastTickerAt || '');
  return {
    ...marketGuardianStatus,
    heartbeatAgeMs: Number.isFinite(heartbeatMs) ? Math.max(0, Date.now() - heartbeatMs) : null,
    tickerAgeMs: Number.isFinite(tickerMs) ? Math.max(0, Date.now() - tickerMs) : null,
    alive: !!marketGuardianWorker && Number.isFinite(heartbeatMs) && Date.now() - heartbeatMs <= MARKET_GUARDIAN_STALE_MS,
    policy: 'independent-own-venue-ipv4-rest-worker'
  };
}

function ingestMarketGuardianTicker(message = {}) {
  if (!dbReady) return null;
  const venue = normalizeVenue(message.venue);
  const symbol = normalizeSymbol(message.symbol);
  if (!venue || !normalizedSymbolWhitelist().includes(symbol)) return null;
  const bid = Number(message.bid || 0);
  const ask = Number(message.ask || 0);
  const price = Number(message.price || 0) || ((bid + ask) / 2);
  if (!(bid > 0) || !(ask > 0) || !(price > 0)) return null;
  const snap = normalizeTickerSnapshot({
    venue,
    requestedVenue: venue,
    marketSourceVenue: venue,
    marketSourceSymbol: symbolForVenue(symbol, venue),
    marketRoute: 'own-venue-guardian-rest',
    marketReferenceConfidence: 1,
    symbol,
    rawSymbol: symbolForVenue(symbol, venue),
    bid,
    ask,
    price,
    volume24h: Number(message.volume24h || 0),
    source: 'live_public',
    latencyMs: Math.max(0, Number(message.latencyMs || 0)),
    marketEndpoint: String(message.endpoint || ''),
    marketAttemptCount: 1,
    marketTransport: 'worker-rest-ipv4',
    marketEventTime: Number(message.eventTime || Date.now())
  });
  marketGuardianStatus.status = 'streaming';
  marketGuardianStatus.lastTickerAt = now();
  marketGuardianStatus.lastSuccessAt = now();
  marketGuardianStatus.lastError = null;
  return snap;
}

function stopMarketGuardianWorker(reason = 'stop') {
  const worker = marketGuardianWorker;
  marketGuardianWorker = null;
  if (marketGuardianRestartTimer) {
    clearTimeout(marketGuardianRestartTimer);
    marketGuardianRestartTimer = null;
  }
  marketGuardianStatus.status = 'stopping';
  if (!worker) return false;
  try { worker.postMessage({ type: 'stop', reason }); } catch {}
  setTimeout(() => { try { worker.terminate(); } catch {} }, 500).unref?.();
  return true;
}

function scheduleMarketGuardianRestart(reason = 'restart') {
  if (!MARKET_GUARDIAN_ENABLED || !WorkerThread || marketGuardianRestartTimer || shutdownInProgress) return false;
  const since = Date.now() - Number(marketGuardianLastRestartAt || 0);
  const waitMs = Math.max(250, MARKET_GUARDIAN_RESTART_COOLDOWN_MS - Math.max(0, since));
  marketGuardianStatus.status = 'restarting';
  marketGuardianStatus.lastError = String(reason || 'restart');
  marketGuardianRestartTimer = setTimeout(() => {
    marketGuardianRestartTimer = null;
    startMarketGuardianWorker(reason, true);
  }, waitMs);
  marketGuardianRestartTimer.unref?.();
  return true;
}

function startMarketGuardianWorker(reason = 'boot', force = false) {
  if (!MARKET_GUARDIAN_ENABLED) {
    marketGuardianStatus = { ...marketGuardianStatus, enabled: false, status: 'disabled' };
    return false;
  }
  if (!WorkerThread) {
    marketGuardianStatus = { ...marketGuardianStatus, status: 'unavailable', lastError: 'worker_threads unavailable' };
    return false;
  }
  if (marketGuardianWorker && !force) return true;
  if (marketGuardianWorker && force) stopMarketGuardianWorker('forced-restart');
  const workerPath = path.join(ROOT, 'backend', 'services', 'marketGuardianWorker.cjs');
  try {
    const worker = new WorkerThread(workerPath, {
      workerData: {
        dispatchMs: MARKET_GUARDIAN_DISPATCH_MS,
        requestTimeoutMs: MARKET_GUARDIAN_REQUEST_TIMEOUT_MS,
        maxInflight: MARKET_GUARDIAN_MAX_INFLIGHT,
        heartbeatMs: MARKET_GUARDIAN_HEARTBEAT_MS
      }
    });
    marketGuardianWorker = worker;
    marketGuardianLastRestartAt = Date.now();
    marketGuardianStatus = {
      ...marketGuardianStatus,
      enabled: true,
      status: 'starting',
      startedAt: now(),
      lastError: null,
      restartCount: Number(marketGuardianStatus.restartCount || 0) + (reason === 'boot' ? 0 : 1)
    };
    worker.on('message', message => {
      if (worker !== marketGuardianWorker) return;
      if (message?.type === 'ticker') {
        marketGuardianStatus.successes = Number(marketGuardianStatus.successes || 0) + 1;
        ingestMarketGuardianTicker(message);
      } else if (message?.type === 'heartbeat') {
        marketGuardianStatus.status = 'healthy';
        marketGuardianStatus.lastHeartbeatAt = now();
        marketGuardianStatus.lastSuccessAt = message.lastSuccessAt || marketGuardianStatus.lastSuccessAt || null;
        marketGuardianStatus.successes = Math.max(Number(marketGuardianStatus.successes || 0), Number(message.successes || 0));
        marketGuardianStatus.failures = Number(message.failures || 0);
        marketGuardianStatus.perMarket = message.perMarket || {};
      }
    });
    worker.on('error', error => {
      if (worker !== marketGuardianWorker) return;
      marketGuardianStatus.lastError = error?.message || String(error);
      marketGuardianStatus.status = 'error';
    });
    worker.on('exit', code => {
      if (worker !== marketGuardianWorker) return;
      marketGuardianWorker = null;
      marketGuardianStatus.status = code === 0 ? 'stopped' : 'exited';
      if (code !== 0) marketGuardianStatus.lastError = `worker_exit_${code}`;
      if (!shutdownInProgress) scheduleMarketGuardianRestart(`worker-exit-${code}`);
    });
    return true;
  } catch (error) {
    marketGuardianStatus.status = 'error';
    marketGuardianStatus.lastError = error?.message || String(error);
    scheduleMarketGuardianRestart('worker-constructor-error');
    return false;
  }
}

function marketGuardianWatchdogTick() {
  if (!MARKET_GUARDIAN_ENABLED || !dbReady || shutdownInProgress) return;
  if (!marketGuardianWorker) {
    startMarketGuardianWorker('watchdog-no-worker');
    return;
  }
  const hb = Date.parse(marketGuardianStatus.lastHeartbeatAt || '');
  const started = Date.parse(marketGuardianStatus.startedAt || '');
  const age = Number.isFinite(hb) ? Date.now() - hb : (Number.isFinite(started) ? Date.now() - started : Infinity);
  if (age > MARKET_GUARDIAN_STALE_MS) {
    const old = marketGuardianWorker;
    marketGuardianWorker = null;
    try { old.terminate(); } catch {}
    marketGuardianStatus.status = 'stale-restart';
    marketGuardianStatus.lastError = `heartbeat_stale_${Math.round(age)}ms`;
    scheduleMarketGuardianRestart('heartbeat-stale');
  }
}

const marketRestBackoff = {};
const marketHistorySeedInflight = new Map();
const marketHistorySeedStatus = {};
let marketHistorySeedBootQueued = false;
const marketRestInflight = new Map();
const marketProviderRouter = {};

function marketProviderRouteState(requestedVenue = 'binance', symbol = 'BTC/USDT') {
  const key = `${normalizeVenue(requestedVenue) || requestedVenue}:${normalizeSymbol(symbol)}`;
  if (!marketProviderRouter[key]) {
    marketProviderRouter[key] = {
      requestedVenue: normalizeVenue(requestedVenue) || 'binance',
      symbol: normalizeSymbol(symbol),
      preferredProvider: normalizeVenue(requestedVenue) || 'binance',
      stickyUntil: 0,
      nextPrimaryProbeAt: 0,
      primaryFailures: 0,
      lastPrimaryError: null,
      lastProviderError: null,
      lastSuccessAt: null,
      lastSwitchAt: null
    };
  }
  return { key, state: marketProviderRouter[key] };
}

function noteMarketProviderPrimarySuccess(requestedVenue, symbol) {
  const { state } = marketProviderRouteState(requestedVenue, symbol);
  state.preferredProvider = normalizeVenue(requestedVenue) || 'binance';
  state.stickyUntil = 0;
  state.nextPrimaryProbeAt = 0;
  state.primaryFailures = 0;
  state.lastPrimaryError = null;
  state.lastProviderError = null;
  state.lastSuccessAt = now();
  return state;
}

function noteMarketProviderPrimaryFailure(requestedVenue, symbol, error) {
  const { state } = marketProviderRouteState(requestedVenue, symbol);
  state.primaryFailures = Number(state.primaryFailures || 0) + 1;
  state.lastPrimaryError = String(error || 'primary-market-failed').slice(0, 1200);
  state.nextPrimaryProbeAt = Date.now() + MARKET_DATA_PRIMARY_REPROBE_MS;
  return state;
}

function noteMarketProviderFallbackSuccess(requestedVenue, symbol, providerVenue) {
  const { state } = marketProviderRouteState(requestedVenue, symbol);
  const provider = normalizeVenue(providerVenue) || providerVenue;
  const changed = state.preferredProvider !== provider;
  state.preferredProvider = provider;
  state.stickyUntil = Date.now() + MARKET_DATA_PROVIDER_STICKY_MS;
  state.nextPrimaryProbeAt = Date.now() + MARKET_DATA_PRIMARY_REPROBE_MS;
  state.lastProviderError = null;
  state.lastSuccessAt = now();
  if (changed) state.lastSwitchAt = now();
  return { ...state, changed };
}

function marketProviderRouterStatus() {
  return Object.fromEntries(Object.entries(marketProviderRouter).map(([key, state]) => [key, {
    requestedVenue: state.requestedVenue,
    symbol: state.symbol,
    preferredProvider: state.preferredProvider,
    stickyRemainingMs: Math.max(0, Number(state.stickyUntil || 0) - Date.now()),
    primaryProbeInMs: Math.max(0, Number(state.nextPrimaryProbeAt || 0) - Date.now()),
    primaryFailures: Number(state.primaryFailures || 0),
    lastPrimaryError: state.lastPrimaryError || null,
    lastProviderError: state.lastProviderError || null,
    lastSuccessAt: state.lastSuccessAt || null,
    lastSwitchAt: state.lastSwitchAt || null
  }]));
}

function binancePublicStreamEndpoints() {
  const streams = ['btcusdt@ticker', 'ethusdt@ticker', 'solusdt@ticker'].join('/');
  return [
    `wss://data-stream.binance.vision:443/stream?streams=${streams}`,
    `wss://stream.binance.com:443/stream?streams=${streams}`
  ];
}

function publicMarketStreamStatus() {
  const lastMessageMs = Date.parse(binancePublicStream.lastMessageAt || '');
  const expectedSymbols = normalizedSymbolWhitelist();
  const freshSymbols = expectedSymbols.filter(symbol => {
    const ticker = binancePublicStream.cache?.[normalizeSymbol(symbol)];
    return ticker && Date.now() - Number(ticker.receivedAt || 0) <= MARKET_DATA_WS_MAX_AGE_MS;
  });
  return {
    enabled: MARKET_DATA_WS_ENABLED,
    clientAvailable: !!WebSocketClient,
    status: binancePublicStream.status,
    endpoint: binancePublicStream.endpoint,
    connectedAt: binancePublicStream.connectedAt,
    lastMessageAt: binancePublicStream.lastMessageAt,
    lastMessageAgeMs: Number.isFinite(lastMessageMs) ? Math.max(0, Date.now() - lastMessageMs) : null,
    reconnectAttempts: Number(binancePublicStream.reconnectAttempts || 0),
    lastError: binancePublicStream.lastError || null,
    cachedSymbols: Object.keys(binancePublicStream.cache || {}),
    freshSymbols,
    staleSymbols: expectedSymbols.filter(symbol => !freshSymbols.includes(symbol)),
    perSymbolAgeMs: Object.fromEntries(expectedSymbols.map(symbol => {
      const ticker = binancePublicStream.cache?.[normalizeSymbol(symbol)];
      return [normalizeSymbol(symbol), ticker ? Math.max(0, Date.now() - Number(ticker.receivedAt || 0)) : null];
    }))
  };
}

function clearBinanceStreamReconnectTimer() {
  if (binancePublicStream.reconnectTimer) clearTimeout(binancePublicStream.reconnectTimer);
  binancePublicStream.reconnectTimer = null;
}

function scheduleBinancePublicStreamReconnect(reason = 'stream-closed') {
  if (!MARKET_DATA_WS_ENABLED || !WebSocketClient) return;
  clearBinanceStreamReconnectTimer();
  const attempts = Number(binancePublicStream.reconnectAttempts || 0);
  const delay = Math.min(60000, Math.max(1000, 1000 * (2 ** Math.min(attempts, 6))));
  binancePublicStream.status = 'reconnecting';
  binancePublicStream.reconnectTimer = setTimeout(() => {
    binancePublicStream.reconnectTimer = null;
    connectBinancePublicMarketStream(reason);
  }, delay);
}

function parseBinanceTickerStreamMessage(raw) {
  let text = raw;
  if (Buffer.isBuffer(raw)) text = raw.toString('utf8');
  if (raw && typeof raw === 'object' && raw.data !== undefined && !Buffer.isBuffer(raw)) text = raw.data;
  if (Buffer.isBuffer(text)) text = text.toString('utf8');
  const payload = typeof text === 'string' ? JSON.parse(text) : text;
  const row = payload?.data || payload || {};
  const symbol = normalizeSymbol(row.s || '');
  const bid = Number(row.b);
  const ask = Number(row.a);
  const price = Number(row.c);
  if (!symbol || !(bid > 0) || !(ask > 0) || !(price > 0)) return null;
  return {
    symbol,
    rawSymbol: String(row.s || compactSymbol(symbol)),
    bid,
    ask,
    price,
    volume24h: Number(row.q || row.v || 0),
    eventTime: Number(row.E || Date.now()),
    receivedAt: Date.now(),
    endpoint: binancePublicStream.endpoint
  };
}

function connectBinancePublicMarketStream(reason = 'boot') {
  if (!MARKET_DATA_WS_ENABLED) {
    binancePublicStream.status = 'disabled';
    return false;
  }
  if (!WebSocketClient) {
    binancePublicStream.status = 'rest-continuity';
    binancePublicStream.lastError = 'ws dependency unavailable; own-venue REST continuity active';
    return false;
  }
  const current = binancePublicStream.socket;
  if (current && (current.readyState === WebSocketClient.OPEN || current.readyState === WebSocketClient.CONNECTING)) return true;

  clearBinanceStreamReconnectTimer();
  const endpoints = binancePublicStreamEndpoints();
  const endpoint = endpoints[binancePublicStream.endpointIndex % endpoints.length];
  binancePublicStream.endpoint = endpoint;
  binancePublicStream.status = 'connecting';

  let socket;
  try {
    socket = new WebSocketClient(endpoint, {
      handshakeTimeout: 10000,
      perMessageDeflate: false,
      headers: { 'User-Agent': 'NEXUS-market-stream/199.131' }
    });
  } catch (error) {
    binancePublicStream.lastError = error?.message || String(error);
    binancePublicStream.reconnectAttempts += 1;
    binancePublicStream.endpointIndex = (binancePublicStream.endpointIndex + 1) % endpoints.length;
    scheduleBinancePublicStreamReconnect('constructor-error');
    return false;
  }

  binancePublicStream.socket = socket;

  socket.on('open', () => {
    const recovered = binancePublicStream.status === 'reconnecting' || Number(binancePublicStream.reconnectAttempts || 0) > 0;
    binancePublicStream.status = 'connected';
    binancePublicStream.connectedAt = now();
    binancePublicStream.lastError = null;
    binancePublicStream.reconnectAttempts = 0;
    if (dbReady && recovered) {
      pushEvent('market', 'Binance public WebSocket kapcsolat helyreállt; friss ticker stream aktív.', {
        source: 'market-data-websocket',
        endpoint,
        reason,
        severity: 'info'
      });
    }
  });

  socket.on('message', raw => {
    try {
      const ticker = parseBinanceTickerStreamMessage(raw);
      if (!ticker) return;
      binancePublicStream.cache[ticker.symbol] = ticker;
      binancePublicStream.lastMessageAt = new Date(ticker.receivedAt).toISOString();
      binancePublicStream.status = 'connected';
      binancePublicStream.lastError = null;
    } catch (error) {
      binancePublicStream.lastError = 'stream-parse: ' + (error?.message || String(error));
    }
  });

  socket.on('error', error => {
    binancePublicStream.lastError = error?.message || String(error);
  });

  socket.on('close', (code, reasonBuffer) => {
    if (binancePublicStream.socket === socket) binancePublicStream.socket = null;
    const reasonText = Buffer.isBuffer(reasonBuffer) ? reasonBuffer.toString('utf8') : String(reasonBuffer || '');
    binancePublicStream.status = 'closed';
    binancePublicStream.lastError = `close_${code}${reasonText ? ': ' + reasonText : ''}`;
    binancePublicStream.reconnectAttempts += 1;
    binancePublicStream.endpointIndex = (binancePublicStream.endpointIndex + 1) % endpoints.length;
    scheduleBinancePublicStreamReconnect('close');
  });

  return true;
}

function freshBinancePublicStreamTicker(symbol = 'BTC/USDT') {
  const normalized = normalizeSymbol(symbol);
  const ticker = binancePublicStream.cache?.[normalized];
  if (!ticker) return null;
  const ageMs = Math.max(0, Date.now() - Number(ticker.receivedAt || 0));
  if (ageMs > MARKET_DATA_WS_MAX_AGE_MS) return null;
  return { ...ticker, ageMs };
}

function ensureBinancePublicMarketStream(reason = 'snapshot') {
  if (MARKET_DATA_WS_ENABLED && !WebSocketClient) { binancePublicStream.status = 'rest-continuity'; return false; }
  if (!MARKET_DATA_WS_ENABLED) return false;
  const status = binancePublicStream.status;
  const expectedSymbols = normalizedSymbolWhitelist();
  const connectedMs = Date.parse(binancePublicStream.connectedAt || '');
  const lastMs = Date.parse(binancePublicStream.lastMessageAt || '');
  const staleLimitMs = Math.max(30000, MARKET_DATA_WS_MAX_AGE_MS * 2);
  const staleSymbols = expectedSymbols.filter(symbol => {
    const ticker = binancePublicStream.cache?.[normalizeSymbol(symbol)];
    return !ticker || Date.now() - Number(ticker.receivedAt || 0) > staleLimitMs;
  });
  const noDataTooLong = status === 'connected' && !Number.isFinite(lastMs) && Number.isFinite(connectedMs) && Date.now() - connectedMs > 30000;
  const wholeVenueStale = noDataTooLong || (staleSymbols.length >= expectedSymbols.length && Number.isFinite(connectedMs) && Date.now() - connectedMs > 30000);
  // Binance combined streams cannot selectively re-subscribe: if any symbol stays stale while the
  // connection itself still receives other symbols, rotate the combined stream so all 3 symbols recover.
  const partialStaleTooLong = status === 'connected' && staleSymbols.length > 0 && Number.isFinite(connectedMs) && Date.now() - connectedMs > 45000;
  const sessionExpired = Number.isFinite(connectedMs) && Date.now() - connectedMs >= MARKET_WS_SESSION_ROTATE_MS;
  const stale = sessionExpired || wholeVenueStale || partialStaleTooLong || (Number.isFinite(lastMs) && Date.now() - lastMs > staleLimitMs);
  if (stale && binancePublicStream.socket) {
    binancePublicStream.lastError = `symbol-selfheal:${staleSymbols.join(',') || 'venue-stale'}`;
    try { binancePublicStream.socket.terminate(); } catch {}
    binancePublicStream.socket = null;
  }
  if (!binancePublicStream.socket || ['idle', 'closed', 'client-unavailable'].includes(status) || stale) {
    return connectBinancePublicMarketStream(reason);
  }
  return true;
}

function hardResetPublicMarketTransports(reason = 'empty-market-hard-reset') {
  const stamp = now();
  marketHardResetCount += 1;
  marketLastHardResetAt = stamp;

  try { clearBinanceStreamReconnectTimer(); } catch {}
  try { binancePublicStream.socket?.terminate(); } catch {}
  binancePublicStream.socket = null;
  binancePublicStream.status = 'idle';
  binancePublicStream.lastError = `hard-reset:${reason}`;
  binancePublicStream.reconnectAttempts = 0;
  binancePublicStream.endpointIndex = (Number(binancePublicStream.endpointIndex || 0) + 1) % Math.max(1, binancePublicStreamEndpoints().length);
  binancePublicStream.cache = {};
  binancePublicStream.lastMessageAt = null;
  binancePublicStream.connectedAt = null;

  for (const [venue, state] of Object.entries(venuePublicStreams)) {
    try { clearVenuePublicReconnectTimer(venue); } catch {}
    try { state.socket?.terminate(); } catch {}
    state.socket = null;
    state.status = 'idle';
    state.lastError = `hard-reset:${reason}`;
    state.reconnectAttempts = 0;
    const endpoints = venuePublicStreamEndpoints(venue);
    state.endpointIndex = endpoints.length ? (Number(state.endpointIndex || 0) + 1) % endpoints.length : 0;
    state.cache = {};
    state.lastMessageAt = null;
    state.connectedAt = null;
    state.lastResubscribeAt = null;
    state.lastResubscribeSymbols = [];
  }

  for (const key of Object.keys(marketRestBackoff)) delete marketRestBackoff[key];
  for (const key of Object.keys(marketProviderRouter)) {
    const state = marketProviderRouter[key];
    if (!state) continue;
    state.preferredProvider = state.requestedVenue || 'binance';
    state.stickyUntil = 0;
    state.nextPrimaryProbeAt = 0;
    state.primaryFailures = 0;
    state.lastPrimaryError = null;
    state.lastProviderError = null;
    state.lastSwitchAt = stamp;
  }
  for (const key of Object.keys(marketRestEndpointCursor)) marketRestEndpointCursor[key] = Number(marketRestEndpointCursor[key] || 0) + 1;
  try { marketGuardianWorker?.postMessage({ type: 'reset', reason }); } catch {}

  setTimeout(() => {
    try { ensureBinancePublicMarketStream(`hard-reset-${reason}`); } catch {}
    try { ensureVenuePublicMarketStreams(`hard-reset-${reason}`); } catch {}
  }, 250).unref?.();

  if (dbReady) pushEvent('market', 'Public market transport teljes újraépítés indult: WS socketek, REST backoff és provider sticky állapot újraindítva.', {
    source: 'v199_178-durable-market-recovery', reason, hardResetCount: marketHardResetCount, severity: 'warn'
  });
  return { at: stamp, reason, hardResetCount: marketHardResetCount };
}

function marketRestBackoffState(venue, symbol) {
  const key = `${normalizeVenue(venue) || venue}:${normalizeSymbol(symbol)}`;
  return { key, state: marketRestBackoff[key] || { failures: 0, nextAttemptAt: 0, lastError: null } };
}

function noteMarketRestSuccess(venue, symbol) {
  const { key } = marketRestBackoffState(venue, symbol);
  marketRestBackoff[key] = { failures: 0, nextAttemptAt: 0, lastError: null, lastOkAt: now() };
}

function noteMarketRestFailure(venue, symbol, error) {
  const { key, state } = marketRestBackoffState(venue, symbol);
  const failures = Number(state.failures || 0) + 1;
  const delay = Math.min(MARKET_DATA_REST_BACKOFF_MAX_MS, MARKET_DATA_REST_BACKOFF_MIN_MS * (2 ** Math.min(failures - 1, 4)));
  marketRestBackoff[key] = {
    failures,
    nextAttemptAt: Date.now() + delay,
    lastError: String(error || 'rest-market-failed').slice(0, 1200),
    lastFailureAt: now(),
    backoffMs: delay
  };
  return marketRestBackoff[key];
}

function marketRestRequestAllowed(venue, symbol) {
  const { state } = marketRestBackoffState(venue, symbol);
  return Date.now() >= Number(state.nextAttemptAt || 0);
}

function marketSnapshotAgeMs(snapshot = {}) {
  const eventMs = Number(snapshot.marketEventTime || 0);
  if (eventMs > 0) return Math.max(0, Date.now() - eventMs);
  const parsed = Date.parse(snapshot.time || snapshot.timestamp || '');
  return Number.isFinite(parsed) ? Math.max(0, Date.now() - parsed) : Infinity;
}

function marketSnapshotIsFreshTrusted(snapshot = {}) {
  const quality = marketDataQualityForSnapshot(snapshot);
  return String(quality.dataQuality || '').startsWith('live-public') &&
    quality.learningTrusted === true &&
    marketSnapshotAgeMs(snapshot) <= MARKET_DATA_TRADE_MAX_AGE_MS;
}


function marketDataEndpointCandidates(venue, rawSymbol) {
  const v = normalizeVenue(venue) || 'binance';
  const symbol = encodeURIComponent(rawSymbol);
  const venueOverrideKey = `NEXUS_MARKET_DATA_${v.toUpperCase()}_URLS`;
  const overrideTemplate = String(process.env[venueOverrideKey] || process.env.NEXUS_MARKET_DATA_OVERRIDE_URL || '').trim();
  const overrides = overrideTemplate
    ? overrideTemplate.split(',').map(item => item.trim()).filter(Boolean).map(item => item
      .replaceAll('{venue}', encodeURIComponent(v))
      .replaceAll('{symbol}', symbol)
      .replaceAll('{rawSymbol}', symbol))
    : [];
  let official = [];
  if (v === 'binance') {
    official = [
      `https://data-api.binance.vision/api/v3/ticker/24hr?symbol=${symbol}`,
      `https://data-api.binance.vision/api/v3/ticker/bookTicker?symbol=${symbol}`,
      `https://api.binance.com/api/v3/ticker/24hr?symbol=${symbol}`,
      `https://api.binance.com/api/v3/ticker/bookTicker?symbol=${symbol}`,
      `https://api-gcp.binance.com/api/v3/ticker/24hr?symbol=${symbol}`,
      `https://api1.binance.com/api/v3/ticker/24hr?symbol=${symbol}`,
      `https://api2.binance.com/api/v3/ticker/24hr?symbol=${symbol}`,
      `https://api3.binance.com/api/v3/ticker/24hr?symbol=${symbol}`,
      `https://api4.binance.com/api/v3/ticker/24hr?symbol=${symbol}`
    ];
  } else if (v === 'bybit') {
    // Bybit documents regional API domains and explicitly blocks US/Mainland-China IPs on api.bybit.com.
    // The router therefore races EEA + global official hosts instead of assuming one deployment region.
    official = [
      `https://api.bybit.eu/v5/market/tickers?category=spot&symbol=${symbol}`,
      `https://api.bybit.com/v5/market/tickers?category=spot&symbol=${symbol}`,
      `https://api.bytick.com/v5/market/tickers?category=spot&symbol=${symbol}`,
      `https://api.bybit.nl/v5/market/tickers?category=spot&symbol=${symbol}`
    ];
  } else if (v === 'okx') {
    // OKX documents eea.okx.com for EEA accounts and regional API routing.
    official = [
      `https://openapi.okx.com/api/v5/market/ticker?instId=${symbol}`,
      `https://eea.okx.com/api/v5/market/ticker?instId=${symbol}`,
      `https://www.okx.com/api/v5/market/ticker?instId=${symbol}`,
      `https://app.okx.com/api/v5/market/ticker?instId=${symbol}`,
      `https://us.okx.com/api/v5/market/ticker?instId=${symbol}`
    ];
  } else if (v === 'kraken') {
    official = [
      `https://api.kraken.com/0/public/Ticker?pair=${symbol}`
    ];
  }
  // v199_159: an old Render override may be useful as a preferred route, but it must never replace
  // all official endpoints. This directly prevents a stale ENV value from producing fresh 0/12 forever.
  return [...new Set([...overrides, ...official])];
}

function tickerPayloadLooksValid(venue, json) {
  const v = normalizeVenue(venue) || 'binance';
  if (v === 'binance') return Number(json?.bidPrice) > 0 && Number(json?.askPrice) > 0 && (Number(json?.lastPrice) > 0 || (Number(json?.bidPrice) + Number(json?.askPrice)) > 0);
  if (v === 'bybit') {
    const row = json?.result?.list?.[0] || {};
    return Number(row.lastPrice) > 0 && Number(row.bid1Price) > 0 && Number(row.ask1Price) > 0;
  }
  if (v === 'okx') {
    const row = json?.data?.[0] || {};
    return Number(row.last) > 0 && Number(row.bidPx) > 0 && Number(row.askPx) > 0;
  }
  if (v === 'kraken') {
    const row = Object.values(json?.result || {})[0] || {};
    return Number(row.c?.[0]) > 0 && Number(row.b?.[0]) > 0 && Number(row.a?.[0]) > 0;
  }
  return false;
}


function tickerValuesFromPayload(venue, json) {
  const v = normalizeVenue(venue) || 'binance';
  if (v === 'binance') {
    const bid = Number(json?.bidPrice || 0), ask = Number(json?.askPrice || 0); return { bid, ask, price: Number(json?.lastPrice || 0) || ((bid + ask) / 2), volume24h: Number(json?.quoteVolume || json?.volume || 0) };
  }
  if (v === 'bybit') {
    const row = json?.result?.list?.[0] || {};
    return { bid: Number(row.bid1Price || 0), ask: Number(row.ask1Price || 0), price: Number(row.lastPrice || 0), volume24h: Number(row.turnover24h || row.volume24h || 0) };
  }
  if (v === 'okx') {
    const row = json?.data?.[0] || {};
    return { bid: Number(row.bidPx || 0), ask: Number(row.askPx || 0), price: Number(row.last || 0), volume24h: Number(row.volCcy24h || row.vol24h || 0) };
  }
  if (v === 'kraken') {
    const row = Object.values(json?.result || {})[0] || {};
    return { bid: Number(row.b?.[0] || 0), ask: Number(row.a?.[0] || 0), price: Number(row.c?.[0] || 0), volume24h: Number(row.v?.[1] || row.v?.[0] || 0) };
  }
  return { bid: 0, ask: 0, price: 0, volume24h: 0 };
}

async function fetchPublicTickerFromVenue(providerVenue, normalizedSymbol, timeoutMs = MARKET_DATA_REFERENCE_TIMEOUT_MS) {
  const provider = normalizeVenue(providerVenue);
  const normalized = normalizeSymbol(normalizedSymbol);
  if (!provider) throw new Error('unknown_provider_venue');
  const inflightKey = `${provider}:${normalized}`;
  if (marketRestInflight.has(inflightKey)) return marketRestInflight.get(inflightKey);
  if (!marketRestRequestAllowed(provider, normalized)) {
    const backoff = marketRestBackoffState(provider, normalized).state;
    throw new Error(`provider_backoff_${provider}_${Math.max(0, Number(backoff.nextAttemptAt || 0) - Date.now())}ms`);
  }
  const task = (async () => {
    const rawSymbol = symbolForVenue(normalized, provider);
    const urls = marketDataEndpointCandidates(provider, rawSymbol);
    try {
      const fetched = await fetchFirstHealthyMarketJson(provider, urls, timeoutMs);
      const ticker = tickerValuesFromPayload(provider, fetched.json);
      if (!(ticker.bid > 0) || !(ticker.ask > 0) || !(ticker.price > 0)) throw new Error('invalid_normalized_ticker');
      noteMarketRestSuccess(provider, normalized);
      return {
        providerVenue: provider,
        providerSymbol: rawSymbol,
        ...ticker,
        url: fetched.url,
        latencyMs: fetched.latencyMs,
        attemptCount: fetched.attemptCount
      };
    } catch (error) {
      noteMarketRestFailure(provider, normalized, error?.message || String(error));
      throw error;
    } finally {
      marketRestInflight.delete(inflightKey);
    }
  })();
  marketRestInflight.set(inflightKey, task);
  return task;
}

function crossVenueProviders(requestedVenue = 'binance') {
  const requested = normalizeVenue(requestedVenue) || 'binance';
  const preferredOrder = requested === 'binance'
    ? ['okx', 'bybit', 'kraken']
    : ['binance', 'okx', 'bybit', 'kraken'];
  return preferredOrder.filter(venue => venue !== requested && VENUES.includes(venue));
}

async function fetchCrossVenueReference(requestedVenue, normalizedSymbol, preferredProvider = '') {
  if (!MARKET_DATA_CROSS_VENUE_ENABLED) throw new Error('cross_venue_fallback_disabled');
  const preferred = normalizeVenue(preferredProvider);
  const providers = uniqueNonEmpty([preferred, ...crossVenueProviders(requestedVenue)]).map(normalizeVenue).filter(Boolean);
  if (!providers.length) throw new Error('no_cross_venue_provider');
  const attempts = providers.map(provider => fetchPublicTickerFromVenue(provider, normalizedSymbol, MARKET_DATA_REFERENCE_TIMEOUT_MS)
    .catch(error => { throw new Error(`${provider}: ${error?.message || String(error)}`); }));
  try {
    return await Promise.any(attempts);
  } catch (error) {
    const reasons = asArray(error?.errors).map(item => item?.message || String(item)).filter(Boolean);
    throw new Error(`cross_venue_market_failed: ${reasons.join(' | ') || error?.message || String(error)}`);
  }
}


async function fetchFastPublicTickerRace(requestedVenue, normalizedSymbol, preferredProvider = '') {
  const requested = normalizeVenue(requestedVenue) || 'binance';
  const symbol = normalizeSymbol(normalizedSymbol);
  const preferred = normalizeVenue(preferredProvider);
  const providers = uniqueNonEmpty([
    requested,
    preferred && preferred !== requested ? preferred : '',
    ...crossVenueProviders(requested)
  ]).map(normalizeVenue).filter(Boolean);

  const failures = [];
  const tasks = providers.map((provider, index) => (async () => {
    // The primary route gets a very small head start, but alternatives start
    // immediately enough to avoid the old sequential 9-15 second timeout chain.
    const delayMs = provider === requested ? 0 : Math.min(180, 60 + index * 35);
    if (delayMs) await new Promise(resolve => setTimeout(resolve, delayMs));
    try {
      const ticker = await fetchPublicTickerFromVenue(provider, symbol, FAST_MARKET_PROVIDER_TIMEOUT_MS);
      return { ...ticker, requestedVenue: requested, wonFastRace: true };
    } catch (error) {
      const message = `${provider}: ${error?.message || String(error)}`;
      failures.push(message);
      throw new Error(message);
    }
  })());

  try {
    return await Promise.any(tasks);
  } catch (error) {
    const reasons = failures.length
      ? failures
      : asArray(error?.errors).map(item => item?.message || String(item)).filter(Boolean);
    throw new Error(`fast_public_market_race_failed: ${reasons.join(' | ') || error?.message || String(error)}`);
  }
}

function snapshotFromFastTicker(requestedVenue, normalizedSymbol, ticker, startedAt, route, wasFallback = false) {
  const requested = normalizeVenue(requestedVenue) || 'binance';
  const provider = normalizeVenue(ticker?.providerVenue) || requested;
  const normalized = normalizeSymbol(normalizedSymbol);
  const primary = provider === requested;
  const previousProvider = route?.preferredProvider;

  if (primary) noteMarketProviderPrimarySuccess(requested, normalized);
  else noteMarketProviderFallbackSuccess(requested, normalized, provider);

  const snapshot = normalizeTickerSnapshot({
    venue: requested,
    requestedVenue: requested,
    marketSourceVenue: provider,
    marketSourceSymbol: ticker.providerSymbol,
    marketRoute: primary ? 'fast-race-primary-rest' : 'fast-race-cross-venue-reference',
    marketReferenceConfidence: primary ? 1 : MARKET_DATA_CROSS_VENUE_SIZE_FACTOR,
    symbol: normalized,
    rawSymbol: symbolForVenue(normalized, requested),
    bid: ticker.bid,
    ask: ticker.ask,
    price: ticker.price,
    volume24h: ticker.volume24h,
    source: 'live_public',
    latencyMs: Date.now() - startedAt,
    marketEndpoint: ticker.url,
    marketAttemptCount: ticker.attemptCount,
    marketTransport: primary ? 'rest' : 'rest-cross-venue',
    marketEventTime: Date.now()
  });

  if (wasFallback || previousProvider !== provider) {
    pushEvent(
      'market',
      primary
        ? `Piaci adat helyreállt: ${requested.toUpperCase()} ${normalized} gyors elsődleges public útvonal aktív.`
        : `Gyors public market router: ${requested.toUpperCase()} helyett ${provider.toUpperCase()} friss bid/ask referencia aktív ${normalized} piachoz.`,
      {
        source: 'v199_152-fast-public-market-race',
        venue: requested.toUpperCase(),
        symbol: normalized,
        marketSourceVenue: provider.toUpperCase(),
        endpoint: ticker.url,
        latencyMs: snapshot.latencyMs,
        severity: primary ? 'info' : 'warn',
        referenceFallback: !primary
      }
    );
  }
  return snapshot;
}

function fetchJsonViaNodeHttps(url, timeoutMs = MARKET_DATA_REQUEST_TIMEOUT_MS) {
  return new Promise((resolve, reject) => {
    let parsed;
    try { parsed = new URL(url); } catch (error) { reject(error); return; }
    const transport = parsed.protocol === 'http:' ? http : https;
    const req = transport.get(parsed, { family: 4, agent: false, timeout: timeoutMs, headers: { 'User-Agent': 'NEXUS-public-market/199.167', 'Accept': 'application/json', 'Connection': 'close' } }, res => {
      const chunks = [];
      res.on('data', chunk => chunks.push(chunk));
      res.on('end', () => {
        const body = Buffer.concat(chunks).toString('utf8');
        if (Number(res.statusCode || 0) < 200 || Number(res.statusCode || 0) >= 300) { reject(new Error(`http_${res.statusCode || 0}`)); return; }
        try { resolve({ json: JSON.parse(body), status: Number(res.statusCode || 200) }); } catch { reject(new Error('invalid_json')); }
      });
    });
    req.on('timeout', () => req.destroy(new Error(`timeout_${timeoutMs}ms`)));
    req.on('error', reject);
  });
}

function boundedMarketEndpointWindow(venue, urls = [], fanout = MARKET_REST_ENDPOINT_FANOUT) {
  const list = asArray(urls).filter(Boolean);
  if (!list.length) return { venue: normalizeVenue(venue) || String(venue || 'market').toLowerCase(), cursor: 0, fanout: 0, selected: [] };
  const v = normalizeVenue(venue) || String(venue || 'market').toLowerCase();
  const cursor = Number(marketRestEndpointCursor[v] || 0) % list.length;
  const width = Math.max(1, Math.min(Number(fanout || 1), list.length));
  const selected = [];
  for (let i = 0; i < width; i += 1) selected.push(list[(cursor + i) % list.length]);
  return { venue: v, cursor, fanout: width, selected };
}

function rotatingMarketRecoveryBatch(missingJobs = [], requestedBatchSize = MARKET_CONTINUITY_PUMP_BATCH_SIZE) {
  const jobs = asArray(missingJobs).filter(Boolean);
  if (!jobs.length) return [];
  const batchSize = Math.max(1, Math.min(Number(requestedBatchSize || 1), jobs.length));
  const start = marketContinuityCursor % jobs.length;
  const batch = [];
  for (let i = 0; i < batchSize; i += 1) batch.push(jobs[(start + i) % jobs.length]);
  marketContinuityCursor = (start + batchSize) % jobs.length;
  return batch;
}

async function fetchFirstHealthyMarketJson(venue, urls = [], timeoutMs = MARKET_DATA_REQUEST_TIMEOUT_MS) {
  if (!urls.length) throw new Error('unknown_venue');
  const window = boundedMarketEndpointWindow(venue, urls, MARKET_REST_ENDPOINT_FANOUT);
  const v = window.venue;
  const cursor = window.cursor;
  const fanout = window.fanout;
  const selected = window.selected;

  const controllers = selected.map(() => new AbortController());
  const timers = [];
  const errors = [];
  let winnerSettled = false;
  const attempts = selected.map((url, index) => (async () => {
    const controller = controllers[index];
    timers[index] = setTimeout(() => controller.abort(), timeoutMs);
    const startedAt = Date.now();
    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: {
          'User-Agent': 'NEXUS-exchange-auth-truth/199.178',
          'Accept': 'application/json',
          'Connection': 'close'
        }
      });
      const json = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(`http_${response.status}`);
      if (!tickerPayloadLooksValid(venue, json)) throw new Error('invalid_ticker_payload');
      return { json, url, latencyMs: Date.now() - startedAt, attemptCount: index + 1 };
    } catch (error) {
      const primaryReason = error?.name === 'AbortError' ? `timeout_${timeoutMs}ms` : (error?.message || String(error));
      // Promise.any aborts losing requests after a winner. Those intentional aborts must NOT
      // spawn a second IPv4 HTTPS request, otherwise long-running recovery leaks loser sockets.
      if (winnerSettled && controller.signal.aborted) throw new Error('cancelled_after_market_winner');
      // IPv4 fallback remains available, but only for the bounded endpoint window.  This avoids
      // opening dozens of sockets every few seconds when a venue or Render route is degraded.
      try {
        const alt = await fetchJsonViaNodeHttps(url, timeoutMs);
        if (!tickerPayloadLooksValid(venue, alt.json)) throw new Error('invalid_ticker_payload');
        return { json: alt.json, url, latencyMs: Date.now() - startedAt, attemptCount: index + 1, transportFallback: 'node-https-ipv4' };
      } catch (fallbackError) {
        const fallbackReason = fallbackError?.message || String(fallbackError);
        const reason = `${primaryReason}; ipv4=${fallbackReason}`;
        errors[index] = `${url}: ${reason}`;
        throw new Error(reason);
      }
    } finally {
      clearTimeout(timers[index]);
    }
  })());

  try {
    const winner = await Promise.any(attempts);
    winnerSettled = true;
    controllers.forEach((controller, index) => {
      if (selected[index] !== winner.url && !controller.signal.aborted) controller.abort();
    });
    const winnerIndex = selected.indexOf(winner.url);
    marketRestEndpointCursor[v] = (cursor + Math.max(0, winnerIndex)) % urls.length;
    return { ...winner, endpointWindowSize: fanout, endpointCursor: marketRestEndpointCursor[v] };
  } catch {
    controllers.forEach(controller => {
      if (!controller.signal.aborted) controller.abort();
    });
    // Rotate to a different small host set on the next request instead of hammering every host at once.
    marketRestEndpointCursor[v] = (cursor + fanout) % urls.length;
    throw new Error(`public_market_endpoints_failed: ${errors.filter(Boolean).join(' | ') || 'no successful endpoint'}`);
  }
}

function historicalCandleRequests(venue = 'binance', symbol = 'BTC/USDT', limit = HISTORICAL_WALKFORWARD_SEED_POINTS) {
  const v = normalizeVenue(venue) || 'binance';
  const normalized = normalizeSymbol(symbol);
  const raw = symbolForVenue(normalized, v);
  const enc = encodeURIComponent(raw);
  const capped = Math.max(60, Math.min(220, Number(limit || HISTORICAL_WALKFORWARD_SEED_POINTS)));
  const venueOverrideKey = `NEXUS_HISTORICAL_MARKET_DATA_${v.toUpperCase()}_URLS`;
  const overrideTemplate = String(process.env[venueOverrideKey] || process.env.NEXUS_HISTORICAL_MARKET_DATA_OVERRIDE_URL || '').trim();
  const overrides = overrideTemplate ? overrideTemplate.split(',').map(item => item.trim()).filter(Boolean).map(item => ({
    url: item
      .replaceAll('{venue}', encodeURIComponent(v))
      .replaceAll('{symbol}', enc)
      .replaceAll('{rawSymbol}', enc)
      .replaceAll('{limit}', String(capped)),
    interval: '1m'
  })) : [];
  let official = [];
  if (v === 'binance') official = [
    { url: `https://data-api.binance.vision/api/v3/klines?symbol=${enc}&interval=1m&limit=${capped}`, interval: '1m' },
    { url: `https://api.binance.com/api/v3/klines?symbol=${enc}&interval=1m&limit=${capped}`, interval: '1m' },
    { url: `https://api1.binance.com/api/v3/klines?symbol=${enc}&interval=1m&limit=${capped}`, interval: '1m' }
  ];
  else if (v === 'bybit') official = [
    { url: `https://api.bybit.eu/v5/market/kline?category=spot&symbol=${enc}&interval=1&limit=${capped}`, interval: '1m' },
    { url: `https://api.bybit.com/v5/market/kline?category=spot&symbol=${enc}&interval=1&limit=${capped}`, interval: '1m' },
    { url: `https://api.bytick.com/v5/market/kline?category=spot&symbol=${enc}&interval=1&limit=${capped}`, interval: '1m' }
  ];
  else if (v === 'okx') official = [
    { url: `https://openapi.okx.com/api/v5/market/candles?instId=${enc}&bar=1m&limit=${Math.min(300, capped)}`, interval: '1m' },
    { url: `https://eea.okx.com/api/v5/market/candles?instId=${enc}&bar=1m&limit=${Math.min(300, capped)}`, interval: '1m' },
    { url: `https://www.okx.com/api/v5/market/candles?instId=${enc}&bar=1m&limit=${Math.min(300, capped)}`, interval: '1m' },
    { url: `https://app.okx.com/api/v5/market/candles?instId=${enc}&bar=1m&limit=${Math.min(300, capped)}`, interval: '1m' }
  ];
  else if (v === 'kraken') official = [
    { url: `https://api.kraken.com/0/public/OHLC?pair=${enc}&interval=1`, interval: '1m' }
  ];
  const seen = new Set();
  return [...overrides, ...official].filter(row => row?.url && !seen.has(row.url) && seen.add(row.url));
}

async function fetchFirstHistoricalCandleJson(venue, requests = [], timeoutMs = HISTORICAL_WALKFORWARD_SEED_TIMEOUT_MS) {
  if (!requests.length) throw new Error('historical-candle-route-unavailable');
  const errors = [];
  const controllers = requests.map(() => new AbortController());
  let winnerSettled = false;
  const tasks = requests.map((request, index) => (async () => {
    const controller = controllers[index];
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetch(request.url, {
        signal: controller.signal,
        headers: { 'User-Agent': 'NEXUS-history-seed/199.160', 'Accept': 'application/json' }
      });
      const json = await response.json().catch(() => ({}));
      if (!response.ok) throw new Error(`historical-http-${response.status}`);
      const rows = historicalCandleRowsFromPayload(venue, 'BTC/USDT', json, request.interval);
      // Validation here is intentionally shape-oriented; symbol-specific parsing is repeated by the caller.
      if (!Array.isArray(rows) || rows.length < 10) throw new Error('historical-invalid-payload');
      return { json, request };
    } catch (error) {
      const primaryMessage = error?.name === 'AbortError' ? `timeout-${timeoutMs}ms` : (error?.message || String(error));
      if (winnerSettled && controller.signal.aborted) throw new Error('cancelled_after_history_winner');
      // v199_170: historical warmup uses the same IPv4-safe fallback as live REST.
      // This prevents Render/Undici DNS-family failures from leaving walk-forward at 0/144 indefinitely.
      try {
        const alt = await fetchJsonViaNodeHttps(request.url, timeoutMs);
        const rows = historicalCandleRowsFromPayload(venue, 'BTC/USDT', alt.json, request.interval);
        if (!Array.isArray(rows) || rows.length < 10) throw new Error('historical-invalid-payload');
        return { json: alt.json, request, transportFallback: 'node-https-ipv4' };
      } catch (fallbackError) {
        const fallbackMessage = fallbackError?.message || String(fallbackError);
        const message = `${primaryMessage}; ipv4=${fallbackMessage}`;
        errors[index] = `${request.url}: ${message}`;
        throw new Error(message);
      }
    } finally {
      clearTimeout(timer);
    }
  })());
  try {
    const winner = await Promise.any(tasks);
    winnerSettled = true;
    controllers.forEach(c => { if (!c.signal.aborted) c.abort(); });
    return winner;
  } catch {
    controllers.forEach(c => { if (!c.signal.aborted) c.abort(); });
    throw new Error(`historical_public_endpoints_failed: ${errors.filter(Boolean).join(' | ') || 'no successful endpoint'}`);
  }
}

function historicalCandleRowsFromPayload(venue = 'binance', symbol = 'BTC/USDT', json = {}, interval = '1m') {
  const v = normalizeVenue(venue) || 'binance';
  const normalized = normalizeSymbol(symbol);
  let rows = [];
  if (v === 'binance' && Array.isArray(json)) {
    rows = json.map(row => ({ ts: Number(row?.[0] || 0), close: Number(row?.[4] || 0), volume: Number(row?.[7] || row?.[5] || 0) }));
  } else if (v === 'bybit') {
    rows = asArray(json?.result?.list).map(row => ({ ts: Number(row?.[0] || 0), close: Number(row?.[4] || 0), volume: Number(row?.[6] || row?.[5] || 0) }));
  } else if (v === 'okx') {
    rows = asArray(json?.data).map(row => ({ ts: Number(row?.[0] || 0), close: Number(row?.[4] || 0), volume: Number(row?.[6] || row?.[5] || 0) }));
  } else if (v === 'kraken') {
    const result = asObject(json?.result, {});
    const key = Object.keys(result).find(k => k !== 'last');
    rows = asArray(key ? result[key] : []).map(row => ({ ts: Number(row?.[0] || 0) * 1000, close: Number(row?.[4] || 0), volume: Number(row?.[6] || 0) }));
  }
  const cutoff = Date.now() - 12 * 60 * 60 * 1000;
  return rows
    .filter(row => row.ts > cutoff && row.ts < Date.now() + 60000 && row.close > 0)
    .sort((a, b) => a.ts - b.ts)
    .slice(-HISTORICAL_WALKFORWARD_SEED_POINTS)
    .map(row => ({
      id: `history-${v}-${compactSymbol(normalized)}-${row.ts}`,
      timeMs: row.ts,
      time: new Date(row.ts).toISOString(),
      marketEventTime: row.ts,
      venueKey: v,
      venue: v.toUpperCase(),
      requestedVenue: v,
      symbol: normalized,
      source: 'live_public',
      marketSourceVenue: v,
      marketRoute: 'historical-public-candle-seed',
      marketTransport: 'rest-historical-candle',
      price: row.close,
      bid: row.close,
      ask: row.close,
      spreadPct: 0,
      volume24h: row.volume,
      historicalSeed: true,
      historicalInterval: interval
    }));
}

async function seedHistoricalWalkForwardMarket(venue = 'binance', symbol = 'BTC/USDT', reason = 'runtime') {
  if (!HISTORICAL_WALKFORWARD_SEED_ENABLED) return { ok: false, skipped: true, reason: 'historical-seed-disabled' };
  const v = normalizeVenue(venue) || 'binance';
  const normalized = normalizeSymbol(symbol);
  const key = marketSeriesHistoryKey({ venueKey: v, venue: v, requestedVenue: v, marketSourceVenue: v, symbol: normalized });
  const prior = asObject(marketHistorySeedStatus[key], {});
  const priorMs = Date.parse(prior.lastSuccessAt || '');
  const existingSeedPoints = asArray(db.marketSeriesHistory).filter(row => marketSeriesHistoryKey(row) === key && row.historicalSeed === true).length;
  if (existingSeedPoints >= Math.min(WALK_FORWARD_LOOKBACK_POINTS, HISTORICAL_WALKFORWARD_SEED_POINTS) && Number.isFinite(priorMs) && Date.now() - priorMs < HISTORICAL_WALKFORWARD_REFRESH_MS) {
    return { ok: true, skipped: true, key, points: existingSeedPoints, reason: 'seed-fresh' };
  }
  if (marketHistorySeedInflight.has(key)) return marketHistorySeedInflight.get(key);
  const task = (async () => {
    const requests = historicalCandleRequests(v, normalized);
    if (!requests.length) throw new Error('historical-candle-route-unavailable');
    try {
      const fetched = await fetchFirstHistoricalCandleJson(v, requests, HISTORICAL_WALKFORWARD_SEED_TIMEOUT_MS);
      const rows = historicalCandleRowsFromPayload(v, normalized, fetched.json, fetched.request.interval);
      if (rows.length < 30) throw new Error(`historical-insufficient-${rows.length}`);
      db.marketSeriesHistory = trimMarketSeriesHistory([...rows.reverse(), ...asArray(db.marketSeriesHistory)]);
      const points = asArray(db.marketSeriesHistory).filter(row => marketSeriesHistoryKey(row) === key && row.historicalSeed === true).length;
      marketHistorySeedStatus[key] = { ok: true, lastSuccessAt: now(), points, reason, interval: fetched.request.interval, endpoint: fetched.request.url };
      return { ok: true, key, points, historicalRows: rows.length, interval: fetched.request.interval, endpoint: fetched.request.url };
    } catch (error) {
      marketHistorySeedStatus[key] = { ok: false, lastErrorAt: now(), error: error?.name === 'AbortError' ? `timeout-${HISTORICAL_WALKFORWARD_SEED_TIMEOUT_MS}ms` : (error?.message || String(error)), reason };
      return { ok: false, key, error: marketHistorySeedStatus[key].error };
    } finally {
      marketHistorySeedInflight.delete(key);
    }
  })();
  marketHistorySeedInflight.set(key, task);
  return task;
}

async function seedHistoricalWalkForwardAll(reason = 'boot') {
  if (!HISTORICAL_WALKFORWARD_SEED_ENABLED) return { ok: false, skipped: true, reason: 'historical-seed-disabled' };
  const jobs = [];
  for (const venue of learningMarketVenues()) {
    for (const symbol of normalizedSymbolWhitelist()) jobs.push({ venue, symbol });
  }
  const results = await mapWithConcurrency(jobs, HISTORICAL_WALKFORWARD_SEED_CONCURRENCY, job => seedHistoricalWalkForwardMarket(job.venue, job.symbol, reason));
  const ok = results.filter(row => row?.ok).length;
  const points = asArray(db.marketSeriesHistory).filter(row => row.historicalSeed === true).length;
  pushEvent('learning', `Walk-forward historikus public előtöltés: ${ok}/${jobs.length} piac, ${points} gyertyapont.`, { source: CURRENT_STRATEGY_VERSION, reason, ok, total: jobs.length, points, severity: ok ? 'info' : 'warn' });
  const replayLearning = ok > 0 ? historicalReplayLearningTick(`${reason}-historical-replay`) : { ok: false, skipped: true, reason: 'no-history-ready' };
  persistSoon('historical-walkforward-seed');
  return { ok: ok > 0, marketsReady: ok, marketsTotal: jobs.length, points, results, replayLearning };
}

function historicalWalkForwardCoverageStatus() {
  const target = Math.min(WALK_FORWARD_LOOKBACK_POINTS, HISTORICAL_WALKFORWARD_SEED_POINTS);
  const counts = new Map();
  for (const row of asArray(db.marketSeriesHistory)) {
    const key = marketSeriesHistoryKey(row);
    if (!key) continue;
    const prior = counts.get(key) || { historicalPoints: 0, livePoints: 0 };
    if (row?.historicalSeed === true) prior.historicalPoints += 1;
    else prior.livePoints += 1;
    counts.set(key, prior);
  }
  const markets = [];
  for (const venue of learningMarketVenues()) {
    for (const symbol of normalizedSymbolWhitelist()) {
      const key = marketSeriesHistoryKey({ venueKey: venue, venue, requestedVenue: venue, marketSourceVenue: venue, symbol });
      const count = counts.get(key) || { historicalPoints: 0, livePoints: 0 };
      markets.push({
        key,
        venue,
        symbol: normalizeSymbol(symbol),
        historicalPoints: count.historicalPoints,
        livePoints: count.livePoints,
        target,
        ready: count.historicalPoints >= target,
        status: asObject(marketHistorySeedStatus[key], {})
      });
    }
  }
  const ready = markets.filter(row => row.ready).length;
  return {
    readyMarkets: ready,
    totalMarkets: markets.length,
    missingMarkets: markets.filter(row => !row.ready).map(row => row.key),
    targetPerMarket: target,
    readyPct: markets.length ? Number((ready / markets.length * 100).toFixed(1)) : 0,
    historicalSeedPoints: markets.reduce((sum, row) => sum + Number(row.historicalPoints || 0), 0),
    livePoints: markets.reduce((sum, row) => sum + Number(row.livePoints || 0), 0),
    markets
  };
}

let historicalWalkForwardRepairBusy = false;
async function historicalWalkForwardRepairTick(reason = 'scheduled-repair') {
  if (!HISTORICAL_WALKFORWARD_SEED_ENABLED || !dbReady) return { ok: false, skipped: true, reason: 'not-ready' };
  if (historicalWalkForwardRepairBusy) return { ok: false, skipped: true, reason: 'repair-busy' };
  const before = historicalWalkForwardCoverageStatus();
  const missing = before.markets.filter(row => !row.ready).slice(0, HISTORICAL_WALKFORWARD_REPAIR_BATCH);
  if (!missing.length) return { ok: true, skipped: true, reason: 'coverage-complete', coverage: before };
  historicalWalkForwardRepairBusy = true;
  try {
    const results = await mapWithConcurrency(
      missing,
      Math.min(HISTORICAL_WALKFORWARD_SEED_CONCURRENCY, HISTORICAL_WALKFORWARD_REPAIR_BATCH),
      row => seedHistoricalWalkForwardMarket(row.venue, row.symbol, reason)
    );
    const after = historicalWalkForwardCoverageStatus();
    const recovered = Math.max(0, after.readyMarkets - before.readyMarkets);
    if (recovered > 0 || after.readyMarkets < after.totalMarkets) {
      pushEvent(
        'learning',
        `Walk-forward history javítás: ${after.readyMarkets}/${after.totalMarkets} piac kész, ${after.missingMarkets.length} hiányos.`,
        { source: 'v199_173-protective-walkforward-history-core', reason, recovered, results, coverage: { readyMarkets: after.readyMarkets, totalMarkets: after.totalMarkets, missingMarkets: after.missingMarkets }, severity: after.readyMarkets ? 'info' : 'warn' }
      );
    }
    if (recovered > 0) persistSoon('historical-walkforward-repair');
    return { ok: after.readyMarkets > 0, repaired: recovered, results, coverage: after };
  } finally {
    historicalWalkForwardRepairBusy = false;
  }
}

function historicalReplayRegime(priorReturnPct = 0) {
  if (priorReturnPct >= 0.18) return 'TRENDING_BULL';
  if (priorReturnPct <= -0.18) return 'RISK_OFF';
  return Math.abs(priorReturnPct) >= 0.10 ? 'VOLATILE' : 'RANGE';
}

function historicalReplayLearningTick(reason = 'historical-seed') {
  if (!HISTORICAL_REPLAY_LEARNING_ENABLED || !ONLINE_POLICY_ENABLED) return { ok: false, skipped: true, reason: 'historical-replay-disabled' };
  const grouped = new Map();
  for (const row of asArray(db.marketSeriesHistory)) {
    if (row?.historicalSeed !== true || !(Number(row.price) > 0)) continue;
    const key = marketSeriesHistoryKey(row);
    if (!grouped.has(key)) grouped.set(key, []);
    grouped.get(key).push(row);
  }
  let processed = 0, wins = 0, losses = 0, skipped = 0;
  let netPctSum = 0;
  const marketSummaries = [];
  for (const [key, rawRows] of grouped.entries()) {
    const rows = rawRows.slice().sort((a,b) => marketSeriesTimestamp(a) - marketSeriesTimestamp(b));
    if (rows.length < 40) { skipped += 1; continue; }
    const sampleCount = Math.min(HISTORICAL_REPLAY_MAX_SAMPLES_PER_MARKET, Math.max(2, Math.floor((rows.length - 20) / 20)));
    let marketProcessed = 0, marketWins = 0, marketNetPct = 0;
    for (let n = 0; n < sampleCount; n += 1) {
      const start = 12 + Math.floor(((rows.length - 22) * (n + 1)) / (sampleCount + 1));
      const exitIndex = Math.min(rows.length - 2, start + 6);
      const priorIndex = Math.max(0, start - 10);
      const entry = rows[start], exit = rows[exitIndex], prior = rows[priorIndex];
      const entryPrice = Number(entry?.price || 0), exitPrice = Number(exit?.price || 0), priorPrice = Number(prior?.price || 0);
      if (!(entryPrice > 0) || !(exitPrice > 0) || !(priorPrice > 0) || exitIndex <= start) continue;
      const priorReturnPct = ((entryPrice - priorPrice) / priorPrice) * 100;
      if (Math.abs(priorReturnPct) < 0.025) continue;
      const side = priorReturnPct >= 0 ? 'BUY' : 'SELL';
      const signedGrossPct = ((exitPrice - entryPrice) / entryPrice) * 100 * (side === 'SELL' ? -1 : 1);
      // Conservative round-trip training cost. It is deliberately higher than zero so replay
      // cannot teach the online learner that fee-less micro moves are profitable.
      const roundTripCostPct = 0.16;
      const netPct = signedGrossPct - roundTripCostPct;
      const venue = normalizeVenue(entry.requestedVenue || entry.venueKey || entry.venue) || key.split(':')[0];
      const symbol = normalizeSymbol(entry.symbol || key.split(':').slice(1).join(':'));
      const replayId = `replay-${venue}-${compactSymbol(symbol)}-${side}-${Number(entry.marketEventTime || entry.timeMs || start)}`;
      const sample = {
        id: replayId, replayId, trainingReplay: true, verifiedMarket: false, synthetic: true,
        venue, requestedVenue: venue, symbol, side, regime: historicalReplayRegime(priorReturnPct),
        entryPrice, exitPrice, qty: 1, netPnl: entryPrice * netPct / 100,
        closedAt: exit.time || new Date(Number(exit.marketEventTime || exit.timeMs || Date.now())).toISOString(),
        strategyVersion: 'v199_159-historical-replay-training',
        technicalAtEntry: { trend: priorReturnPct >= 0 ? 'up' : 'down', momentumPct: Number(priorReturnPct.toFixed(5)), trainingReplay: true }
      };
      const result = updateOnlineLearningFromReplaySample(sample, { reason, weight: HISTORICAL_REPLAY_SAMPLE_WEIGHT });
      if (!result.ok || result.skipped) continue;
      processed += 1; marketProcessed += 1; netPctSum += netPct; marketNetPct += netPct;
      if (netPct > 0) { wins += 1; marketWins += 1; } else losses += 1;
    }
    if (marketProcessed) marketSummaries.push({ key, samples: marketProcessed, wins: marketWins, hitRate: Number((marketWins / marketProcessed * 100).toFixed(1)), avgNetPct: Number((marketNetPct / marketProcessed).toFixed(5)) });
  }
  const summary = {
    id: `historical-replay-${Date.now()}`, type: 'historical-replay-training', trainingOnly: true,
    time: now(), reason, processed, wins, losses, hitRate: processed ? Number((wins / processed * 100).toFixed(1)) : 0,
    avgNetPct: processed ? Number((netPctSum / processed).toFixed(5)) : 0,
    weightPerSample: HISTORICAL_REPLAY_SAMPLE_WEIGHT, markets: marketSummaries.slice(0, 20),
    note: 'Training-only prior; not a verified trade, not included in PnL/winrate.'
  };
  db.backtests = asArray(db.backtests);
  db.backtests.unshift(summary); db.backtests = db.backtests.slice(0, 25);
  if (processed > 0) pushEvent('learning', `Historikus replay tanulás: ${processed} training minta • ${summary.hitRate}% találati arány • ${summary.avgNetPct}% átlag nettó. Nem verified trade/PnL.`, { source: CURRENT_STRATEGY_VERSION, reason, trainingOnly: true, processed, wins, losses, avgNetPct: summary.avgNetPct, sampleWeight: HISTORICAL_REPLAY_SAMPLE_WEIGHT });
  return { ok: processed > 0, ...summary, skippedMarkets: skipped };
}

function queueHistoricalWalkForwardSeedAll(reason = 'boot') {
  if (!HISTORICAL_WALKFORWARD_SEED_ENABLED || marketHistorySeedBootQueued) return false;
  marketHistorySeedBootQueued = true;
  const seedDelayMs = isManagedCloudRuntime() ? CLOUD_HISTORICAL_SEED_DELAY_MS : 6000;
  setTimeout(() => {
    seedHistoricalWalkForwardAll(reason).catch(error => pushIncident('warn', `Historikus walk-forward előtöltés hiba: ${error?.message || String(error)}`, { source: CURRENT_STRATEGY_VERSION, reason }));
  }, seedDelayMs);
  return true;
}

async function exactPublicSourceSnapshot(requestedVenue = 'binance', symbol = 'BTC/USDT', sourceVenue = '') {
  const requested = normalizeVenue(requestedVenue) || 'binance';
  const normalized = normalizeSymbol(symbol);
  const source = normalizeVenue(sourceVenue) || requested;
  const started = Date.now();
  if (source === 'binance') ensureBinancePublicMarketStream('source-pinned-snapshot');
  else ensureVenuePublicMarketStreams('source-pinned-snapshot');
  const streamTicker = freshVenuePublicStreamTicker(source, normalized);
  if (streamTicker) {
    return normalizeTickerSnapshot({
      venue: requested, requestedVenue: requested, marketSourceVenue: source, marketSourceSymbol: streamTicker.rawSymbol,
      marketRoute: source === requested ? 'primary-websocket' : 'cross-venue-source-pinned', marketReferenceConfidence: source === requested ? 1 : MARKET_DATA_CROSS_VENUE_SIZE_FACTOR,
      symbol: normalized, rawSymbol: symbolForVenue(normalized, requested), bid: streamTicker.bid, ask: streamTicker.ask, price: streamTicker.price, volume24h: streamTicker.volume24h,
      source: 'live_public', latencyMs: streamTicker.ageMs, marketEndpoint: streamTicker.endpoint, marketAttemptCount: 0,
      marketTransport: source === requested ? 'websocket' : 'rest-cross-venue', marketEventTime: streamTicker.eventTime
    });
  }
  const ticker = await fetchPublicTickerFromVenue(source, normalized, MARKET_DATA_REFERENCE_TIMEOUT_MS);
  return normalizeTickerSnapshot({
    venue: requested, requestedVenue: requested, marketSourceVenue: source, marketSourceSymbol: ticker.providerSymbol,
    marketRoute: source === requested ? 'primary-rest' : 'cross-venue-source-pinned', marketReferenceConfidence: source === requested ? 1 : MARKET_DATA_CROSS_VENUE_SIZE_FACTOR,
    symbol: normalized, rawSymbol: symbolForVenue(normalized, requested), bid: ticker.bid, ask: ticker.ask, price: ticker.price, volume24h: ticker.volume24h,
    source: 'live_public', latencyMs: Date.now() - started, marketEndpoint: ticker.url, marketAttemptCount: ticker.attemptCount,
    marketTransport: source === requested ? 'rest' : 'rest-cross-venue', marketEventTime: Date.now()
  });
}

const marketDataService = {
  async getStrictPrimarySnapshot(venue = 'binance', symbol = 'BTC/USDT') {
    const v = normalizeVenue(venue) || 'binance';
    const normalized = normalizeSymbol(symbol);
    try {
      const snapshot = await exactPublicSourceSnapshot(v, normalized, v);
      if (snapshot && marketSnapshotIsFreshTrusted(snapshot)) return snapshot;
      throw new Error('primary_snapshot_not_fresh');
    } catch (error) {
      const cached = latestFreshLivePublicSnapshotFromSource(v, normalized, v, MARKET_SOURCE_CACHE_MAX_AGE_MS);
      if (cached?.snap && marketSnapshotIsFreshTrusted(cached.snap)) return cached.snap;
      throw error;
    }
  },
  async getPrimarySnapshot(venue = 'binance', symbol = 'BTC/USDT') {
    const v = normalizeVenue(venue) || 'binance';
    const normalized = normalizeSymbol(symbol);
    try {
      return await this.getStrictPrimarySnapshot(v, normalized);
    } catch (error) {
      const fallback = await this.getSnapshot(v, normalized);
      fallback.primarySourceError = error?.message || String(error);
      return fallback;
    }
  },
  async getSnapshot(venue = 'binance', symbol = 'BTC/USDT') {
    const v = normalizeVenue(venue) || 'binance';
    const normalized = normalizeSymbol(symbol);
    if (!['BTC/USDT', 'ETH/USDT', 'SOL/USDT'].includes(normalized)) {
      return simulatedMarketSnapshot(v, normalized, 'unsupported-symbol');
    }

    const started = Date.now();
    try {
      if (typeof fetch !== 'function') throw new Error('fetch_unavailable');
      const route = marketProviderRouteState(v, normalized).state;
      const wasFallback = !!db.marketDataHealth?.degraded || !!db.marketDataHealth?.referenceFallbackActive;

      // v199_167: prefer each venue's own public WebSocket before REST.
      if (v === 'binance') ensureBinancePublicMarketStream('market-snapshot-v199_167');
      else ensureVenuePublicMarketStreams('market-snapshot-v199_167');
      const ownStreamTicker = freshVenuePublicStreamTicker(v, normalized);
      if (ownStreamTicker) {
        const previousProvider = route.preferredProvider;
        noteMarketProviderPrimarySuccess(v, normalized);
        const snapshot = normalizeTickerSnapshot({
          venue: v, requestedVenue: v, marketSourceVenue: v, marketSourceSymbol: ownStreamTicker.rawSymbol,
          marketRoute: 'primary-websocket', marketReferenceConfidence: 1, symbol: normalized, rawSymbol: symbolForVenue(normalized, v),
          bid: ownStreamTicker.bid, ask: ownStreamTicker.ask, price: ownStreamTicker.price, volume24h: ownStreamTicker.volume24h,
          source: 'live_public', latencyMs: ownStreamTicker.ageMs, marketEndpoint: ownStreamTicker.endpoint, marketAttemptCount: 0,
          marketTransport: 'websocket', marketEventTime: ownStreamTicker.eventTime
        });
        if (wasFallback || previousProvider !== v) pushEvent('market', `Piaci adat kapcsolat helyreállt: ${v.toUpperCase()} ${normalized} saját WebSocket ticker friss.`, { source: 'v199_167-own-venue-public-websocket', venue: v.toUpperCase(), symbol: normalized, endpoint: ownStreamTicker.endpoint, latencyMs: ownStreamTicker.ageMs, severity: 'info' });
        return snapshot;
      }

      // v199_179: trade-facing history and decisions are own-venue only. Cross-venue races
      // created unnecessary sockets and could contaminate requested-venue history with reference prices.
      const ticker = await fetchPublicTickerFromVenue(v, normalized, MARKET_DATA_REFERENCE_TIMEOUT_MS);
      return snapshotFromFastTicker(v, normalized, ticker, started, route, wasFallback);
    } catch (error) {
      const err = error?.message || String(error);
      const staleLive = latestFreshLivePublicSnapshot(v, normalized);
      if (staleLive?.snap) {
        const stale = normalizeTickerSnapshot({
          venue: v,
          requestedVenue: v,
          marketSourceVenue: staleLive.snap.marketSourceVenue || staleLive.snap.venueKey || v,
          marketSourceSymbol: staleLive.snap.marketSourceSymbol || staleLive.snap.rawSymbol || symbolForVenue(normalized, v),
          marketRoute: 'stale-last-live-recovery',
          marketReferenceConfidence: 0,
          symbol: normalized,
          rawSymbol: staleLive.snap.rawSymbol || symbolForVenue(normalized, v),
          bid: staleLive.snap.bid,
          ask: staleLive.snap.ask,
          price: staleLive.snap.price || staleLive.snap.mid,
          volume24h: staleLive.snap.volume24h,
          source: 'stale_live_public_fallback',
          latencyMs: Date.now() - started,
          error: err,
          staleFromSnapshotId: staleLive.snap.id,
          staleAgeMs: staleLive.ageMs,
          fallbackReason: 'fast-public-race-failed-stale-live-display-only',
          marketEndpoint: staleLive.snap.marketEndpoint || '',
          marketAttemptCount: 0,
          marketTransport: 'stale-cache',
          marketEventTime: Number(staleLive.snap.marketEventTime || Date.parse(staleLive.snap.time || '') || 0)
        });
        pushEvent('market', `Public market race hibás: ${v.toUpperCase()} ${normalized}; utolsó élő adat csak kijelzésre (${Math.round(staleLive.ageMs / 1000)} mp régi).`, {
          source: 'v199_152-fast-public-market-race',
          venue: v.toUpperCase(),
          symbol: normalized,
          severity: 'warn',
          staleLiveFallback: true,
          snapshotId: stale.id,
          staleAgeMs: staleLive.ageMs,
          error: err
        });
        return stale;
      }

      const fallback = simulatedMarketSnapshot(v, normalized, err || 'fast-public-market-race-failed');
      fallback.error = String(err || '').slice(0, 1200);
      Object.assign(fallback, marketDataQualityForSnapshot(fallback));
      updateMarketDataHealth(fallback);
      pushEvent('market', `Nincs friss public ár ${v.toUpperCase()} ${normalized} piachoz; szimulált adat csak kijelzésre, trade tiltva.`, {
        source: 'v199_152-fast-public-market-race',
        venue: v.toUpperCase(),
        symbol: normalized,
        severity: 'warn',
        simulatedFallback: true,
        snapshotId: fallback.id,
        error: fallback.error
      });
      return fallback;
    }
  },
  latest(venue = 'binance', symbol = 'BTC/USDT') {
    return db.marketState[marketKey(venue, symbol)] || null;
  }
};


// v199_170: capture fresh own-venue WebSocket cache events directly into the live technical series.
// This is memory-only/compact history sampling: it does not create extra Supabase market_snapshot writes.
// It lets all 12 venue+symbol routes accumulate the 10 live samples/20s technical warmup in parallel,
// instead of waiting for the rotating REST/continuity batch to revisit each market.
function captureFreshOwnVenueStreamHistory(reason = 'continuity-cache-sample') {
  const incoming = [];
  let available = 0;
  for (const venue of learningMarketVenues()) {
    for (const symbol of normalizedSymbolWhitelist()) {
      const ticker = freshVenuePublicStreamTicker(venue, symbol);
      if (!ticker) continue;
      available += 1;
      const timeMs = Number(ticker.eventTime || ticker.receivedAt || Date.now());
      incoming.push({
        id: `stream-history-${venue}-${compactSymbol(symbol)}-${timeMs}`,
        timeMs, time: new Date(timeMs).toISOString(), marketEventTime: timeMs,
        venueKey: venue, venue: venue.toUpperCase(), requestedVenue: venue,
        symbol: normalizeSymbol(symbol), source: 'live_public', marketSourceVenue: venue,
        marketRoute: 'own-venue-websocket-history-cache', marketTransport: 'websocket',
        price: Number(ticker.price || ((Number(ticker.bid || 0) + Number(ticker.ask || 0)) / 2)),
        quoteObserved: Number(ticker.bid)>0 && Number(ticker.ask)>=Number(ticker.bid),
        bid: Number(ticker.bid || ticker.price || 0), ask: Number(ticker.ask || ticker.price || 0),
        spreadPct: Number(ticker.price > 0 ? Math.max(0, Number(ticker.ask || 0) - Number(ticker.bid || 0)) / Number(ticker.price) * 100 : 0),
        volume24h: Number(ticker.volume24h || 0), historicalSeed: false
      });
    }
  }
  if (incoming.length) db.marketSeriesHistory = trimMarketSeriesHistory([...incoming, ...asArray(db.marketSeriesHistory)]);
  const perMarket = {};
  for (const row of asArray(db.marketSeriesHistory)) {
    if (row?.historicalSeed === true) continue;
    const key = marketSeriesHistoryKey(row);
    perMarket[key] = Number(perMarket[key] || 0) + 1;
  }
  return { reason, captured: incoming.length, available, perMarket, at: now() };
}

// v199_157: independent continuity pump refreshes own-venue public markets even when the trading runtime is busy or HOLD-blocked.
async function marketContinuityPumpTick(reason = 'interval') {
  if (!MARKET_CONTINUITY_PUMP_ENABLED) {
    marketContinuityStatus = { ...marketContinuityStatus, enabled: false, status: 'disabled', lastRunAt: now() };
    return marketContinuityStatus;
  }
  if (marketContinuityBusy || marketRecoveryNetworkBusy || !dbReady) return marketContinuityStatus;

  // Always harvest every fresh own-venue WebSocket cache first.  This is cheap and lets all
  // 12 markets keep their technical/walk-forward series alive even when no REST request is needed.
  ensureBinancePublicMarketStream(`continuity-${reason}`);
  ensureVenuePublicMarketStreams(`continuity-${reason}`);
  const streamHistoryCapture = captureFreshOwnVenueStreamHistory(reason);
  const beforeCoverage = freshTrustedMarketCoverage();
  const missingSet = new Set(beforeCoverage.missingKeys || []);

  // v199_177: missing-first recovery. Previously the continuity cursor spent REST work on already
  // healthy markets while a dead symbol could remain 0/12 or 1/12 for a long time.  Refresh only
  // missing own-venue markets first; if coverage is complete, do no REST work at all.
  const allJobs = [];
  for (const venue of learningMarketVenues()) for (const symbol of normalizedSymbolWhitelist()) {
    const key = `${normalizeVenue(venue)}:${normalizeSymbol(symbol)}`;
    allJobs.push({ venue: normalizeVenue(venue), symbol: normalizeSymbol(symbol), key });
  }
  const missingJobs = allJobs.filter(job => missingSet.has(job.key));
  const batch = rotatingMarketRecoveryBatch(missingJobs, MARKET_CONTINUITY_PUMP_BATCH_SIZE);
  const batchSize = batch.length;

  if (!batch.length) {
    marketContinuityStatus = {
      enabled: true,
      status: beforeCoverage.freshCount >= beforeCoverage.expectedCount ? 'healthy' : (beforeCoverage.freshCount > 0 ? 'partial' : 'waiting'),
      reason,
      freshMarketCount: beforeCoverage.freshCount,
      expectedMarketCount: beforeCoverage.expectedCount,
      freshVenues: beforeCoverage.freshVenues,
      staleOrMissingMarkets: beforeCoverage.missingKeys,
      refreshed: [], failed: [], lastRunAt: now(),
      lastOkAt: beforeCoverage.freshCount ? now() : (marketContinuityStatus.lastOkAt || null),
      lastError: null,
      latencyMs: 0,
      intervalMs: MARKET_CONTINUITY_PUMP_INTERVAL_MS,
      batchSize: 0,
      concurrency: MARKET_CONTINUITY_PUMP_CONCURRENCY,
      streamHistoryCapture,
      recoveryCursor: marketContinuityCursor,
      endpointFanout: MARKET_REST_ENDPOINT_FANOUT,
      hardResetCount: marketHardResetCount,
      lastHardResetAt: marketLastHardResetAt,
      emptySinceAt: marketEmptySinceAt,
      policy: 'v199_178-round-robin-bounded-network-hard-reset'
    };
    if (beforeCoverage.latest) updateMarketDataHealth(beforeCoverage.latest);
    return marketContinuityStatus;
  }

  // A market that is still missing after the WebSocket harvest should not remain trapped behind a
  // long REST exponential backoff forever. Allow one rescue attempt once the prior failure is old.
  for (const job of batch) {
    const { key, state } = marketRestBackoffState(job.venue, job.symbol);
    const failureMs = Date.parse(state.lastFailureAt || '');
    if (Number.isFinite(failureMs) && Date.now() - failureMs > 45000 && Number(state.nextAttemptAt || 0) > Date.now()) {
      marketRestBackoff[key] = { ...state, nextAttemptAt: 0, rescueResetAt: now() };
    }
  }

  marketContinuityBusy = true;
  marketRecoveryNetworkBusy = true;
  const startedAt = Date.now();
  try {
    const results = await mapWithConcurrency(batch, MARKET_CONTINUITY_PUMP_CONCURRENCY, async job => {
      try {
        const snapshot = await marketDataService.getStrictPrimarySnapshot(job.venue, job.symbol);
        return { ok: marketSnapshotIsFreshTrusted(snapshot), venue: job.venue, symbol: job.symbol, snapshotId: snapshot?.id || null, transport: snapshot?.marketTransport || snapshot?.marketRoute || null };
      } catch (error) {
        return { ok: false, venue: job.venue, symbol: job.symbol, error: String(error?.message || error || 'market-continuity-failed').slice(0, 300) };
      }
    });
    const coverage = freshTrustedMarketCoverage();
    const okRows = results.filter(row => row.ok);
    const badRows = results.filter(row => !row.ok);
    marketContinuityStatus = {
      enabled: true,
      status: coverage.freshCount > 0 ? (coverage.freshCount >= coverage.expectedCount ? 'healthy' : 'partial') : 'waiting',
      reason,
      freshMarketCount: coverage.freshCount,
      expectedMarketCount: coverage.expectedCount,
      freshVenues: coverage.freshVenues,
      staleOrMissingMarkets: coverage.missingKeys,
      refreshed: okRows.map(row => `${normalizeVenue(row.venue)}:${normalizeSymbol(row.symbol)}`),
      failed: badRows.map(row => `${normalizeVenue(row.venue)}:${normalizeSymbol(row.symbol)}`),
      lastRunAt: now(),
      lastOkAt: okRows.length ? now() : (marketContinuityStatus.lastOkAt || null),
      lastError: badRows.length ? badRows.map(row => `${row.venue}:${row.symbol}:${row.error}`).join(' | ').slice(0, 1000) : null,
      latencyMs: Date.now() - startedAt,
      intervalMs: MARKET_CONTINUITY_PUMP_INTERVAL_MS,
      batchSize,
      concurrency: MARKET_CONTINUITY_PUMP_CONCURRENCY,
      streamHistoryCapture,
      recoveryCursor: marketContinuityCursor,
      endpointFanout: MARKET_REST_ENDPOINT_FANOUT,
      hardResetCount: marketHardResetCount,
      lastHardResetAt: marketLastHardResetAt,
      emptySinceAt: marketEmptySinceAt,
      policy: 'v199_178-round-robin-bounded-network-hard-reset'
    };
    if (coverage.latest) updateMarketDataHealth(coverage.latest);
    else updateMarketDataHealth({ source: 'simulated_fallback', fallbackReason: marketContinuityStatus.lastError || 'no-fresh-own-venue-market', time: now() });
    return marketContinuityStatus;
  } finally {
    marketContinuityBusy = false;
    marketRecoveryNetworkBusy = false;
  }
}

function sanitizePublicExchangeState(state = db) {
  for (const venue of Object.keys(state.exchanges || {})) {
    const item = state.exchanges[venue] || {};
    if (item.apiKey) item.apiKeyMasked = mask(item.apiKey);
    if (item.apiSecret || item.secret || item.secretKey) item.apiSecretMasked = mask(item.apiSecret || item.secret || item.secretKey);
    if (item.passphrase) item.passphraseMasked = mask(item.passphrase);
    delete item.apiKey;
    delete item.apiSecret;
    delete item.secret;
    delete item.secretKey;
    delete item.passphrase;
  }
}

function supabaseHeaders() {
  const key = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.SUPABASE_ANON_KEY || '';
  if (!process.env.SUPABASE_URL || !key || typeof fetch !== 'function') return null;
  return { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Prefer: 'return=minimal' };
}

function criticalPersistenceTable(table) {
  return ['trade_journal', 'venue_configs'].includes(String(table || ''));
}

function minutesSince(iso) {
  if (!iso) return Infinity;
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return Infinity;
  return (Date.now() - t) / 60000;
}

function msSinceIso(iso) {
  if (!iso) return Infinity;
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return Infinity;
  return Date.now() - t;
}

function recentWithin(iso, ms) {
  return Number.isFinite(msSinceIso(iso)) && msSinceIso(iso) <= ms;
}

function runtimeHeartbeatStatus() {
  const since = msSinceIso(db.lastRuntimeAt);
  const activePhase = ['REALTIME_RUNTIME_ACTIVE','MARKET_SCAN','SIGNAL_GENERATION','RISK_GATE','EXECUTION_INTENT','EXECUTION_RECONCILE','LEARNING_FEEDBACK'].includes(String(db.phase || ''));
  const stalled = !!db.autopilot && Number.isFinite(since) && since > AUTONOMY_RUNTIME_STALL_MS;
  const neverStarted = !!db.autopilot && !db.lastRuntimeAt;
  return {
    ok: !!db.autopilot && !stalled && !neverStarted,
    activePhase,
    stalled,
    neverStarted,
    lastRuntimeAt: db.lastRuntimeAt || null,
    msSinceLastRuntime: Number.isFinite(since) ? Math.round(since) : null,
    thresholdMs: AUTONOMY_RUNTIME_STALL_MS,
    phase: db.phase
  };
}

function criticalAutonomyBlockers(blockers = []) {
  return asArray(blockers).filter(b => {
    const text = String(b || '');
    if (/kill_switch_or_emergency|max_drawdown_exceeded|autonomous_live_not_allowed/i.test(text)) return true;
    if (/watchdog_memory_cooldown/i.test(text)) return true;
    if (/recovery_lock_active/i.test(text) && !recoveryIsStartReady()) return true;
    if (/persistence_unhealthy:critical|persistence_unhealthy:legacy_critical/i.test(text)) return true;
    // Kapcsolati/proof hiba fontos, de a hosszú futás miatt csak több egymást követő ciklus után állítjuk meg.
    return false;
  });
}

function persistenceSupervisorHealth() {
  if (!supabaseConfigured()) return { ok: true, reason: 'supabase_optional_not_configured' };
  const p = db.persistence || {};
  if (p.safeMode && String(process.env.NEXUS_STRICT_SUPABASE || 'false').toLowerCase() !== 'true') {
    return { ok: true, reason: 'safe_persistence_mode_non_blocking', safeModeReason: p.safeModeReason || db.supabaseHealth?.safeModeReason || 'supabase_degraded' };
  }
  const lastError = String(p.lastError || '');
  const criticalFailures = Number(p.criticalFailedWrites || 0);
  const legacyFailed = Number(p.failedWrites || 0);
  const recentCriticalOk = p.lastCriticalWriteOk === true && minutesSince(p.lastCriticalWriteAt) < 15;
  const recentProofOk = p.lastProofOk === true && minutesSince(p.lastProofAt) < 60;
  const criticalError = /(trade_journal|venue_configs|supabase_not_configured|supabase_readback_failed)/i.test(lastError);

  // A v199_30 alap maradjon: teljes realtime dashboard, de a supervisor ne állítsa le
  // a runtime-ot opcionális/örökölt Supabase log/event hibák vagy cache limitek miatt.
  if (recentProofOk || recentCriticalOk) return { ok: true, reason: recentProofOk ? 'recent_proof_ok' : 'recent_critical_write_ok' };
  if (criticalFailures >= 3 && criticalError) return { ok: false, reason: 'critical_persistence_unhealthy', criticalFailures, lastError };
  if (legacyFailed > 10 && criticalError && !p.lastSuccessfulWriteAt) return { ok: false, reason: 'legacy_critical_persistence_unhealthy', failedWrites: legacyFailed, lastError };
  return { ok: true, reason: 'optional_or_stale_persistence_failures_ignored', failedWrites: legacyFailed, criticalFailures, lastError };
}

function safeOutboxRow(row) {
  if (!row || typeof row !== 'object') return null;
  try {
    const raw = JSON.stringify(row);
    if (raw.length > 80000) return null;
    return JSON.parse(raw);
  } catch { return null; }
}


function supabaseCircuitInfo() {
  db.persistence = db.persistence || {};
  db.persistence.supabaseCircuit = db.persistence.supabaseCircuit || { openUntil: null, reason: null, failures: 0 };
  const openUntilMs = Date.parse(db.persistence.supabaseCircuit.openUntil || '');
  const open = Number.isFinite(openUntilMs) && openUntilMs > Date.now();
  return { ...db.persistence.supabaseCircuit, open, msRemaining: open ? Math.max(0, openUntilMs - Date.now()) : 0 };
}

function openSupabaseWriteCircuit(reason = 'supabase_write_backoff') {
  db.persistence = db.persistence || {};
  db.persistence.supabaseCircuit = db.persistence.supabaseCircuit || {};
  db.persistence.supabaseCircuit.openUntil = new Date(Date.now() + SUPABASE_WRITE_BACKOFF_MS).toISOString();
  db.persistence.supabaseCircuit.reason = reason;
  db.persistence.supabaseCircuit.failures = Number(db.persistence.supabaseCircuit.failures || 0) + 1;
  db.persistence.status = 'supabase-write-backoff';
  db.persistence.safeMode = true;
  db.persistence.safeModeReason = reason;
  return db.persistence.supabaseCircuit;
}

function closeSupabaseWriteCircuit(reason = 'supabase_write_recovered') {
  if (!db.persistence) return;
  db.persistence.supabaseCircuit = { openUntil: null, reason, failures: 0, closedAt: now() };
  db.persistence.safeMode = false;
  db.persistence.safeModeReason = null;
}

function deferSupabaseWrite(table, row, reason = 'supabase_write_backoff', conflict = 'id', opts = {}) {
  db.persistence = db.persistence || {};
  const safeRow = safeOutboxRow(row);
  const rowId = rowIdOf(row);
  const critical = !!opts.critical || criticalPersistenceTable(table);
  if (safeRow) {
    const item = { id: uid(), time: now(), table, rowId, error: reason, critical, conflict: conflict || 'id', retryCount: 0, row: safeRow, deferred: true };
    db.persistence.outbox = [item, ...asArray(db.persistence.outbox).filter(x => !(x && x.table === item.table && x.rowId === item.rowId))].slice(0, 200);
  }
  db.persistence.optionalDeferredWrites = Number(db.persistence.optionalDeferredWrites || 0) + (critical ? 0 : 1);
  db.persistence.lastWriteAt = now();
  db.persistence.status = critical ? 'supabase-critical-queued' : 'supabase-optional-deferred';
  db.persistence.lastDeferredReason = reason;
  db.persistence.lastDeferredAt = now();
  return { ok: false, deferred: true, queued: !!safeRow, error: reason, table, rowId };
}

function supabaseTableHealthState(table = '') {
  db.persistence = db.persistence || {};
  db.persistence.tableHealth = asObject(db.persistence.tableHealth, {});
  const key = String(table || '').toLowerCase();
  db.persistence.tableHealth[key] = asObject(db.persistence.tableHealth[key], { table: key, writeOk: null, readOk: null, deleteOk: null, lastWriteAt: null, lastReadAt: null, lastDeleteAt: null, lastOkAt: null, lastError: null });
  return db.persistence.tableHealth[key];
}

function markSupabaseRead(table, ok, detail = {}) {
  const row = supabaseTableHealthState(table);
  row.readOk = !!ok;
  row.lastReadAt = now();
  if (ok) {
    row.lastOkAt = row.lastReadAt;
    row.lastError = null;
    if (detail.rowCount != null) row.lastKnownRowCount = Number(detail.rowCount || 0);
  } else row.lastError = detail.error || detail.status || 'supabase_read_failed';
  return row;
}

function markSupabaseDelete(table, ok, detail = {}) {
  const row = supabaseTableHealthState(table);
  row.deleteOk = !!ok;
  row.lastDeleteAt = now();
  if (ok) {
    row.lastOkAt = row.lastDeleteAt;
    row.lastError = null;
    if (detail.deletedCount != null) row.lastDeletedCount = Number(detail.deletedCount || 0);
  } else row.lastError = detail.error || detail.status || 'supabase_delete_failed';
  return row;
}

function recentSupabaseTableEvidence(table = '', maxMinutes = 180) {
  const row = asObject(db.persistence?.tableHealth?.[String(table || '').toLowerCase()], {});
  const lastAt = row.lastOkAt || row.lastWriteAt || row.lastReadAt || null;
  return {
    ok: minutesSince(lastAt) <= Number(maxMinutes || 180) && (row.writeOk === true || row.readOk === true || row.deleteOk === true),
    readOk: row.readOk === true,
    writeOk: row.writeOk === true,
    deleteOk: row.deleteOk === true,
    lastAt,
    lastKnownRowCount: Number.isFinite(Number(row.lastKnownRowCount)) ? Number(row.lastKnownRowCount) : null,
    lastError: row.lastError || null
  };
}

function markSupabaseWrite(table, ok, detail = {}) {
  if (!db || !db.persistence) return;
  const tableState = supabaseTableHealthState(table);
  tableState.writeOk = !!ok;
  tableState.lastWriteAt = now();
  const critical = !!detail.critical || criticalPersistenceTable(table);
  db.persistence.supabaseConfigured = !!supabaseHeaders();
  db.persistence.lastWriteAt = now();
  db.persistence.lastWriteOk = !!ok;
  db.persistence.status = ok ? 'supabase-write-ok' : 'supabase-write-failed';
  if (ok) {
    db.persistence.lastSuccessfulWriteAt = now();
    db.persistence.lastError = null;
    tableState.lastOkAt = tableState.lastWriteAt;
    tableState.lastError = null;
    closeSupabaseWriteCircuit('write_ok');
    if (critical) {
      db.persistence.criticalWrites = Number(db.persistence.criticalWrites || 0) + 1;
      db.persistence.lastCriticalWriteAt = now();
      db.persistence.lastCriticalWriteOk = true;
      db.persistence.criticalFailedWrites = 0;
      // A régebbi, opcionális hibákból felgyűlt számláló nem tarthatja készenlétben a botot,
      // ha a kritikus journal/snapshot/config írás újra sikeres.
      db.persistence.failedWrites = 0;
    }
    return;
  }
  db.persistence.failedWrites = Number(db.persistence.failedWrites || 0) + 1;
  if (critical) {
    db.persistence.criticalFailedWrites = Number(db.persistence.criticalFailedWrites || 0) + 1;
    db.persistence.lastCriticalWriteOk = false;
  } else {
    db.persistence.optionalFailedWrites = Number(db.persistence.optionalFailedWrites || 0) + 1;
  }
  db.persistence.lastError = detail.error || 'unknown_supabase_error';
  tableState.lastError = db.persistence.lastError;
  if (!critical && Number(db.persistence.optionalFailedWrites || 0) >= SUPABASE_OPTIONAL_FAILURES_BEFORE_BACKOFF) {
    openSupabaseWriteCircuit(db.persistence.lastError || 'optional_supabase_write_failures');
  }
  const row = safeOutboxRow(detail.row);
  const item = { id: uid(), time: now(), table, rowId: detail.rowId || detail.id || rowIdOf(detail.row), error: db.persistence.lastError, critical, conflict: detail.conflict || 'id', retryCount: 0, row };
  // Dedup: ugyanazt a sort ne szaporítsa végtelenül, de az újabb payload maradjon elöl.
  db.persistence.outbox = [item, ...asArray(db.persistence.outbox).filter(x => !(x && x.table === item.table && x.rowId === item.rowId))].slice(0, 200);
}

function rowIdOf(row) { return row && (row.id || row.venue || row.order_id || row.trade_id) || ''; }


function eventJournalCompatRow(row = {}) {
  const payload = {
    ...(row.payload && typeof row.payload === 'object' ? row.payload : {}),
    schemaCompat: true
  };
  if (row.type !== undefined && payload.type === undefined) payload.type = row.type;
  if (row.message !== undefined && payload.message === undefined) payload.message = row.message;
  if (row.summary !== undefined && payload.summary === undefined) payload.summary = row.summary;
  if (row.details !== undefined && payload.details === undefined) payload.details = row.details;
  if (row.error !== undefined && payload.error === undefined) payload.error = row.error;
  const eventType = row.event_type || row.type || payload.type || 'nexus_event';
  return {
    id: row.id || 'event_' + uid(),
    event_type: String(eventType),
    source: row.source || payload.source || 'nexus-runtime',
    venue: row.venue || payload.venue || '',
    symbol: row.symbol || payload.symbol || '',
    mode: row.mode || db?.mode || '',
    severity: row.severity || payload.severity || 'info',
    payload,
    created_at: row.created_at || row.time || now()
  };
}


function supabaseSchemaCacheOrColumnError(errorText = '') {
  return /PGRST204|schema cache|Could not find|column|42703|does not exist/i.test(String(errorText || ''));
}

function tradeJournalCompatRow(row = {}) {
  const payload = {
    ...(row.payload && typeof row.payload === 'object' ? row.payload : {}),
    schemaCompat: true,
    originalColumns: {
      order_id: row.order_id || row.orderId || null,
      venue: row.venue || null,
      symbol: row.symbol || null,
      side: row.side || null
    }
  };
  return {
    id: row.id || row.trade_id || row.order_id || ('trade_' + uid()),
    payload,
    created_at: row.created_at || row.closedAt || row.time || now()
  };
}

function runtimeSnapshotCompatRow(row = {}) {
  return {
    id: row.id || ('snap_' + uid()),
    payload: row.payload && typeof row.payload === 'object' ? row.payload : { schemaCompat: true, original: row },
    created_at: row.created_at || row.time || now()
  };
}

function supabaseCompatRowForTable(table, row, errorText = '') {
  const t = String(table || '').toLowerCase();
  if (!supabaseSchemaCacheOrColumnError(errorText)) return null;
  if (t === 'trade_journal') return tradeJournalCompatRow(row);
  if (t === 'runtime_snapshots') return runtimeSnapshotCompatRow(row);
  return null;
}

async function supabaseUpsertEventJournal(row, conflict = 'id', opts = {}) {
  const headers = supabaseHeaders();
  if (!headers) {
    markSupabaseWrite('event_journal', false, { row, error: 'supabase_not_configured', critical: !!opts.critical, conflict });
    return { ok: false, error: 'supabase_not_configured', schemaCompat: true };
  }
  const compatRow = eventJournalCompatRow(row);
  const circuit = supabaseCircuitInfo();
  if (circuit.open && !opts.critical) return deferSupabaseWrite('event_journal', compatRow, circuit.reason || 'supabase_write_backoff', conflict, opts);
  const base = process.env.SUPABASE_URL.replace(/\/$/, '') + '/rest/v1/event_journal';
  const url = `${base}?on_conflict=${encodeURIComponent(conflict || 'id')}`;
  try {
    const t = timeoutSignal(SUPABASE_WRITE_TIMEOUT_MS);
    let response;
    try {
      response = await fetch(url, { method: 'POST', signal: t.signal, headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify(compatRow) });
    } finally { t.cancel(); }
    if (!response.ok) throw new Error(`event_journal_${response.status}_${(await response.text().catch(() => '')).slice(0, 200)}`);
    markSupabaseWrite('event_journal', true, { row: compatRow, critical: !!opts.critical, conflict });
    return { ok: true, schemaCompat: true, row: compatRow };
  } catch (error) {
    const raw = error.message || String(error);
    markSupabaseWrite('event_journal', false, { row: compatRow, error: raw, critical: !!opts.critical, conflict });
    return { ok: false, error: raw, schemaCompat: true, row: compatRow };
  }
}

async function supabaseUpsert(table, row, conflict = 'id', opts = {}) {
  if (String(table || '').toLowerCase() === 'event_journal') return supabaseUpsertEventJournal(row, conflict, opts);
  const headers = supabaseHeaders();
  if (!headers) {
    markSupabaseWrite(table, false, { row, error: 'supabase_not_configured', critical: !!opts.critical, conflict });
    return { ok: false, error: 'supabase_not_configured' };
  }
  const circuit = supabaseCircuitInfo();
  if (circuit.open && !opts.critical) return deferSupabaseWrite(table, row, circuit.reason || 'supabase_write_backoff', conflict, opts);
  const base = process.env.SUPABASE_URL.replace(/\/$/, '') + '/rest/v1/' + table;
  const url = `${base}?on_conflict=${encodeURIComponent(conflict || 'id')}`;
  try {
    const t = timeoutSignal(SUPABASE_WRITE_TIMEOUT_MS);
    let response;
    try {
      response = await fetch(url, { method: 'POST', signal: t.signal, headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify(row) });
    } finally { t.cancel(); }
    if (!response.ok) throw new Error(`${table}_${response.status}_${(await response.text().catch(() => '')).slice(0, 160)}`);
    markSupabaseWrite(table, true, { row, critical: !!opts.critical, conflict });
    return { ok: true };
  } catch (error) {
    const rawError = error.message || String(error);
    const compatRow = supabaseCompatRowForTable(table, row, rawError);
    if (compatRow) {
      try {
        const t2 = timeoutSignal(SUPABASE_WRITE_TIMEOUT_MS);
        let response2;
        try {
          response2 = await fetch(url, { method: 'POST', signal: t2.signal, headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify(compatRow) });
        } finally { t2.cancel(); }
        if (response2.ok) {
          markSupabaseWrite(table, true, { row: compatRow, critical: !!opts.critical, conflict });
          if (String(table || '').toLowerCase() === 'trade_journal') {
            db.persistence.tradeJournalCompatWriteOkAt = now();
            db.persistence.tradeJournalCompatMode = true;
          }
          return { ok: true, schemaCompat: true, originalError: rawError, row: compatRow };
        }
        const compatError = `${table}_compat_${response2.status}_${(await response2.text().catch(() => '')).slice(0, 160)}`;
        markSupabaseWrite(table, false, { row: compatRow, error: compatError, critical: !!opts.critical, conflict });
        return { ok: false, error: compatError, originalError: rawError, schemaCompatTried: true };
      } catch (compatCatch) {
        const compatError = compatCatch.message || String(compatCatch);
        markSupabaseWrite(table, false, { row: compatRow, error: compatError, critical: !!opts.critical, conflict });
        return { ok: false, error: compatError, originalError: rawError, schemaCompatTried: true };
      }
    }
    markSupabaseWrite(table, false, { row, error: rawError, critical: !!opts.critical, conflict });
    return { ok: false, error: rawError };
  }
}

function supabaseInsert(table, row) {
  const compactRow = compactSupabaseRowForTable(table, row);
  if (!shouldPersistSupabaseOptionalRow(table, compactRow)) {
    db.persistence = db.persistence || {};
    db.persistence.suppressedRemoteWrites = Number(db.persistence.suppressedRemoteWrites || 0) + 1;
    db.persistence.lastSuppressedRemoteWrite = { table: String(table || ''), at: now(), reason: supabaseDatabasePressureActive() ? 'quota-footprint-guard' : 'remote-write-sampling' };
    return;
  }
  supabaseUpsert(table, compactRow, 'id').catch(() => {});
}

async function rawSupabaseUpsertNoMark(table, row, conflict = 'id') {
  const headers = supabaseHeaders();
  if (!headers) return { ok: false, error: 'supabase_not_configured' };
  if (!row || typeof row !== 'object') return { ok: false, error: 'missing_outbox_row' };
  const targetTable = String(table || '');
  const payload = targetTable.toLowerCase() === 'event_journal' ? eventJournalCompatRow(row) : row;
  const base = process.env.SUPABASE_URL.replace(/\/$/, '') + '/rest/v1/' + encodeURIComponent(targetTable);
  const url = `${base}?on_conflict=${encodeURIComponent(conflict || 'id')}`;
  try {
    const t = timeoutSignal(SUPABASE_WRITE_TIMEOUT_MS);
    let response;
    try {
      response = await fetch(url, { method: 'POST', signal: t.signal, headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify(payload) });
    } finally { t.cancel(); }
    if (!response.ok) {
      const errorText = `${targetTable}_${response.status}_${(await response.text().catch(() => '')).slice(0, 160)}`;
      const compat = supabaseCompatRowForTable(targetTable, payload, errorText);
      if (compat) {
        const t2 = timeoutSignal(SUPABASE_WRITE_TIMEOUT_MS);
        let response2;
        try {
          response2 = await fetch(url, { method: 'POST', signal: t2.signal, headers: { ...headers, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify(compat) });
        } finally { t2.cancel(); }
        if (response2.ok) return { ok: true, schemaCompat: true };
        return { ok: false, status: response2.status, error: `${targetTable}_compat_${response2.status}_${(await response2.text().catch(() => '')).slice(0, 160)}`, originalError: errorText, schemaCompatTried: true };
      }
      return { ok: false, status: response.status, error: errorText };
    }
    return { ok: true };
  } catch (error) {
    const raw = error.message || String(error);
    const compat = supabaseCompatRowForTable(targetTable, payload, raw);
    if (compat) {
      try {
        const headers2 = supabaseHeaders();
        const base2 = process.env.SUPABASE_URL.replace(/\/$/, '') + '/rest/v1/' + encodeURIComponent(targetTable);
        const url2 = `${base2}?on_conflict=${encodeURIComponent(conflict || 'id')}`;
        const t3 = timeoutSignal(SUPABASE_WRITE_TIMEOUT_MS);
        let response3;
        try {
          response3 = await fetch(url2, { method: 'POST', signal: t3.signal, headers: { ...headers2, Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify(compat) });
        } finally { t3.cancel(); }
        if (response3.ok) return { ok: true, schemaCompat: true };
        return { ok: false, status: response3.status, error: `${targetTable}_compat_${response3.status}_${(await response3.text().catch(() => '')).slice(0, 160)}`, originalError: raw, schemaCompatTried: true };
      } catch (compatCatch) {
        return { ok: false, error: compatCatch.message || String(compatCatch), originalError: raw, schemaCompatTried: true };
      }
    }
    return { ok: false, error: raw };
  }
}

let supabaseOutboxFlushBusy = false;
async function flushSupabaseOutbox(reason = 'outbox-flush') {
  if (supabaseOutboxFlushBusy) return { ok: false, skipped: true, reason: 'outbox_flush_busy', queued: asArray(db.persistence?.outbox).length };
  if (!supabaseConfigured()) return { ok: false, skipped: true, reason: 'supabase_not_configured', queued: asArray(db.persistence?.outbox).length };
  const queued = asArray(db.persistence?.outbox).filter(x => x && x.table && x.row).slice(0, SUPABASE_OUTBOX_FLUSH_LIMIT);
  if (!queued.length) return { ok: true, skipped: true, reason: 'outbox_empty', queued: asArray(db.persistence?.outbox).length };
  supabaseOutboxFlushBusy = true;
  const done = [];
  const failed = [];
  try {
    for (const item of queued) {
      const result = await rawSupabaseUpsertNoMark(item.table, item.row, item.conflict || 'id');
      if (result.ok) done.push(item.id);
      else failed.push({ ...item, retryCount: Number(item.retryCount || 0) + 1, lastRetryAt: now(), error: result.error || result.status || 'outbox_flush_failed' });
    }
    const doneSet = new Set(done);
    const failedById = new Map(failed.map(x => [x.id, x]));
    db.persistence.outbox = asArray(db.persistence.outbox)
      .filter(x => x && !doneSet.has(x.id))
      .map(x => failedById.get(x.id) || x)
      .slice(0, 200);
    if (done.length) {
      closeSupabaseWriteCircuit('outbox_flush_ok');
      db.persistence.lastSuccessfulWriteAt = now();
      db.persistence.lastWriteOk = true;
      db.persistence.status = failed.length ? 'supabase-outbox-partial-flushed' : 'supabase-outbox-flushed';
      db.persistence.lastError = failed.length ? (failed[0].error || 'partial_outbox_failure') : null;
      db.persistence.failedWrites = failed.length ? Number(db.persistence.failedWrites || 0) : 0;
      db.persistence.criticalFailedWrites = failed.some(x => x.critical) ? Number(db.persistence.criticalFailedWrites || 0) : 0;
      pushEvent('persistence', `Supabase outbox újraküldés: ${done.length} sor sikeres, ${failed.length} maradt sorban.`, { source: 'supabase-auto-recovery-outbox', reason, flushed: done.length, failed: failed.length, severity: failed.length ? 'warn' : 'info' });
      persistSoon('supabase-outbox-flush');
    }
    return { ok: failed.length === 0, flushed: done.length, failed: failed.length, queuedAfter: asArray(db.persistence.outbox).length };
  } finally {
    supabaseOutboxFlushBusy = false;
  }
}

async function supabaseAutoRecoveryTick(reason = 'interval') {
  if (!supabaseConfigured()) return { ok: true, skipped: true, reason: 'supabase_not_configured' };
  const outboxCount = asArray(db.persistence?.outbox).length;
  const needsRecovery = !!db.supabaseHealth?.safeMode || db.persistence?.lastWriteOk === false || outboxCount > 0 || db.supabaseHealth?.ok === false;
  if (!needsRecovery) return { ok: true, skipped: true, reason: 'supabase_healthy', outboxCount };
  const health = await runSupabaseHealthCheck(reason + '-health');
  let proof = null;
  if (health.health?.restOk && health.health?.criticalSchemaOk) proof = await databaseReadWriteProof(reason + '-proof');
  const flushed = await flushSupabaseOutbox(reason + '-outbox');
  const recovered = !!(health.ok || proof?.ok || flushed.flushed);
  if (recovered) closeSupabaseWriteCircuit('auto_recovery_ok');
  return { ok: recovered, health: health.summary || health.health, proof: proof ? { ok: !!proof.ok, status: proof.status } : null, flushed, circuit: supabaseCircuitInfo() };
}

async function supabaseSelectById(table, id, options = {}) {
  const headers = supabaseHeaders();
  if (!headers) return [];
  const base = process.env.SUPABASE_URL.replace(/\/$/, '') + '/rest/v1/' + table;
  const url = `${base}?select=*&id=eq.${encodeURIComponent(id)}`;
  try {
    const readHeaders = { ...headers };
    delete readHeaders.Prefer;
    const t = timeoutSignal(CONTINUITY_CHECKPOINT_REMOTE_TIMEOUT_MS);
    let response;
    try { response = await fetch(url, { method: 'GET', signal: t.signal, headers: readHeaders }); }
    finally { t.cancel(); }
    if (!response.ok) throw new Error('supabase_select_by_id_' + table + '_' + response.status);
    const rows = await response.json();
    if(options.strict && !Array.isArray(rows))throw new Error('invalid-durable-read-shape');
    const list = Array.isArray(rows) ? rows : [];
    markSupabaseRead(table, true, { rowCount: list.length });
    return list;
  } catch (error) {
    markSupabaseRead(table, false, { id, error: error.message || String(error) });
    if(options.strict)throw error;
    return [];
  }
}

