function currentProbeAdmission(decision) {
  const snapshot = decision?.marketSnapshot || {};
  const venue = normalizeVenue(snapshot.venueKey || snapshot.venue) || 'binance';
  const protection = recentVerifiedQualityProtection(20, venue);
  const venueSupervisor = venueSupervisorFor(venue, 'probe-admission');
  const protectiveProbation = decision?.tradeActivity?.activeLearningProbeMode === 'protective-probation-probe'
    && protection.severity === 'protective'
    && Number(protection.currentEngineLossStreak || 0) === 2
    && protection.lossStreakPauseActive !== true
    && venueSupervisor.tradeAllowed !== false;
  const supervisedProtectiveRecovery = decision?.tradeActivity?.activeLearningProbeMode === 'supervised-discovery-probe'
    && decision?.tradeActivity?.supervisedDiscovery?.protectiveRecoveryAllowed === true
    && protection.severity === 'protective'
    && protection.lossStreakPauseActive !== true
    && venueSupervisor.tradeAllowed !== false;
  const currentTrades = currentStrategyVerifiedTrades(db).filter(row => onlineLearningMarketVenue(row) === venue).length;
  const venueOpenCount = activeLearningOpenProbeCountForVenue(venue);
  const totalOpenCount = activeLearningOpenProbeCount();
  const discoveryMinEdge = Number(decision?.tradeActivity?.supervisedDiscovery?.minNetEdgePct || SUPERVISED_DISCOVERY_MIN_NET_EDGE_PCT);
  const admission = probeAdmission({
    mode: db.mode, enabled: ACTIVE_LEARNING_PROBE_ENABLED && venueSupervisor.tradeAllowed !== false,
    openCount: venueOpenCount, maxOpen: ACTIVE_LEARNING_MAX_CONCURRENT_PROBES_PER_VENUE,
    cooldownOk: activeLearningProbeCooldownStatus(decision?.symbol || '', venue).ok,
    protection, allowProtectiveProbation: protectiveProbation || supervisedProtectiveRecovery,
    currentTrades,
    recoveryCap: BRIDGED_RECOVERY_MAX_CURRENT_TRADES,
    netEdgePct: Number(decision?.tradeActivity?.probeNetEdgePct ?? NaN),
    minNetEdgePct: decision?.tradeActivity?.activeLearningProbeMode === 'supervised-discovery-probe'
      ? discoveryMinEdge
      : decision?.tradeActivity?.activeLearningProbeMode === 'protective-probation-probe'
        ? PROTECTIVE_PROBATION_MIN_NET_EDGE_PCT
        : ACTIVE_LEARNING_PROBE_MIN_NET_EDGE_PCT
  });
  if (totalOpenCount >= ACTIVE_LEARNING_MAX_CONCURRENT_PROBES && !admission.blockers.includes('probe_global_concurrency_limit')) admission.blockers.push('probe_global_concurrency_limit');
  if (venueSupervisor.tradeAllowed === false && !admission.blockers.includes('venue-supervisor-ai-paused')) admission.blockers.push('venue-supervisor-ai-paused');
  return { ...admission, venue, currentTrades, venueSupervisor };
}

