function supabaseDatabasePressureActive() {
  if (!SUPABASE_FOOTPRINT_GUARD_ENABLED) return false;
  const usage = db?.supabaseHealth?.databaseUsage || db?.databaseMaintenance?.databaseUsage || {};
  return db?.supabaseHealth?.quotaRestricted === true
    || db?.supabaseHealth?.quotaExceeded === true
    || usage?.nearQuota === true
    || usage?.overQuota === true
    || Number(usage?.quotaPercent || 0) >= 80;
}

function shouldPersistSupabaseOptionalRow(table = '', row = {}) {
  if (!SUPABASE_FOOTPRINT_GUARD_ENABLED) return true;
  const t = String(table || '').toLowerCase();
  if (['trade_journal', 'venue_configs', 'profit_withdrawals', 'capital_state'].includes(t)) return true;
  const pressure = supabaseDatabasePressureActive();
  // v199_171: routine market/runtime snapshots are regenerable and were the largest DB growth source.
  // Keep the fixed continuity checkpoint (direct critical upsert) and current proof snapshots, but sample routine rows.
  if (t === 'runtime_snapshots') {
    const id = String(row?.id || '');
    if (id === CONTINUITY_CHECKPOINT_ID || id.startsWith('live-readonly-snap-current-')) return true;
    if (pressure) return false;
    const key = 'runtime_snapshot:scheduled';
    const last = Number(supabaseRemoteWriteSampleState.get(key) || 0);
    if (Date.now() - last < SUPABASE_RUNTIME_SNAPSHOT_WRITE_INTERVAL_MS) return false;
    supabaseRemoteWriteSampleState.set(key, Date.now());
    return true;
  }
  if (t === 'market_snapshots') {
    if (pressure) return false;
    const venue = normalizeVenue(row.venue || row.payload?.venue || row.payload?.venueKey || '') || 'unknown';
    const symbol = normalizeSymbol(row.symbol || row.payload?.symbol || 'UNKNOWN');
    const key = `market_snapshot:${venue}:${symbol}`;
    const last = Number(supabaseRemoteWriteSampleState.get(key) || 0);
    if (Date.now() - last < SUPABASE_MARKET_SNAPSHOT_WRITE_INTERVAL_MS) return false;
    supabaseRemoteWriteSampleState.set(key, Date.now());
    return true;
  }
  if (pressure && ['ai_decisions', 'event_journal', 'strategy_evaluations', 'signal_quality', 'incident_log', 'replay_recovery_log', 'testnet_orders', 'testnet_proofs', 'portfolio_risk_scaling_snapshots'].includes(t)) return false;
  if (t === 'ai_decisions') {
    const side = String(row.side || row.payload?.side || 'HOLD').toUpperCase();
    if (side !== 'HOLD') return true;
    const venue = normalizeVenue(row.payload?.venue || row.venue || '') || 'unknown';
    const symbol = normalizeSymbol(row.symbol || row.payload?.symbol || 'UNKNOWN');
    const key = `ai_hold:${venue}:${symbol}`;
    const last = Number(supabaseRemoteWriteSampleState.get(key) || 0);
    if (Date.now() - last < SUPABASE_HOLD_DECISION_WRITE_INTERVAL_MS) return false;
    supabaseRemoteWriteSampleState.set(key, Date.now());
    return true;
  }
  if (t === 'event_journal') {
    const eventType = String(row.event_type || row.payload?.type || '').toLowerCase();
    const severity = String(row.severity || row.payload?.severity || 'info').toLowerCase();
    if (['warn', 'error', 'critical'].includes(severity) || ['execution', 'risk', 'incident', 'recovery'].includes(eventType)) return true;
    const venue = normalizeVenue(row.venue || row.payload?.venue || '') || 'global';
    const symbol = normalizeSymbol(row.symbol || row.payload?.symbol || 'GLOBAL');
    const key = `event:${eventType || 'info'}:${venue}:${symbol}`;
    const last = Number(supabaseRemoteWriteSampleState.get(key) || 0);
    if (Date.now() - last < SUPABASE_ROUTINE_EVENT_WRITE_INTERVAL_MS) return false;
    supabaseRemoteWriteSampleState.set(key, Date.now());
    return true;
  }
  return true;
}

function compactSupabaseRowForTable(table = '', row = {}) {
  const t = String(table || '').toLowerCase();
  if (t === 'trade_journal') {
    const trade = compactTradeForDatabase(row.payload || row);
    return { ...row, order_id: row.order_id || trade.orderId || null, venue: row.venue || trade.venue || null, symbol: row.symbol || trade.symbol || null, side: row.side || trade.side || null, payload: trade, created_at: row.created_at || trade.closedAt || now() };
  }
  if (t === 'ai_decisions') return { ...row, payload: compactDecisionForDatabase(row.payload || row) };
  if (t === 'capital_ledger') return { ...row, payload: compactCapitalLedgerForDatabase(row.payload || row) };
  return row;
}

