function safeStagingAutoResumeGuard(reason = 'safe-staging-auto-resume') {
  db.autonomousSupervisor = deepMerge(defaultState().autonomousSupervisor, db.autonomousSupervisor || {});
  if (db.autopilot || db.killSwitch || db.emergency) return { ok: true, skipped: true, reason: 'already-running-or-blocked' };
  if (db.autonomousSupervisor.manualStop || db.autonomousSupervisor.desiredAutopilot === false) return { ok: true, skipped: true, reason: 'manual-stop-or-disabled-intent' };
  if (envFlag('NEXUS_LIVE_REAL_SUBMIT', 'ALLOW_LIVE_ORDER_SUBMIT')) return { ok: false, skipped: true, reason: 'live-submit-enabled' };
  if (String(process.env.NEXUS_SAFE_STAGING_AUTO_RESUME || 'true').toLowerCase() === 'false') return { ok: true, skipped: true, reason: 'disabled' };
  const recoveryLocked = !!db.renderRecovery?.recoveryLock && !recoveryIsStartReady();
  if (recoveryLocked) return { ok: true, skipped: true, reason: 'recovery-lock-active' };
  if (!['paper', 'staging'].includes(String(db.mode || 'paper'))) {
    db.mode = 'paper';
    db.workflowStage = 'paper';
  }
  const gate = readiness();
  const safePhase = ['SAFE_READY', 'RECOVERY_SAFE_READY', 'READY_CONTROLLED', 'START_BLOCKED', 'RECOVERY_LOCKED'].includes(String(db.phase || ''));
  if (gate.startAllowed && safePhase) {
    db.autopilot = true;
    db.phase = 'REALTIME_RUNTIME_ACTIVE';
    db.risk = 'controlled';
    db.autonomousSupervisor.enabled = true;
    db.autonomousSupervisor.status = 'running';
    db.autonomousSupervisor.desiredAutopilot = true;
    db.autonomousSupervisor.lastReason = reason;
    db.autonomousSupervisor.lastAutoStartAt = now();
    db.modules.mission.status = 'running';
    db.modules.router.status = 'routing';
    resumePaperSimulationSession(reason);
    db.renderRecovery = deepMerge(db.renderRecovery || {}, { recoveryLock: false, autoStartBlocked: false, autoResumeAt: now(), autoResumeReason: reason, resumeIntent: true });
    pushEvent('recovery', 'Automatikus restart-folytatás: a bot PAPER/STAGING módban kézi kattintás nélkül újraindult. Éles order továbbra is tiltva.', { source: reason, mode: db.mode, blockers: gate.blockers, checkpoint: db.continuityCheckpoint, closedTrades: Number(db.aggregateStats?.closedTrades || 0) });
    writeContinuityCheckpoint(reason + '-activated', { force: true }).catch(() => {});
    persistSoon('safe-staging-auto-resume');
    setTimeout(() => { runtimeCycle().catch(error => pushIncident('warn', 'Automatikus restart-folytatás runtime hiba: ' + (error.message || String(error)), { source: reason })); }, 250);
    return { ok: true, resumed: true, readiness: gate.summary, mode: db.mode };
  }
  return { ok: true, skipped: true, reason: 'conditions-not-met', blockers: gate.blockers, phase: db.phase, mode: db.mode };
}


let learningDurableBusy=false,learningRemoteRevision=null,learningLastChecksum=null;
function activePolicyConfig() {
  return {strategyVersion:CURRENT_STRATEGY_VERSION,riskLimits:db.riskLimits,aiTuning:db.aiTuning,symbolWhitelist:db.symbolWhitelist,
    strategyAutopilotControl:db.strategyAutopilotControl,strategyBuilder:db.strategyBuilder,
    executionPolicy:{paperDefault:true,liveRealSubmit:false,replicas:1,contract:'enforced-3',uncertain:'reconcile-only'}};
}
function syncModelRegistryCacheFromState() {
  // Only a checksum-verified durable bundle can replace the local complete registry.
  db.modelRegistry=registrySnapshot(ROOT);
}
async function hydrateLearningState() {
  const file=path.join(STORAGE_DIR,'learning_bundle_v3.json');
  const local=readJsonFile(file,null);
  let localRestore=null;
  if(local?.bundle) {localRestore=restoreDurableBundle(ROOT,local.bundle);if(localRestore.ok && localRestore.restored)applyLearningConfig(localRestore.config);}
  if(!supabaseConfigured()){db.learningDurability={status:localRestore?.ok===false?'local-invalid':'local-only',remoteVerified:false,reason:localRestore?.ok===false?localRestore.reason:null};return {ok:localRestore?.ok!==false,local:true};}
  let rows;
  try {rows=await supabaseSelectById('nexus_learning_state','nexus-learning-v3',{strict:true});}
  catch(error){learningRemoteRevision=null;db.learningDurability={status:'remote-unavailable',remoteVerified:false,reason:error.message};return {ok:false,...db.learningDurability};}
  if(!rows.length){learningRemoteRevision=0;db.learningDurability={status:'remote-empty-verified',remoteVerified:false};return {ok:false,reason:'remote-state-not-proven'};}
  const remote=rows[0];
  if(!Number.isSafeInteger(Number(remote.revision)) || Number(remote.revision)<1){learningRemoteRevision=null;return {ok:false,reason:'invalid-remote-revision'};}
  const result=restoreDurableBundle(ROOT,remote.payload,local?.bundle || null);
  learningRemoteRevision=Number(remote.revision);
  if(result.ok && result.restored)applyLearningConfig(result.config);
  if(!result.ok){learningRemoteRevision=null;db.learningDurability={status:'conflict-or-invalid',reason:result.reason,remoteVerified:false};return result;}
  db.modelRegistry=registrySnapshot(ROOT);
  db.learningDurability={status:result.restored?'remote-restored':'local-newer',remoteRevision:learningRemoteRevision,remoteVerified:true,checksum:remote.payload.checksum};
  writeJsonFile(file,{bundle:exportDurableBundle(ROOT,activePolicyConfig()),remoteRevision:learningRemoteRevision});
  return result;
}
function applyLearningConfig(config={}) {
  if(config.strategyVersion!==CURRENT_STRATEGY_VERSION)return;
  for(const key of ['riskLimits','aiTuning','symbolWhitelist','strategyAutopilotControl','strategyBuilder'])if(config[key])db[key]=config[key];
  // Stored config cannot grant external/live authority.
  db.executionPolicy={...config.executionPolicy,liveRealSubmit:false,paperDefault:true,replicas:1};
}
async function persistLearningState() {
  if(learningDurableBusy)return {ok:true,skipped:true,reason:'already-writing'};
  learningDurableBusy=true;
  try {
    if(supabaseConfigured() && learningRemoteRevision===null)await hydrateLearningState();
    const bundle=exportDurableBundle(ROOT,activePolicyConfig());
    writeJsonFile(path.join(STORAGE_DIR,'learning_bundle_v3.json'),{bundle,remoteRevision:learningRemoteRevision});
    if(!supabaseConfigured())return {ok:true,local:true,remote:false};
    if(learningRemoteRevision===null)return {ok:false,reason:'unresolved-durable-state-conflict'};
    if(bundle.checksum===learningLastChecksum)return {ok:true,skipped:true,reason:'unchanged-content'};
    const response=await supabaseRpc('nexus_save_learning_state',{p_id:'nexus-learning-v3',p_expected_revision:learningRemoteRevision,p_payload:bundle});
    if(!response.ok || !response.data?.ok){db.learningDurability={status:'remote-write-blocked',remoteVerified:false,reason:response.error || response.data?.reason};learningRemoteRevision=null;return {ok:false,...db.learningDurability};}
    learningRemoteRevision=Number(response.data.revision);learningLastChecksum=bundle.checksum;
    writeJsonFile(path.join(STORAGE_DIR,'learning_bundle_v3.json'),{bundle,remoteRevision:learningRemoteRevision});
    db.learningDurability={status:'saved-local-and-remote',remoteRevision:learningRemoteRevision,remoteVerified:true,checksum:bundle.checksum,savedAt:now()};
    return {ok:true,...db.learningDurability};
  }finally{learningDurableBusy=false;}
}

function refreshStrategyLearningIntelligence(reason = 'auto') {
  const trades = verifiedLearningTrades();
  const scorecard = buildStrategyScorecard(trades, { strategyVersion: CURRENT_STRATEGY_VERSION, reason, halfLifeDays: 21 });
  db.strategyScorecard = scorecard;
  try { db.modelRegistry = registrySnapshot(ROOT); } catch {}
  db.strategyQualityAutopilot2 = summarizeStrategyQuality2(scorecard, db.modelRegistry || {});
  return { scorecard, modelRegistry: db.modelRegistry, qualityAutopilot: db.strategyQualityAutopilot2 };
}

async function continuousRetrainingTick(reason = 'interval', force = false) {
  db.continuousRetraining = deepMerge({ enabled: true, running: false, lastRunAt: null, lastResult: null, minIntervalMs: 1800000, policy: 'non-blocking-statistical-policy-retraining' }, db.continuousRetraining || {});
  if (db.continuousRetraining.enabled === false) return { ok: true, skipped: true, reason: 'disabled' };
  if (db.continuousRetraining.running) return { ok: true, skipped: true, reason: 'already-running' };
  const minIntervalMs = Math.max(300000, Number(process.env.NEXUS_RETRAIN_MIN_INTERVAL_MS || db.continuousRetraining.minIntervalMs || 1800000));
  const lastMs = Date.parse(db.continuousRetraining.lastRunAt || '');
  if (!force && Number.isFinite(lastMs) && Date.now() - lastMs < minIntervalMs) return { ok: true, skipped: true, reason: 'too-soon', nextInMs: minIntervalMs - (Date.now() - lastMs) };
  db.continuousRetraining.running = true;
  db.continuousRetraining.lastReason = reason;
  try {
    await new Promise(resolve => setImmediate(resolve));
    syncModelRegistryCacheFromState();
    const trades = verifiedLearningTrades();
    const context = {
      projectRoot: ROOT,
      trades,
      strategyVersion: CURRENT_STRATEGY_VERSION,
      mode: db.mode,
      policy: {
        minTrades: Number(process.env.NEXUS_RETRAIN_MIN_TRADES || 20),
        minSamples: 8,
        validationFraction: 0.30,
        validationMinTrades: 5,
        validationMinProfitFactor: 0.98,
        validationMinExpectancyUsd: -0.005,
        validationMinReliability: 0.12,
        validationMinScore: 42,
        promotionMinScoreDelta: 1.5,
        promotionMinExpectancyDelta: 0,
        promotionMaxPfRegression: 0.15,
        autoRollback: true
      }
    };
    const prepared=await prepareTrainingInWorker(context,{timeoutMs:10000});
    const result=runContinuousRetrainingCycle({...context,prepared});
    db.continuousRetraining.lastRunAt = now();
    db.continuousRetraining.lastResult = result;
    db.continuousRetraining.lastOkAt = now();
    db.modelRegistry = result.registry || registrySnapshot(ROOT);
    const intelligence = refreshStrategyLearningIntelligence('continuous-retraining-' + reason);
    db.strategyQualityAutopilot2 = summarizeStrategyQuality2(intelligence.scorecard, { ...db.modelRegistry, drift: result.drift });
    pushEvent('learning', `Continuous retraining ciklus: ${result.skipped ? result.reason : (result.promotion?.promoted ? 'új champion' : 'candidate értékelve')}.`, { source: 'continuous-retraining-v2', result: { skipped: result.skipped, candidateId: result.candidateId, validation: result.validation, monteCarlo: result.monteCarlo, promotion: result.promotion, drift: result.drift, rollback: result.rollback } });
    await persistLearningState();
    persistSoon('continuous-retraining-v2');
    return result;
  } catch (error) {
    db.continuousRetraining.lastError = error.message || String(error);
    pushIncident('warn', 'Continuous retraining hiba: ' + db.continuousRetraining.lastError, { source: 'continuous-retraining-v2' });
    return { ok: false, error: db.continuousRetraining.lastError };
  } finally {
    db.continuousRetraining.running = false;
  }
}

