const server = http.createServer(async (req, res) => {
  if (req.method === 'OPTIONS') return send(res, 204, {});
  const url = new URL(req.url, 'http://localhost');
  try {
    // v199_168+: cloud health checks bypass every trading/proof/dashboard code path.
    if (url.pathname === '/healthz') return send(res, 200, ultraLightHealthPayload());
    if (url.pathname === '/events') {
      while (clients.size >= MAX_SSE_CLIENTS) {
        const oldest = clients.values().next().value;
        if (!oldest) break;
        clients.delete(oldest);
        try { oldest.end(); } catch {}
      }
      res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive', 'Access-Control-Allow-Origin': '*', 'X-Accel-Buffering': 'no' });
      res.write('retry: 5000\n');
      res.write('data: ' + JSON.stringify({ type: 'hello', payload: compactDashboardLiveDelta(compactDashboardSnapshotSafe('sse-hello')) }) + '\n\n');
      res.__nexusBackpressured = false;
      clients.add(res); req.on('close', () => clients.delete(res)); return;
    }
    if (url.pathname.startsWith('/api/') || url.pathname === '/health') return handleApi(req, res, url);
    return serveStatic(url.pathname, res);
  } catch (error) {
    pushIncident('error', 'Backend hiba: ' + (error.message || String(error)), { source: 'http-handler' });
    persist(); return send(res, 500, { ok: false, error: error.message || String(error) });
  }
});

let shutdownInProgress = false;
async function shutdownAndExit(reason, code = 0) {
  if (shutdownInProgress) return;
  shutdownInProgress = true;
  await gracefulShutdown(reason);
  process.exit(code);
}
server.on('error', error => {
  console.error('[NEXUS] server error', error);
  recordRenderExitDiagnostic('server-error', error, { code: error?.code || '', port: PORT });
  if (CLOUD_EXIT_ON_FATAL || ['EADDRINUSE', 'EACCES'].includes(String(error?.code || ''))) void shutdownAndExit('server-error', 1);
});
process.on('SIGTERM', () => { void shutdownAndExit('SIGTERM', 0); });
process.on('SIGINT', () => { void shutdownAndExit('SIGINT', 0); });
process.on('uncaughtException', error => {
  console.error('[NEXUS] uncaught exception', error);
  recordRenderExitDiagnostic('uncaughtException', error, { exitOnFatal: CLOUD_EXIT_ON_FATAL });
  if (CLOUD_EXIT_ON_FATAL) void shutdownAndExit('uncaughtException', 1);
});
process.on('unhandledRejection', error => {
  console.error('[NEXUS] unhandled rejection', error);
  recordRenderExitDiagnostic('unhandledRejection', error, { exitOnFatal: CLOUD_EXIT_ON_FATAL });
  if (CLOUD_EXIT_ON_FATAL) void shutdownAndExit('unhandledRejection', 1);
});
server.keepAliveTimeout = 65000;
server.headersTimeout = 70000;
server.requestTimeout = 30000;
server.listen(PORT, '0.0.0.0', () => { console.log('NEXUS ' + VERSION + ' running on port ' + PORT); });

