// Server-owned paper lifecycle: no browser request is needed to collect or execute.
let paperStrategyBusy=false,paperStrategyLastSearch=0;
async function paperStrategyRuntimeTick(){
  if(!dbReady || paperStrategyBusy)return;
  paperStrategyBusy=true;
  try{
    const blockedReason=db.killSwitch===true || db.killSwitch?.active===true || db.emergency?'kill-switch-or-emergency':db.autonomousSupervisor?.manualStop?'operator-stop':db.renderRecovery?.recoveryLock || db.renderRecovery?.autoStartBlocked || db.replay?.status==='recovering'?'restart-restore-in-progress':!db.autopilot?'autopilot-disabled':!['paper','staging'].includes(String(db.mode).toLowerCase())?'unsupported-mode-paper-experiment-blocked':null;
    db.paperStrategyRuntime=paperStrategyTick(ROOT,asArray(db.marketSeriesHistory),{blockedReason,trades:verifiedLearningTrades()});
    if(!blockedReason && Date.now()-paperStrategyLastSearch>=900000){
      paperStrategyLastSearch=Date.now();
      const groups=new Map();for(const q of asArray(db.marketSeriesHistory)){if(q.historicalSeed || q.source!=='live_public' || q.quoteObserved!==true)continue;const venue=normalizeVenue(q.venueKey || q.venue),symbol=q.symbol;if(!venue || !symbol)continue;const key=venue+':'+symbol;(groups.get(key) || (groups.set(key,[]),groups.get(key))).push(q);}
      const existing=readRegistry(ROOT).entries.filter(e=>e.paperRuntime && e.status!=='retired');
      for(const [key,quotes] of [...groups].sort((a,b)=>b[1].length-a[1].length).slice(0,4)){
        const [venue,symbol]=key.split(':');if(existing.some(e=>e.artifact.scope.venue===venue && e.artifact.scope.symbol===symbol))continue;
        const report=await prepareStrategyReplayInWorker(quotes,{venue,symbol},{notionalUsd:25,feeRate:0.001,slippageRate:0.0002,minNotional:5,maxGapMs:60000});
        if(!report.skipped)registerPaperStrategy(ROOT,report,CURRENT_STRATEGY_VERSION);
      }
    }
    db.modelRegistry=registrySnapshot(ROOT);await persistLearningState();
    await optionalLearningInfrastructureTick();
  }catch(error){db.paperStrategyRuntime={ok:false,reason:error.message,liveAuthority:false};pushIncident('warn','Paper stratégia ciklus: '+error.message,{source:'paper-strategy-runtime'});}
  finally{paperStrategyBusy=false;}
}
setTimeout(()=>{paperStrategyRuntimeTick();},30000).unref?.();
setInterval(()=>{paperStrategyRuntimeTick();},10000).unref?.();

let infrastructureBusy=false,infrastructureLastArchiveAt=0;
let monitoringCache=null,modelArchive=null;
async function optionalLearningInfrastructureTick(){
  if(infrastructureBusy)return;infrastructureBusy=true;
  try{
    if(!monitoringCache)monitoringCache=new RedisRestHotCache({url:process.env.NEXUS_REDIS_REST_URL || '',token:process.env.NEXUS_REDIS_REST_TOKEN || ''});
    if(monitoringCache.status.configured){await monitoringCache.put('paper-strategies',db.paperStrategyRuntime,60);const echo=await monitoringCache.get('paper-strategies');db.monitoringCacheStatus={configured:true,verified:modelFingerprint(echo)===modelFingerprint(db.paperStrategyRuntime),lastVerifiedAt:now(),scope:'monitoring-only'};}
    else db.monitoringCacheStatus={configured:false,verified:false,reason:'optional-redis-rest-not-configured'};
    if(!modelArchive)modelArchive=new SupabaseArtifactArchive({url:process.env.SUPABASE_URL || '',key:process.env.SUPABASE_SERVICE_ROLE_KEY || '',bucket:process.env.NEXUS_ARCHIVE_BUCKET || ''});
    if(modelArchive.configured && Date.now()-infrastructureLastArchiveAt>=1800000){const saved=await modelArchive.save(exportDurableBundle(ROOT,activePolicyConfig()));db.modelArchiveStatus={...saved,lastVerifiedAt:now()};infrastructureLastArchiveAt=Date.now();}
    else if(!modelArchive.configured)db.modelArchiveStatus={configured:false,verified:false,reason:'optional-private-archive-bucket-not-configured'};
  }catch(error){db.optionalInfrastructureError={reason:error.message,at:now()};}
  finally{infrastructureBusy=false;}
}
